window.QUESTIONS=[{"id":"C1-001","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “Triết học là… về thế giới và vị trí con người, trong thế giới đó, là khoa học về sự vận động, phát triển chung nhất của tự nhiên, xã hội và tư duy”.","opts":["Hệ thống quan điểm duy nhất","Hệ thống lý luận về quan điểm","Hệ thống lý luận chung nhất","Hệ thống luận điểm duy nhất"],"ans":2,"ex":"Giáo trình định nghĩa **triết học** là hệ thống lý luận chung nhất về thế giới và vị trí con người trong thế giới, đồng thời là khoa học về những quy luật vận động, phát triển chung nhất của tự nhiên, xã hội và tư duy. Điểm cốt lõi là triết học là tri thức **lý luận** có tính **khái quát cao nhất**, không phải một quan điểm hay luận điểm “duy nhất” nào. Các phương án có chữ “duy nhất” sai vì triết học có nhiều trường phái khác nhau."},{"id":"C1-002","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “… là hệ thống lý luận chung nhất về thế giới và vị trí con người, trong thế giới đó, là khoa học về sự vận động, phát triển chung nhất của tự nhiên, xã hội và tư duy”.","opts":["Thế giới quan","Triết học","Phương pháp luận","Chủ nghĩa duy vật biện chứng"],"ans":1,"ex":"Đây là định nghĩa chung về **triết học** trong giáo trình: hệ thống lý luận chung nhất về thế giới và vị trí con người, khoa học về quy luật chung nhất của tự nhiên, xã hội và tư duy. Thế giới quan là khái niệm rộng hơn (gồm cả tri thức, niềm tin, tình cảm), phương pháp luận là lý luận về phương pháp, còn chủ nghĩa duy vật biện chứng chỉ là một hình thức cụ thể của triết học."},{"id":"C1-003","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Triết học là hệ thống quan điểm lý luận chung nhất về thế giới và vị trí của con người trong thế giới đó, là khoa học về những quy luật vận động và phát triển chung nhất của tự nhiên, xã hội và tư duy. Cụm từ “Chung nhất” trong câu trên, muốn nói đến điều gì của triết học?","opts":["Triết học là lý luận về tất cả mọi lĩnh vực","Triết học là lý luận mang tính khái quát cao","Triết học là một lý luận duy nhất","Triết học là một lý luận tốt nhất"],"ans":1,"ex":"Cụm từ “chung nhất” nói lên **tính khái quát cao** của tri thức triết học: triết học không đi vào từng lĩnh vực cụ thể như các khoa học chuyên ngành mà khái quát những quy luật phổ biến nhất của thế giới. Vì vậy hiểu triết học là lý luận “về tất cả mọi lĩnh vực” là sai, bởi nó không thay thế các khoa học cụ thể; càng không có nghĩa triết học là “duy nhất” hay “tốt nhất”."},{"id":"C1-004","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Tư duy triết học bắt đầu từ đâu?","opts":["Từ những lực lượng siêu nhiên ở bên ngoài chi phối nhận thức của con người","Từ những cảm giác, nhận thức chủ quan của con người","Từ các triết lý, từ sự khôn ngoan, từ tình yêu sự thông thái dần hình thành các hệ thống những tri thức chung nhất về thế giới.","Cả ba phương án trên đều đúng"],"ans":2,"ex":"Theo giáo trình, triết học ra đời vào khoảng thế kỷ VIII–VI TCN ở Ấn Độ, Trung Quốc, Hy Lạp; tư duy triết học bắt đầu từ các **triết lý**, từ sự khôn ngoan, từ **tình yêu sự thông thái** (philosophia), rồi dần hình thành hệ thống tri thức chung nhất về thế giới. Giải thích bằng lực lượng siêu nhiên là đặc trưng của thần thoại, tôn giáo; cảm giác chủ quan chưa phải tư duy lý luận."},{"id":"C1-005","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Tầng lớp trí thức có vai trò như thế nào đối với sự hình thành của triết học?","opts":["Không có vai trò gì, bởi triết học đã được hình thành từ trước khi tầng lớp này ra đời","Chỉ có vai trò truyền bá những tư tưởng triết học hình thành trong nhân dân","Sáng tác những câu chuyện thần thoại mang triết lý về cuộc sống","Khái quát những hiểu biết của con người về thế giới thành lý luận"],"ans":3,"ex":"Triết học ra đời có **nguồn gốc nhận thức** và **nguồn gốc xã hội**. Về mặt xã hội, khi lao động trí óc tách khỏi lao động chân tay, xuất hiện **tầng lớp trí thức** có điều kiện nghiên cứu, hệ thống hóa, khái quát những hiểu biết của con người về thế giới thành lý luận. Vì vậy trí thức không chỉ truyền bá mà chính là chủ thể sáng tạo hệ thống triết học; sáng tác thần thoại là đặc trưng của thế giới quan thần thoại."},{"id":"C1-006","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chọn nhận định đúng về vai trò của triết học đối với đời sống xã hội.","opts":["Tạo ra của cải vật chất","Tăng năng suất lao động","Ổn định trật tự xã hội","Tạo cơ sở đúng đắn cho việc thực hiện những điều trên"],"ans":3,"ex":"Triết học không trực tiếp tạo ra của cải, tăng năng suất hay giữ trật tự xã hội, mà với chức năng **thế giới quan** và **phương pháp luận**, nó cung cấp cơ sở lý luận đúng đắn để con người nhận thức và cải tạo thế giới. Nhờ đó, các hoạt động sản xuất, quản lý xã hội được định hướng hiệu quả. Các phương án A, B, C là kết quả gián tiếp của hoạt động thực tiễn có triết học định hướng."},{"id":"C1-007","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “… là khái niệm triết học dùng để chỉ hệ thống các tri thức, quan điểm, tình cảm, niềm tin, lý tưởng xác định về thế giới và vị trí con người trong thế giới đó”.","opts":["Phương pháp luận","Thế giới quan","Chủ nghĩa duy vật","Chủ nghĩa duy tâm"],"ans":1,"ex":"**Thế giới quan** là khái niệm chỉ hệ thống các tri thức, quan điểm, tình cảm, niềm tin, lý tưởng xác định về thế giới và vị trí con người trong thế giới đó; nó quy định nguyên tắc, thái độ, giá trị trong định hướng nhận thức và hoạt động. **Phương pháp luận** là lý luận về phương pháp; chủ nghĩa duy vật và duy tâm là các trường phái triết học, tức các hình thức thế giới quan cụ thể."},{"id":"C1-008","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: ‘Thế giới quan là khái niệm triết học dùng để chỉ hệ thống các tri thức, quan điểm, tình cảm, niềm tin, lý tưởng xác định về…trong thế giới đó”.","opts":["Vũ trụ và tầm vóc của con người","Xã hội và vai trò của con người","Thế giới loài người và loài người","Thế giới và vị trí của con người"],"ans":3,"ex":"Đối tượng mà thế giới quan hướng tới là **thế giới** (tự nhiên, xã hội, tư duy) và **vị trí của con người** trong thế giới đó. Định nghĩa này nhấn mạnh thế giới quan luôn bao hàm câu hỏi về quan hệ con người – thế giới. Các phương án khác thu hẹp đối tượng (chỉ vũ trụ, chỉ xã hội) hoặc diễn đạt không đúng với giáo trình."},{"id":"C1-009","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thế giới quan có thể được hiểu một cách ngắn gọn là:","opts":["Hệ thống quan điểm của con người về thế giới","Bức tranh chung về thế giới","Cảm nhận về thế giới","Nhận thức chung về cuộc đời"],"ans":0,"ex":"Hiểu ngắn gọn, **thế giới quan** là **hệ thống quan điểm của con người về thế giới**, bao gồm cả quan điểm về vị trí của con người trong thế giới. Nó không chỉ là “bức tranh” hay “cảm nhận” rời rạc, mà là những quan điểm có tính hệ thống, thống nhất giữa tri thức, niềm tin và lý tưởng, đóng vai trò định hướng cho hoạt động của con người."},{"id":"C1-010","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thế giới quan quy định điều gì trong việc định hướng nhận thức và hoạt động thực tiễn của con người?","opts":["Các nguyên tắc, thái độ, giá trị","Các nguyên nhân, mức độ và giá trị","Điều kiện, nền tảng và cách thức","Điều kiện, giá trị và điều lệ"],"ans":0,"ex":"Giáo trình chỉ rõ thế giới quan quy định **các nguyên tắc, thái độ, giá trị** trong định hướng nhận thức và hoạt động thực tiễn của con người. Nói cách khác, thế giới quan là “la bàn” định hướng: con người nhìn thế giới thế nào thì sẽ hành động theo nguyên tắc, thái độ và thang giá trị tương ứng. Các phương án còn lại không phải là nội dung được giáo trình nêu."},{"id":"C1-011","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Sự hình thành các trường phái khác nhau trong triết học xuất phát từ sự khác biệt về:","opts":["Trình độ tư duy","Giai cấp","Thế giới quan","Vị trí địa lý"],"ans":2,"ex":"Các trường phái triết học hình thành từ cách giải quyết khác nhau **vấn đề cơ bản của triết học**, tức sự khác biệt về **thế giới quan**: coi vật chất hay ý thức là cái có trước, quyết định, và con người có nhận thức được thế giới hay không. Từ đó phân thành duy vật, duy tâm, nhị nguyên, khả tri, bất khả tri. Trình độ tư duy, giai cấp hay địa lý chỉ là yếu tố ảnh hưởng, không phải tiêu chí phân chia trực tiếp."},{"id":"C1-012","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thế giới quan đúng đắn là một thế giới quan như thế nào?","opts":["Thế giới quan phù hợp với cách nghĩ của chủ thể nhận thức","Thế giới quan phù hợp với tâm lý chung của xã hội","Thế giới quan đúng với đạo đức xã hội","Thế giới quan phù hợp với hiện thực khách quan"],"ans":3,"ex":"Theo lập trường duy vật biện chứng, **thế giới quan đúng đắn** là thế giới quan phản ánh đúng **hiện thực khách quan**, tức phù hợp với bản chất và quy luật vốn có của thế giới. Thế giới quan khoa học là cơ sở để con người hoạt động thực tiễn có hiệu quả. Các tiêu chí như cách nghĩ của chủ thể, tâm lý xã hội hay đạo đức đều mang tính chủ quan, không bảo đảm tính đúng đắn."},{"id":"C1-013","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thế giới quan và nhân sinh quan có mối quan hệ như thế nào?","opts":["Thế giới quan bao hàm cả nhân sinh quan","Thế giới quan đối lập với nhân sinh quan","Thế giới quan xuất không có mối liên hệ với nhân sinh quan","Thế giới quan là một phần của nhân sinh quan."],"ans":0,"ex":"**Nhân sinh quan** là quan niệm về cuộc sống, ý nghĩa, mục đích sống của con người; nó là một bộ phận của thế giới quan, vì thế giới quan bàn về thế giới và cả vị trí con người trong đó. Do vậy, thế giới quan **bao hàm** nhân sinh quan. Coi hai khái niệm đối lập, không liên hệ, hay coi thế giới quan là một phần của nhân sinh quan đều sai."},{"id":"C1-014","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Triết học có vai trò như thế nào đối với thế giới quan?","opts":["Là linh hồn của thế giới quan","Là nguyên nhân – lý luận của thế giới quan","Là hạt nhân – lý luận của thế giới quan","Là vấn đề cơ bản của thế giới quan"],"ans":2,"ex":"Giáo trình khẳng định triết học là **hạt nhân lý luận của thế giới quan**. Trong thế giới quan có nhiều thành phần (tri thức khoa học, đạo đức, thẩm mỹ, tôn giáo…), triết học là thành phần quan trọng nhất, đóng vai trò cốt lõi vì nó cung cấp quan điểm chung nhất, có hệ thống và lý luận. Các cách diễn đạt “linh hồn”, “nguyên nhân”, “vấn đề cơ bản” không đúng thuật ngữ giáo trình."},{"id":"C1-015","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Triết học là hạt nhân của thế giới quan được hiểu là:","opts":["Triết học có chức năng xây dựng thế giới quan","Thế giới quan là một giai đoạn phát triển cao của triết học","Không thể xuất hiện thế giới quan nào nếu không có triết học","Thế giới quan bao trùm cả triết học"],"ans":0,"ex":"Nói triết học là **hạt nhân của thế giới quan** nghĩa là triết học giữ vai trò cốt lõi, có **chức năng xây dựng thế giới quan**: định hướng, hệ thống hóa và nâng các quan điểm về thế giới lên trình độ lý luận. Thế giới quan không phải là giai đoạn cao của triết học; và vẫn có thế giới quan không có triết học (thần thoại, tôn giáo), nên phương án C sai."},{"id":"C1-016","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Theo F. Ăngghen, vấn đề cơ bản lớn của mọi triết học, đặc biệt là của triết học hiện đại là:","opts":["Vấn đề quan hệ giữa mặt hạn chế và mặt tồn tại","Vấn đề quan hệ giữa biện chứng và siêu hình","Vấn đề quan hệ giữa tư duy với tồn tại","Vấn đề quan hệ giữa con người với thế giới"],"ans":2,"ex":"Trong tác phẩm **“Lútvích Phoiơbắc và sự cáo chung của triết học cổ điển Đức”**, Ph. Ăngghen viết: vấn đề cơ bản lớn của mọi triết học, nhất là triết học hiện đại, là **quan hệ giữa tư duy với tồn tại**. Đây chính là quan hệ giữa ý thức và vật chất; việc giải quyết nó là cơ sở để phân chia các trường phái và xác định lập trường của các hệ thống triết học."},{"id":"C1-017","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Mối quan hệ giữa tư duy và tồn tại là muốn nói đến mối quan hệ giữa hai yếu tố nào?","opts":["Những vấn đề không tồn tại và những vấn đề đang tồn tại","Ý thức và sự tồn vong","Ý thức và vật chất","Thế giới ảo và thế giới thực"],"ans":2,"ex":"Trong vấn đề cơ bản của triết học, **tư duy** chỉ ý thức, tinh thần; **tồn tại** chỉ vật chất, giới tự nhiên. Vì vậy quan hệ tư duy – tồn tại chính là quan hệ giữa **ý thức và vật chất**. Các phương án như “sự tồn vong” hay “thế giới ảo – thế giới thực” là hiểu sai nghĩa triết học của các thuật ngữ này."},{"id":"C1-018","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Hai mặt trong vấn đề cơ bản của triết học là:","opts":["Khả tri luận và bất khả tri luận","Nhị nguyên luận và nhất nguyên luận","Bản thể luận và nhận thức luận","Hoài nghi luận và ý thức luận"],"ans":2,"ex":"Vấn đề cơ bản của triết học có hai mặt: **mặt thứ nhất (bản thể luận)** trả lời giữa vật chất và ý thức cái nào có trước, cái nào quyết định; **mặt thứ hai (nhận thức luận)** trả lời con người có nhận thức được thế giới hay không. Khả tri – bất khả tri hay nhất nguyên – nhị nguyên chỉ là các lập trường nảy sinh khi giải quyết từng mặt, không phải bản thân hai mặt."},{"id":"C1-019","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Bản thể luận trong vấn đề cơ bản của triết học được hiểu là:","opts":["Bàn luận về bản chất con người","Bàn về bản chất của triết học","Bàn về yếu tố đầu tiên hình thành và quyết định thế giới","Bàn về thể thức nghiên cứu của triết học"],"ans":2,"ex":"**Bản thể luận** là học thuyết về bản thể, tức cái tồn tại đầu tiên, nền tảng. Trong vấn đề cơ bản của triết học, mặt bản thể luận bàn về yếu tố có trước, sinh ra và quyết định thế giới: vật chất hay ý thức. Nó không bàn riêng về bản chất con người hay bản chất của triết học."},{"id":"C1-020","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Mặt bản thể luận trong vấn đề cơ bản của triết học giải quyết nội dung gì?","opts":["Mối quan hệ giữa con người với thế giới","Mối quan hệ giữa vật chất và ý thức","Mối quan hệ giữa bản chất và hiện tượng","Mối quan hệ giữa thực thể tự nhiên và thực thể xã hội"],"ans":1,"ex":"Mặt **bản thể luận** giải quyết **mối quan hệ giữa vật chất và ý thức** xét về tính thứ nhất: cái nào có trước, cái nào quyết định. Cách giải quyết này chia triết học thành chủ nghĩa duy vật (vật chất có trước) và chủ nghĩa duy tâm (ý thức có trước), ngoài ra có nhị nguyên luận. Quan hệ bản chất – hiện tượng là một cặp phạm trù của phép biện chứng, không phải nội dung này."},{"id":"C1-021","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Mặt bản thể luận trong vấn đề cơ bản của triết học trả lời cho câu hỏi lớn nào?","opts":["Giữa vật chất và ý thức, các nào có trước, cái nào có sau, cái nào phủ định cái nào?","Giữa vật chất và ý thức, cái nào quan trọng hơn?","Gữa vật chất và ý thức, cái nào quyết định cái còn lại?","Giữa vật chất và ý thức, cái nào có trước, cái nào có sau, cái nào quyết định cái nào?"],"ans":3,"ex":"Câu hỏi của mặt **bản thể luận** là: giữa vật chất và ý thức, **cái nào có trước, cái nào có sau, cái nào quyết định cái nào**? Câu hỏi đầy đủ gồm cả tính có trước (nguồn gốc) và vai trò quyết định. Phương án B chỉ hỏi “quan trọng hơn”, C thiếu vế có trước có sau, A dùng “phủ định” là không đúng."},{"id":"C1-022","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Mặt nhận thức luận trong vấn đề cơ bản của triết học giải quyết nội dung gì?","opts":["Luận giải về nguồn gốc của ý thức","Xem xét khả năng tư duy trừu tượng của con người về bản thân mình","Khả năng nhận thức của con người về thế giới","Bàn luận về nguồn gốc của thế giới"],"ans":2,"ex":"Mặt **nhận thức luận** (mặt thứ hai) giải quyết vấn đề **khả năng nhận thức của con người về thế giới**. Trả lời khẳng định là **thuyết khả tri**, phủ nhận là **thuyết bất khả tri**, còn hoài nghi luận nghi ngờ khả năng ấy. Nguồn gốc của ý thức hay của thế giới thuộc phạm vi mặt bản thể luận."},{"id":"C1-023","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Mặt nhận thức luận trong vấn đề cơ bản của triết học trả lời cho câu hỏi lớn nào?","opts":["Con người có khả năng thâu tóm được thế giới hay không?","Con người có khả năng nhận thức được thế giới hay không?","Con người có khả năng chế ngự được giới tự nhiên hay không?","Con người có khả năng tồn tại trong thế giới hay không?"],"ans":1,"ex":"Mặt **nhận thức luận** trả lời câu hỏi: **con người có khả năng nhận thức được thế giới hay không?** Chủ nghĩa duy vật biện chứng theo thuyết khả tri, khẳng định con người có thể nhận thức thế giới thông qua thực tiễn. “Thâu tóm”, “chế ngự” hay “tồn tại” trong thế giới không phải vấn đề nhận thức luận."},{"id":"C1-024","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Việc giải quyết vấn đề cơ bản có ảnh hưởng như thế nào đến sự phát triển của triết học?","opts":["Cơ bản giải quyết xong mọi vấn đề của triết học","Bàn luận những vấn đề của khoa học cơ bản trong triết học","Giải quyết tranh cãi xem vật chất có trước hay có sau","Tạo tiền tề cho việc hình thành các trường phái triết học"],"ans":3,"ex":"Cách giải quyết **vấn đề cơ bản của triết học** là tiêu chuẩn để phân chia và hình thành các **trường phái triết học**: duy vật – duy tâm – nhị nguyên (mặt thứ nhất), khả tri – bất khả tri (mặt thứ hai). Nó không “giải quyết xong mọi vấn đề” của triết học, mà là điểm xuất phát, nền tảng để giải quyết các vấn đề khác."},{"id":"C1-025","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chủ nghĩa duy tâm có những trường phái nào?","opts":["Duy tâm thần bí và duy tầm siêu hình","Duy tâm khách quan và duy tâm chủ quan","Duy tâm biện chứng và duy tâm siêu hình","Duy tâm thần thánh và duy tâm con người"],"ans":1,"ex":"Chủ nghĩa duy tâm có hai hình thức: **duy tâm chủ quan** (coi cảm giác, ý thức cá nhân là tính thứ nhất, tiêu biểu Béccơli) và **duy tâm khách quan** (coi “ý niệm”, “tinh thần tuyệt đối” tồn tại ngoài con người là tính thứ nhất, tiêu biểu Platôn, Hêghen). Biện chứng – siêu hình là phương pháp tư duy, không phải tiêu chí phân chia hình thức duy tâm."},{"id":"C1-026","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Quan niệm: “Sống chết có mệnh, giàu sang do trời” của Khổng Tử phản ánh thế giới quan của trường phái triết học nào?","opts":["Duy tâm chủ quan","Duy tâm khách quan","Duy vật siêu hình","Duy vật cổ đại"],"ans":1,"ex":"Quan niệm cho rằng sống chết, giàu sang do **“mệnh”, “trời”** định đoạt là coi một lực lượng tinh thần siêu nhiên, tồn tại khách quan bên ngoài con người, chi phối thế giới. Đó là lập trường **duy tâm khách quan**. Không phải duy tâm chủ quan, vì cái quyết định không phải cảm giác hay ý thức của cá nhân."},{"id":"C1-027","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chủ nghĩa duy vật có những trường phái nào?","opts":["Duy vật siêu hình và duy vật biện chứng","Duy vật chất phác và duy vật siêu hình","Duy vật chất phác thời cổ đại, duy vật siêu hình và duy vật biện chứng","Duy vật chất phác và duy vật biện chứng"],"ans":2,"ex":"Giáo trình nêu ba hình thức lịch sử của chủ nghĩa duy vật: **duy vật chất phác** thời cổ đại (đồng nhất vật chất với một vật thể cụ thể như nước, lửa…), **duy vật siêu hình** thế kỷ XVII–XVIII (xem xét thế giới tách rời, tĩnh tại, máy móc) và **duy vật biện chứng** do C. Mác, Ph. Ăngghen sáng lập, V.I. Lênin phát triển. Các phương án khác thiếu một hình thức."},{"id":"C1-028","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chủ nghĩa duy vật lịch sử là kết quả của hoạt động nào?","opts":["Nghiên cứu sự phát triển của chủ nghĩa duy vật trong lịch sử","Nghiên cứu những quan điểm duy vật trong lịch sử","Vận dụng và mở rộng quan điểm duy vật biện chứng vào nghiên cứu lịch sử xã hội","Vận dụng lịch sử trong việc nghiên cứu những vấn đề triết học duy vật"],"ans":2,"ex":"**Chủ nghĩa duy vật lịch sử** là kết quả của việc C. Mác và Ph. Ăngghen **vận dụng và mở rộng quan điểm duy vật biện chứng vào nghiên cứu lịch sử xã hội**. Nhờ đó, chủ nghĩa duy vật được hoàn bị cả trong lĩnh vực xã hội, khắc phục quan điểm duy tâm về lịch sử của các triết học trước. Nó không phải là việc nghiên cứu lịch sử của chủ nghĩa duy vật."},{"id":"C1-029","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Câu thành ngữ “Phú quý sinh lễ nghĩa” phản ánh quan điểm của trường phái triết học nào?","opts":["Chủ nghĩa duy vật","Chủ nghĩa duy tâm","Nhị nguyên luận","Không thuộc trường phái nào"],"ans":0,"ex":"Thành ngữ **“Phú quý sinh lễ nghĩa”** cho rằng điều kiện vật chất đầy đủ mới làm nảy sinh lễ nghĩa, tức đời sống vật chất quyết định đời sống tinh thần. Đây là tư tưởng **duy vật** mộc mạc trong dân gian, gần với luận điểm tồn tại xã hội quyết định ý thức xã hội."},{"id":"C1-030","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chủ nghĩa duy tâm giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học như thế nào?","opts":["Vật chất và ý thức sinh ra đồng thời và nương tựa vào nhau biến đổi","Thế giới tinh thần có trước và quyết định sự tồn tại của thế giới vật chất","Thế giới tinh thần là sản phẩm của các yếu tố vật chất","Thế giới tinh thần là thế giới duy nhất tồn tại vĩnh hằng"],"ans":1,"ex":"**Chủ nghĩa duy tâm** cho rằng ý thức, tinh thần là cái có trước, sinh ra và quyết định giới tự nhiên, vật chất. Duy tâm khách quan coi đó là tinh thần khách quan (ý niệm, tinh thần tuyệt đối), duy tâm chủ quan coi đó là cảm giác, ý thức cá nhân. Phương án A là quan điểm nhị nguyên, C là quan điểm duy vật."},{"id":"C1-031","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Chủ nghĩa duy vật giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học như thế nào?","opts":["Vật chất là cái có trước, vật chất quyết định ý thức","Thế giới tinh thần có trước và quyết định sự tồn tại của thế giới vật chất","Vật chất và ý thức sinh ra đồng thời và nương tựa vào nhau biến đổi","Thế giới tinh thần là thế giới duy nhất tồn tại vĩnh hằng"],"ans":0,"ex":"**Chủ nghĩa duy vật** khẳng định **vật chất có trước, ý thức có sau, vật chất quyết định ý thức**; ý thức là sự phản ánh thế giới vật chất. Đây là lập trường nhất nguyên duy vật. Phương án B và D là duy tâm, C là nhị nguyên luận."},{"id":"C1-032","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Do con người không thể nhận thức được tất cả các sự vật, hiện tượng trong vũ trụ rộng lớn, nên việc giải quyết mặt bản thể luận trong vấn đề cơ bản của triết học cần theo hướng nào?","opts":["Cần phải làm rõ vật chất và ý thức cái nào có trước, cái nào có sau để tiếp tục nghiên cứu về thế giới","Thừa nhận vật chất và ý thức đều cùng xuất hiện và chi phối lẫn nhau vì thực tế là như vậy","Không cần xác định vật chất hay ý thức có trước hay có sau, chỉ cần thừa nhận sự tồn tại của nó trong thế giới và tiếp tục nghiên cứu.","Xác định một cách tương đối, nếu như có những phát hiện mới về vật chất và ý thức thì xác định lại."],"ans":0,"ex":"Dù con người không nhận thức hết vũ trụ, triết học vẫn phải xác định rõ **tính thứ nhất**: vật chất hay ý thức có trước, cái nào quyết định, vì đây là nền tảng thế giới quan để nghiên cứu tiếp. Né tránh vấn đề (C) hoặc coi hai cái cùng xuất hiện (B, nhị nguyên) đều không giải quyết được. Tính vô tận của thế giới không làm mất đi tính tất yếu phải trả lời vấn đề cơ bản."},{"id":"C1-033","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Nhận định nào đúng về khả năng nhận thức của con người đối với thế giới khách quan?","opts":["Con người không thể nhận thức được thế giới khách quan","Con người có thể nhận thức đầy đủ về thế giới khách quan","Con người hiện tại chưa thể nhận thức được thế giới khách quan","Con người hoàn toàn nhận thức được thế giới khách quan nhưng sẽ không đầy đủ"],"ans":3,"ex":"Theo **thuyết khả tri** của chủ nghĩa duy vật biện chứng, con người có khả năng nhận thức được thế giới khách quan; nhưng nhận thức là quá trình đi từ chưa biết đến biết, từ biết ít đến biết nhiều, nên tri thức ở mỗi thời điểm luôn mang tính tương đối, **chưa đầy đủ**. Vì vậy vừa phủ nhận bất khả tri (A, C) vừa không tuyệt đối hóa khả năng nhận thức (B)."},{"id":"C1-034","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Câu thành ngữ “Ếch ngồi đáy giếng, coi trời bằng vung” thể hiện vấn đề gì về thế giới quan?","opts":["Người có nhận thức sai lầm","Người có nhận thức lệch lạc","Người ít hiểu biết, kiến thức nông cạn do điều kiện tiếp xúc hạn hẹp; người ngông nghênh, tự phụ, phiến diện.","Người có nhận thức cảm tính"],"ans":2,"ex":"Thành ngữ chỉ người có tầm nhìn hạn hẹp do **điều kiện tiếp xúc hạn chế**, từ đó dẫn tới hiểu biết nông cạn, tự phụ, phiến diện. Về triết học, nó minh họa việc thế giới quan bị quy định bởi điều kiện sống và thực tiễn của chủ thể; thiếu tri thức thì thế giới quan dễ chủ quan, phiến diện. Phương án C đầy đủ nhất, các phương án khác chỉ nêu một khía cạnh chung chung."},{"id":"C1-035","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Lý luận khái quát các quan điểm, nguyên tắc chung nhất để lấy cơ sở xác định các phương pháp luận ngành, phương pháp luận chung và các phương pháp hoạt động cụ thể của nhận thức và thực tiễn”. Luận giải trên đang nói đến vấn đề nào?","opts":["Thế giới quan khoa học","Phương pháp luận","Thế giới quan triết học","Phương pháp luận triết học"],"ans":3,"ex":"**Phương pháp luận triết học** là phương pháp luận chung nhất, khái quát các quan điểm, nguyên tắc chung nhất làm cơ sở xác định phương pháp luận ngành, phương pháp luận chung và các phương pháp cụ thể. Giáo trình phân phương pháp luận thành ba cấp: ngành, chung và chung nhất (triết học). Phương án B quá rộng, không chỉ đúng cấp độ chung nhất."},{"id":"C1-036","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Trong triết học, có hai phương pháp tư duy chung nhất đối lập nhau đó là:","opts":["Phương pháp quy nạp và phương pháp diễn dịch","Phương pháp chứng minh và phương pháp phản chứng","Phương pháp trừu tượng và phương pháp cụ thể","Phương pháp biện chứng và phương pháp siêu hình"],"ans":3,"ex":"Trong lịch sử triết học có hai phương pháp tư duy chung nhất đối lập: **phương pháp biện chứng** (xem xét sự vật trong mối liên hệ, vận động, phát triển) và **phương pháp siêu hình** (xem xét sự vật cô lập, tĩnh tại). Quy nạp – diễn dịch, trừu tượng – cụ thể là những phương pháp nhận thức cụ thể, không phải phương pháp chung nhất."},{"id":"C1-037","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Khi vận dụng, phương pháp tư duy biện chứng sẽ ưu việt hơn phương pháp tư duy siêu hình ở điểm nào?","opts":["Có cái nhìn một chiều, sâu sắc hơn","Có cái nhìn đa chiều, đầy đủ hơn","Đầy đủ chứng cứ hơn","Tính phản biện cao hơn"],"ans":1,"ex":"**Phương pháp biện chứng** xem xét sự vật trong các mối liên hệ phổ biến, trong vận động và phát triển, nên đem lại cái nhìn **đa chiều, toàn diện, đầy đủ hơn**. Ăngghen nói phương pháp siêu hình “chỉ thấy cây mà không thấy rừng”. Phương án A mô tả đặc điểm một chiều của siêu hình; “chứng cứ” hay “phản biện” không phải tiêu chí phân biệt."},{"id":"C1-038","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Người học cần vận dụng phương pháp tư duy nào trong triết học Mác – Lênin để có thể đánh giá sự vật, hiện tượng hoặc hành động đúng đắn, khách quan và khoa học?","opts":["Tư duy trừu tượng","Phương pháp tư duy siêu hình","Tư duy phiến diện","Phương pháp tư duy biện chứng"],"ans":3,"ex":"Để đánh giá sự vật khách quan, khoa học, cần vận dụng **phương pháp tư duy biện chứng duy vật**, với các nguyên tắc toàn diện, lịch sử – cụ thể, phát triển. Phương pháp siêu hình và tư duy phiến diện dẫn tới cái nhìn tách rời, tuyệt đối hóa. Tư duy trừu tượng chỉ là một năng lực nhận thức, không phải phương pháp luận triết học."},{"id":"C1-039","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Ông cha ta có câu: “Không thầy đố mày làm nên”, đồng thời lại có câu “Học thầy không tày học bạn” điều này thể hiện tư duy gì của người Việt Nam?","opts":["Siêu hình, tuyệt đối hóa một chiều","Biện chứng","Duy tâm","Duy vật"],"ans":1,"ex":"Hai câu tục ngữ tưởng như mâu thuẫn nhưng thực chất bổ sung nhau: vừa đề cao vai trò của thầy, vừa coi trọng học hỏi từ bạn. Đây là lối tư duy **biện chứng**, xem xét vấn đề nhiều mặt, không tuyệt đối hóa một phía. Nếu chỉ chấp nhận một vế và bác bỏ vế kia thì mới là tư duy siêu hình."},{"id":"C1-040","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Các hình thức cơ bản của phép biện chứng trong lịch sử là:","opts":["Phép biện chứng tự phát, phép biện chứng duy tâm và phép biện chứng duy vật","Phép biện chứng tự nhiên, phép biện chứng xã hội và phép biện chứng tư duy","Phép biện chứng khách quan, phép biện chứng chủ quan và phép biện chứng duy ý chí","Phép biện chứng toàn diện, phép biện chứng cụ thể và phép biện chứng lịch sử"],"ans":0,"ex":"Giáo trình chỉ ra ba hình thức cơ bản của phép biện chứng: **biện chứng tự phát** thời cổ đại (Hêraclít, Lão Tử…), **biện chứng duy tâm** cổ điển Đức (đỉnh cao là Hêghen) và **biện chứng duy vật** do Mác – Ăngghen sáng lập. Biện chứng khách quan – chủ quan là cặp khái niệm khác, không phải các hình thức lịch sử."},{"id":"C1-041","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Các nhà sáng lập triết học Mác – Lênin đã kế thừa “hạt nhân hợp lý” trong triết học của Hêghen để trực tiếp xây dựng nên lý luận nào?","opts":["Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy vật lịch sử","Phép biện chứng duy vật","Tất cả các phương án trên đều sai"],"ans":2,"ex":"Mác và Ăngghen đã phê phán tính duy tâm thần bí trong triết học **Hêghen** nhưng kế thừa **“hạt nhân hợp lý”** là phép biện chứng, cải tạo nó trên lập trường duy vật để xây dựng nên **phép biện chứng duy vật**. Mác viết rằng ở Hêghen phép biện chứng “bị lộn ngược đầu xuống đất”, cần dựng nó lại. Chủ nghĩa duy vật thì kế thừa chủ yếu từ Phoiơbắc."},{"id":"C1-042","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “… là hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","opts":["Triết học","Triết học hiện sinh","Triết học Mác - Lênin","Triết học cổ điển Anh"],"ans":2,"ex":"Đây là định nghĩa **triết học Mác – Lênin** trong giáo trình: hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy, là thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động và các lực lượng xã hội tiến bộ. Dấu hiệu nhận biết là lập trường **duy vật biện chứng** và tính giai cấp công nhân."},{"id":"C1-043","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Trong ba bộ phận cấu thành nên chủ nghĩa Mác - Lênin, bộ phận nào giữ vai trò là thế giới quan và phương pháp luận chung nhất?","opts":["Triết học Mác - Lênin","Kinh tế chính trị Mác – Lênin","Chủ nghĩa xã hội khoa học","Chủ nghĩa duy vật lịch sử"],"ans":0,"ex":"Chủ nghĩa Mác – Lênin gồm ba bộ phận: **triết học**, **kinh tế chính trị** và **chủ nghĩa xã hội khoa học**. Trong đó, **triết học Mác – Lênin** giữ vai trò thế giới quan và phương pháp luận chung nhất, là cơ sở lý luận cho hai bộ phận còn lại. Chủ nghĩa duy vật lịch sử là một bộ phận của triết học Mác chứ không phải bộ phận độc lập của chủ nghĩa Mác – Lênin."},{"id":"C1-044","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Những thành tựu của khoa học tự nhiên (Định luật bảo toàn và chuyển hóa năng lượng, thuyết tiến hóa và thuyết tế bào) đã cung cấp tiền đề gì cho C. Mác và Ph. Ăngghen xây dựng triết học duy vật biện chứng?","opts":["Làm rõ tính thống nhất vật chất của thế giới","Làm rõ nguồn gốc của loài người","Chứng minh sự thống nhất khoa học tự nhiên và triết học","Chứng minh triết học là khoa học của mọi khoa học"],"ans":0,"ex":"Ba phát minh lớn của khoa học tự nhiên thế kỷ XIX – **định luật bảo toàn và chuyển hóa năng lượng**, **học thuyết tế bào**, **thuyết tiến hóa** của Đácuyn – đã chứng minh **tính thống nhất vật chất** và mối liên hệ, sự chuyển hóa, phát triển trong giới tự nhiên. Chúng là tiền đề khoa học tự nhiên để Mác, Ăngghen khái quát nên phép biện chứng duy vật, khắc phục tính siêu hình của chủ nghĩa duy vật cũ."},{"id":"C1-045","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Sự ra đời của triết học Mác dựa trên tiền đề lý luận là Triết học cổ điển Đức, Kinh tế chính trị cổ điển Anh và Chủ nghĩa xã hội không tưởng Pháp là kết quả của điều gì?","opts":["Phủ định hoàn toàn những học thuyết kể trên.","Sự pha trộn những học thuyết kể trên.","Sự kế thừa có chọn lọc và phát triển sáng tạo những học thuyết kể trên.","Sự kế thừa nguyên vẹn những lý luận của các học thuyết kể trên."],"ans":2,"ex":"Ba nguồn gốc lý luận của chủ nghĩa Mác là **triết học cổ điển Đức**, **kinh tế chính trị cổ điển Anh** và **chủ nghĩa xã hội không tưởng Pháp**. Mác, Ăngghen không phủ định sạch trơn, không pha trộn chiết trung, cũng không kế thừa nguyên vẹn, mà **kế thừa có chọn lọc, có phê phán và phát triển sáng tạo**, đúng tinh thần phủ định biện chứng."},{"id":"C1-046","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thực tiễn cách mạng của giai cấp vô sản là cơ sở chủ yếu nhất cho sự ra đời của triết học Mác, chứng tỏ điều gì?","opts":["Giai cấp vô sản đã cung cấp cho C. Mác những ý tưởng chủ đạo để xây dựng triết học của mình","Mọi triết học đều xuất phát từ nhu cầu thực tiễn và dùng để phục vụ thực tiễn","Thực chất triết học Mác là việc khái quát cuộc đấu tranh cách mạng của giai cấp vô sản","Những cuộc cách mạng của giai cấp vô sản đã cung cấp những chất liệu để C. Mác sáng tạo ra triết học của mình"],"ans":1,"ex":"Triết học Mác ra đời khi phong trào công nhân phát triển và đặt ra nhu cầu có lý luận soi đường. Điều này minh chứng luận điểm duy vật: **mọi triết học đều xuất phát từ nhu cầu thực tiễn và quay lại phục vụ thực tiễn**. Triết học Mác không chỉ là sự “khái quát” cuộc đấu tranh vô sản (C), mà còn dựa trên tiền đề lý luận và khoa học tự nhiên; giai cấp vô sản cũng không “cung cấp ý tưởng” cho Mác."},{"id":"C1-047","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Vai trò của V. I. Lênin đối với triết học Mác là:","opts":["Bảo vệ và phát triển sáng tạo","Bảo tồn và giữ nguyên giá trị","Bảo vệ và sử dụng đúng đắn","Phản biện và phủ định những quan điểm sai trái"],"ans":0,"ex":"**V.I. Lênin** có công **bảo vệ và phát triển sáng tạo** triết học Mác trong điều kiện chủ nghĩa đế quốc, tiêu biểu qua tác phẩm “Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán” (1908) và “Bút ký triết học”. Ông đưa ra định nghĩa vật chất, phát triển lý luận nhận thức, phép biện chứng, lý luận về nhà nước và cách mạng. Do đó triết học Mác được gọi là triết học Mác – Lênin."},{"id":"C1-048","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Những lý luận được bổ sung từ V.I. Lênin đối với triết học Mác – Lênin được dựa trên cơ sở nào?","opts":["Ý tưởng sáng tạo của Lênin","Do triết học của Mác còn khuyết thiếu","Do những câu hỏi mà Mác đặt ra cho hậu thế","Dòi hỏi khách quan của thời đại và thực tiễn cách mạng trong thời kỳ mới"],"ans":3,"ex":"Những đóng góp của Lênin xuất phát từ **đòi hỏi khách quan của thời đại** (chủ nghĩa tư bản chuyển sang chủ nghĩa đế quốc, cuộc khủng hoảng vật lý học cuối thế kỷ XIX – đầu XX) và **thực tiễn cách mạng** ở Nga. Lý luận phát triển do thực tiễn yêu cầu, không phải do ý tưởng chủ quan hay vì triết học Mác “khuyết thiếu”."},{"id":"C1-049","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"V.I. Lênin muốn nhấn mạnh điều gì thông qua nhận định: “Chúng ta không coi lý luận của Mác như là một cái gì đã xong xuôi hẳn và bất khả xâm phạm”?","opts":["Triết học của C. Mác còn rất nhiều hạn chế, những hạn chế này không thể khắc phục được nên không thể can thiệp được.","Triết học của C. Mác vẫn còn dang dở chưa hoàn bị và nên được bảo tồn","Triết học của C. Mác là một học thuyết về sự phát triển luôn đòi hỏi được bổ sung, phát triển không ngừng.","Triết học của C. Mác đã trở nên lạc hậu, nó chỉ phù hợp với những thời kỳ lịch sử trước tuy nhiên nó là một tài liệu quý giá."],"ans":2,"ex":"Luận điểm của Lênin nhấn mạnh tính **mở, cách mạng và khoa học** của chủ nghĩa Mác: nó là học thuyết về sự phát triển, nên bản thân nó cũng phải không ngừng được **bổ sung, phát triển** theo thực tiễn. Đây là sự chống lại thái độ giáo điều. Các phương án còn lại hoặc coi lý luận Mác lạc hậu, hoặc chỉ cần bảo tồn, đều trái với tinh thần ấy."},{"id":"C1-050","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Tại sao hiện nay việc bổ sung, phát triển lý luận của triết học Mác– Lênin là cấp thiết? Chọn đáp án sai trong các đáp án sau:","opts":["Do mong muốn chủ quan của các nhà nghiên cứu lý luận.","Do đặc điểm thời đại: sự tương tác giữa cách mạng khoa học công nghệ và cách mạng xã hội đã tạo nên sự biến đổi rất năng động của đời sống xã hội.","Do sự khủng hoảng của chủ nghĩa xã hội làm cho yêu cầu phát triển triết học Mác – Lênin càng trở nên cấp bách.","Do sự phát triển lý luận triết học mácxít và đổi mới chủ nghĩa xã hội trong thực tiễn là một quá trình thống nhất"],"ans":0,"ex":"Câu hỏi yêu cầu chọn phương án **sai**. Việc bổ sung, phát triển triết học Mác – Lênin là cấp thiết do các **yêu cầu khách quan**: biến đổi năng động của thời đại do cách mạng khoa học – công nghệ, khủng hoảng của chủ nghĩa xã hội hiện thực, và sự thống nhất giữa phát triển lý luận với đổi mới thực tiễn. Ngược lại, “mong muốn chủ quan” của nhà nghiên cứu không phải là căn cứ."},{"id":"C1-051","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Phát kiến vĩ đại thiên tài của Mác trong lĩnh vực triết học là:","opts":["Học thuyết giá trị thặng dư","Chủ nghĩa duy vật lịch sử","Sứ mệnh lịch sử của giai cấp công nhân","Không có phát kiến thiên tài nào"],"ans":1,"ex":"**Chủ nghĩa duy vật lịch sử** được Lênin đánh giá là thành tựu vĩ đại nhất của tư tưởng khoa học, là phát kiến thiên tài của Mác trong triết học: lần đầu tiên chủ nghĩa duy vật được vận dụng vào lĩnh vực xã hội. Học thuyết giá trị thặng dư là phát kiến trong kinh tế chính trị; sứ mệnh lịch sử của giai cấp công nhân là nội dung của chủ nghĩa xã hội khoa học."},{"id":"C1-052","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Nhận định: “Triết học Mác – Lênin là cơ sở thế giới quan, phương pháp luận khoa học và cách mạng để phân tích xu hướng phát triển của xã hội” là dựa trên cơ sở nào?","opts":["Triết học Mác – Lênin chỉ ra quy luật vận động và phát triển chung nhất của tự nhiên, xã hội và tư duy.","Triết học Mác – lênin là chìa khóa vạn năng, có thể dùng để giải quyết tất cả các vấn đề phát sinh trong đời sống xã hội","Triết học Mác – Lênin có khả năng dự báo tương lai của xã hội loài người một cách chính xác","Triết học Mác – Lênin là khoa học về việc hoạch định chính sách phát triển kinh tế - xã hội của loài người."],"ans":0,"ex":"Triết học Mác – Lênin là cơ sở thế giới quan, phương pháp luận để phân tích xu hướng xã hội vì nó phát hiện ra **những quy luật vận động, phát triển chung nhất** của tự nhiên, xã hội và tư duy. Tuy vậy, nó không phải “chìa khóa vạn năng”, không thay thế các khoa học cụ thể hay chính sách, và không dự báo chính xác mọi chi tiết của tương lai."},{"id":"C1-053","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Tại sao sinh viên cần phải học, học phần Triết học Mác - Lênin? Chọn đáp án đúng nhất trong các đáp án sau:","opts":["Triết học Mác – Lênin là một học phần bắt buộc trong chương trình học, nếu không học tốt sẽ ảnh hưởng đến kết quả học tập và cơ hội việc làm.","Triết học Mác - Lênin giúp cho sinh viên trang bị được thế giới quan và phương pháp luận khoa học, cách mạng","Triết học rất khó, nếu học được nó sẽ khiến mọi người thán phục, vì không phải ai cũng học được triết học","Triết học là khoa học của mọi khoa học"],"ans":1,"ex":"Học triết học Mác – Lênin giúp sinh viên được trang bị **thế giới quan duy vật biện chứng** và **phương pháp luận khoa học, cách mạng**, từ đó nhận thức và giải quyết đúng các vấn đề trong học tập, nghề nghiệp, đời sống. Lý do “học phần bắt buộc” hay “được thán phục” là hời hợt; quan niệm “triết học là khoa học của mọi khoa học” đã bị triết học Mác bác bỏ."},{"id":"C1-054","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Để tiếp thu hiệu quả những tri thức của triết học nói chung và triết học Mác – Lênin nói riêng, sinh viên cần nhất điều gì?","opts":["Khả năng ghi nhớ và khả năng học thuộc lòng thật tốt","Tìm được tài liệu ngắn nhất, cô đọng nhất.","Bản thân phải có khả năng bẩm sinh về triết học hoặc có tư duy dị biệt","Trải nghiệm thực tiễn phong phú và nền tảng kiến thức phổ thông vững chắc"],"ans":3,"ex":"Tri thức triết học có tính khái quát cao, nên để tiếp thu hiệu quả cần có **vốn trải nghiệm thực tiễn** và **nền tảng tri thức khoa học** vững chắc làm chất liệu để hiểu và vận dụng. Điều này phù hợp nguyên tắc thống nhất lý luận và thực tiễn. Học thuộc lòng, tìm tài liệu ngắn nhất hay trông chờ năng khiếu bẩm sinh đều không phải yếu tố quyết định."},{"id":"C1-055","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Muốn có sự hiệu quả trong các hoạt động làm việc nhóm, trước tiên chúng ta cần phải làm gì?","opts":["Thống nhất về thế giới quan và phương pháp luận","Sự nhiệt tình và tinh thần lạc quan, cống hiến","Cần chọn những người giỏi nhất vào trong nhóm","Cần có thủ lĩnh giỏi để dẫn dắt nhóm"],"ans":0,"ex":"**Thế giới quan** và **phương pháp luận** định hướng cách nhìn nhận vấn đề và cách hành động. Trong làm việc nhóm, khi các thành viên thống nhất về quan điểm, mục tiêu và cách thức tiếp cận, hoạt động chung mới phối hợp hiệu quả. Nhiệt tình, người giỏi hay thủ lĩnh giỏi đều cần, nhưng nếu thiếu sự thống nhất nền tảng này thì nhóm dễ phân tán, mâu thuẫn."},{"id":"C1-056","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Học triết học và những khoa học khác cần nắm vững nguyên tắc nào?","opts":["Học liên tục không được ngắt quãng","Học theo năng lực của bản thân","Học tập lý luận gắn với vận dụng thực tiễn sinh động","Cần có tâm lý tốt và ý chí sắt đá"],"ans":2,"ex":"Nguyên tắc **thống nhất giữa lý luận và thực tiễn** là nguyên tắc cơ bản của triết học Mác – Lênin: lý luận phải xuất phát từ thực tiễn, được kiểm nghiệm bằng thực tiễn và phục vụ thực tiễn. Vì vậy học tập phải gắn lý luận với vận dụng vào thực tiễn sinh động, tránh bệnh giáo điều, sách vở. Các phương án khác chỉ là điều kiện hỗ trợ về phương pháp học hay tâm lý."},{"id":"C1-057","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thực chất và ý nghĩa cuộc cách mạng trong triết học do C. Mác và Ph. Ăngghen thực hiện?","opts":["Khắc phục được hạn chế của các trường phái triết học trong lịch sử để xây dựng chủ nghĩa duy vật biện chứng.","Vận dụng và mở rộng quan điểm duy vật biện chứng vào nghiên cứu lịch sử xã hội, sáng tạo ra chủ nghĩa duy vật lịch sử.","Bổ sung những đặc tính mới vào triết học, sáng tạo ra triết học chân chính khoa học – triết học duy vật biện chứng.","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Cuộc **cách mạng trong triết học** do Mác, Ăngghen thực hiện thể hiện ở: khắc phục tính trực quan, siêu hình của chủ nghĩa duy vật cũ và tính duy tâm của phép biện chứng Hêghen để xây dựng **chủ nghĩa duy vật biện chứng**; vận dụng nó vào xã hội, sáng tạo **chủ nghĩa duy vật lịch sử**; và bổ sung tính thực tiễn, tính giai cấp, đưa triết học thành khoa học chân chính. Vì vậy cả ba phương án đều đúng."},{"id":"C1-058","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Để thực hiện những cuộc cải cách trong tư tưởng cá nhân và tư tưởng xã hội, chúng ta cần dựa vào cơ sở khoa học nào là tốt nhất?","opts":["Đạo đức học","Tâm lý học","Triết học Mác - Lênin","Giáo dục học"],"ans":2,"ex":"Cải biến tư tưởng cá nhân và xã hội đòi hỏi cơ sở **thế giới quan và phương pháp luận** chung nhất. **Triết học Mác – Lênin** đáp ứng yêu cầu này vì nó chỉ ra quy luật chung nhất và vai trò của ý thức xã hội trong quan hệ với tồn tại xã hội. Đạo đức học, tâm lý học, giáo dục học là các khoa học cụ thể, chỉ giải quyết từng khía cạnh và cũng cần triết học làm nền tảng."},{"id":"C1-059","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Vai trò của triết học Mác – Lênin đối với sự nghiệp đổi mới theo định hướng xã hội chủ nghĩa ở Việt Nam?","opts":["Là nền tảng, cơ sở cho quá trình đổi mới tư duy ở Việt Nam.","Góp phần tìm được lời giải đáp về con đường đi lên chủ nghĩa xã hội ở Việt Nam. Đồng thời, qua thực tiễn để bổ sung, phát triển tư duy lý luận về chủ nghĩa xã hội.","Giúp giải quyết những vấn đề đặt ra trong thực tiễn xây dựng chủ nghĩa xã hội và thực tiễn đổi mới của đất nước ta.","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Giáo trình chỉ rõ triết học Mác – Lênin là **nền tảng lý luận** cho đổi mới tư duy ở Việt Nam; giúp tìm lời giải về **con đường đi lên chủ nghĩa xã hội**, đồng thời qua thực tiễn để bổ sung, phát triển lý luận; và giúp giải quyết các vấn đề thực tiễn của công cuộc đổi mới. Ba vai trò này thống nhất nhau, nên đáp án là tất cả đều đúng."},{"id":"C1-060","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Đường lối cách mạng của Đảng Cộng Sản Việt Nam là sự vận dụng sáng tạo của lý luận nào?","opts":["Chủ nghĩa Mác","Chủ nghĩa Mác – Lênin","Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh","Chủ nghĩa Mác và tư tưởng Hồ Chí Minh"],"ans":2,"ex":"Cương lĩnh và Điều lệ Đảng khẳng định Đảng Cộng sản Việt Nam lấy **chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh** làm nền tảng tư tưởng, kim chỉ nam cho hành động. Đường lối cách mạng là sự vận dụng sáng tạo cả hai nền tảng đó vào điều kiện Việt Nam. Các phương án khác thiếu tư tưởng Hồ Chí Minh hoặc thiếu đóng góp của Lênin."},{"id":"C1-061","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “Triết học Mác – Lênin là hệ thống quan điểm … về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","opts":["Duy vật biện chứng","Duy vật siêu hình","Duy tâm khách quan","Duy tâm chủ quan"],"ans":0,"ex":"Đặc trưng then chốt của **triết học Mác – Lênin** là lập trường **duy vật biện chứng**, tức sự thống nhất hữu cơ giữa chủ nghĩa duy vật và phép biện chứng. Điều này phân biệt nó với chủ nghĩa duy vật siêu hình (duy vật nhưng không biện chứng) và với triết học Hêghen (biện chứng nhưng duy tâm khách quan)."},{"id":"C1-062","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Điền vào chỗ trống: “Triết học Mác – Lênin là hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy – thế giới quan và phương pháp luận khoa học, cách mạng của …và các lực lượng xã hội tiến bộ trong nhận thức và cải tạo thế giới”.","opts":["Tầng lớp trí thức, tiểu tư sản","Giai cấp tư sản và giới tinh hoa","Tầng lớp quý tộc, vương giả","Gai cấp công nhân, nhân dân lao động"],"ans":3,"ex":"Triết học Mác – Lênin mang **tính giai cấp** rõ ràng: là thế giới quan, phương pháp luận của **giai cấp công nhân, nhân dân lao động** và các lực lượng xã hội tiến bộ. Nó phục vụ sự nghiệp giải phóng giai cấp, giải phóng con người, khác với các triết học trước vốn chủ yếu thể hiện lợi ích của giai cấp thống trị (tư sản, quý tộc)."},{"id":"C1-063","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Yếu tố nào không phải là điều kiện khách quan cho sự ra đời của triết học Mác – Lênin?","opts":["Sự phát triển của phong trào công nhân","Triết học cổ điển Đức","Sự ra đời của nền đại công nghiệp","Sự thay đổi lập trường triết học của C. Mác"],"ans":3,"ex":"Sự ra đời của triết học Mác có **điều kiện khách quan** gồm: điều kiện kinh tế – xã hội (nền đại công nghiệp, phong trào công nhân), nguồn gốc lý luận (trong đó có triết học cổ điển Đức) và tiền đề khoa học tự nhiên. Bên cạnh đó là **nhân tố chủ quan**: thiên tài và hoạt động thực tiễn của Mác, Ăngghen, nhất là sự chuyển biến lập trường từ duy tâm sang duy vật, từ dân chủ cách mạng sang cộng sản. Do đó phương án D không phải điều kiện khách quan."},{"id":"C1-064","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Chỉ thấy cây mà không thấy rừng” là câu nói lột tả phương pháp tư duy nào?","opts":["Tư duy biện chứng","Tư duy siêu hình","Tư duy trừu tượng","Tư duy độc lập"],"ans":1,"ex":"Ph. Ăngghen trong **“Chống Đuyrinh”** phê phán **phương pháp siêu hình**: chỉ nhìn thấy những sự vật riêng biệt mà không thấy mối liên hệ qua lại giữa chúng, “chỉ thấy cây mà không thấy rừng”. Tư duy siêu hình xem xét sự vật cô lập, tĩnh tại, phiến diện; trái lại tư duy biện chứng xem xét sự vật trong mối liên hệ phổ biến và sự phát triển."},{"id":"C1-065","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Câu nói “Không ai tắm hai lần trên một dòng sông” cho thấy phương pháp tư duy nào trong triết học?","opts":["Tư duy biện chứng","Tư duy siêu hình","Tư duy trừu tượng","Tư duy độc lập"],"ans":0,"ex":"Câu nói của **Hêraclít** (Hy Lạp cổ đại) diễn tả tư tưởng mọi vật đều trôi chảy, biến đổi không ngừng: dòng sông và con người luôn thay đổi. Đây là biểu hiện tiêu biểu của **phép biện chứng tự phát** thời cổ đại, thuộc phương pháp tư duy **biện chứng**. Tư duy siêu hình ngược lại xem sự vật là tĩnh tại, bất biến."},{"id":"C1-066","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Câu nói “\"Vẻ đẹp không nằm ở đôi má hồng của người thiếu nữ mà ở trong mắt của kẻ si tình\"” phản ánh quan điểm của trường phái triết học nào?","opts":["Trường phái duy tâm chủ quan","Trường phái duy tâm khách quan","Trường phái duy vật siêu hình","Trường phái duy vật biện chứng"],"ans":0,"ex":"Câu nói khẳng định cái đẹp không tồn tại khách quan ở đối tượng mà do **cảm nhận, ý thức của chủ thể** tạo nên. Coi cảm giác, ý thức cá nhân quyết định sự tồn tại và thuộc tính của sự vật là lập trường **duy tâm chủ quan**. Duy tâm khách quan thì đặt cái quyết định vào một tinh thần siêu cá nhân như “ý niệm” hay “tinh thần tuyệt đối”."},{"id":"C1-067","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Ý nghĩa lịch sử to lớn của triết học Mác – Lênin là gì?","opts":["Là học thuyết triết học đầu tiên trong lịch sử nhân loại kết hợp được lý luận của ba nhà tư tưởng lỗi lạc của nhân loại","Là học thuyết triết học đầu tiên trong lịch sử nhân loại đứng trên lập trường của người lao động","Là học thuyết triết học đầu tiên trong lịch sử nhân loại nghiên cứu về mối quan hệ giữa vật chất và ý thức","Là học thuyết triết học đầu tiên trong lịch sử nhân loại có chức năng xây dựng thế giới quan, phương pháp luận."],"ans":1,"ex":"Ý nghĩa lịch sử nổi bật của triết học Mác – Lênin là lần đầu tiên có một học thuyết triết học **đứng trên lập trường của giai cấp công nhân và nhân dân lao động**, trở thành vũ khí lý luận cho sự nghiệp giải phóng. Các phương án khác sai vì quan hệ vật chất – ý thức và chức năng thế giới quan, phương pháp luận đã có ở mọi triết học trước đó."},{"id":"C1-068","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Nhận định nào không đúng về triết học Mác – Lênin?","opts":["Triết học Mác – Lênin đã kế thừa trực tiếp những thành tựu của triết học cổ điển Đức","Triết học Mác – Lênin là một công cụ hữu hiệu để các lực lượng tiến bộ cải tạo hiện thực khách quan","Triết học Mác – Lênin đã phủ định hoàn toàn dấu vết của triết học duy tâm khách quan của Hegel","Triết học Mác – Lê nin có mối quan hệ chặt chẽ với kinh tế chính trị Mác – Lênin và chủ nghĩa xã hội khoa học."],"ans":2,"ex":"Câu hỏi yêu cầu chọn nhận định **không đúng**. Mác và Ăngghen phê phán tính duy tâm khách quan của Hêghen nhưng **không phủ định sạch trơn**: họ kế thừa “hạt nhân hợp lý” là phép biện chứng. Đây là phủ định biện chứng (vừa loại bỏ, vừa kế thừa). Các nhận định còn lại đều đúng: kế thừa triết học cổ điển Đức, là công cụ cải tạo hiện thực, gắn bó với hai bộ phận kia của chủ nghĩa Mác – Lênin."},{"id":"C1-069","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Những lý luận triết học có tầm ảnh hưởng lớn đến sự hình thành của triết học Mác – Lênin là?","opts":["Lý luận triết học biện chứng của Hegel và lý luận triết học duy vật của Feuerbach","Lý luận siêu hình học của Kant và lý luận triết học duy tâm tiên nghiệm của Schelling","Lý luận triết học duy vật máy móc của Duhring và lý luận triết học duy cảm của Berkeley","Lý luận triết học đạo đức của Socrate và triết học duy tâm khách quan của Platon"],"ans":0,"ex":"Trong triết học cổ điển Đức, hai đại biểu ảnh hưởng trực tiếp nhất tới triết học Mác là **Hêghen** (với phép biện chứng – “hạt nhân hợp lý”) và **Phoiơbắc** (với chủ nghĩa duy vật, tư tưởng nhân bản). Mác kế thừa biện chứng của Hêghen và duy vật của Phoiơbắc, khắc phục hạn chế của cả hai. Đuyrinh và Béccơli chính là những người bị Mác – Ăngghen, Lênin phê phán."},{"id":"C1-070","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Yếu tố ảnh hưởng lớn nhất đối với thế giới quan của con người là gì?","opts":["Quan niệm thẩm mỹ","Quan điểm đạo đức","Quan niệm về đức tin","Quan điểm triết học"],"ans":3,"ex":"Trong cấu trúc thế giới quan, **quan điểm triết học** là **hạt nhân lý luận**, giữ vai trò chi phối, định hướng các quan niệm khác như đạo đức, thẩm mỹ, tôn giáo. Bởi vì triết học trả lời những vấn đề chung nhất về thế giới và con người, nên nó có ảnh hưởng lớn nhất tới tính chất của thế giới quan."},{"id":"C1-071","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Thế giới quan triết học và thế giới quan thần thoại khác nhau ở điểm nào?","opts":["Triết học giải thích thế giới dựa trên lý luận, còn thần thoại dựa trên sự tưởng tượng và yếu tố niềm tin","Triết học sử dụng ngôn ngữ hình ảnh, còn thần thoại sử dụng khái niệm trừu tượng","Triết học chỉ dành cho tầng lớp quý tộc, còn thần thoại dành cho toàn dân","Triết học ra đời sớm hơn thần thoại"],"ans":0,"ex":"Giáo trình phân biệt các hình thức thế giới quan: **thần thoại** giải thích thế giới bằng **trí tưởng tượng**, hình ảnh và niềm tin; **tôn giáo** dựa trên niềm tin vào siêu nhiên; còn **triết học** giải thích thế giới bằng **hệ thống khái niệm, phạm trù, lý luận**. Phương án B đảo ngược đặc điểm; thần thoại ra đời trước triết học nên D sai."},{"id":"C1-072","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Vai trò cơ bản của thế giới quan đối với con người là gì?","opts":["Giúp con người hình thành các quan hệ xã hội","Định hướng cho nhận thức và hoạt động thực tiễn của con người trong đời sống","Giúp cho con người lý giải thế giới dưới nhiều góc nhìn khác nhau","Trang bị cho con người những hiểu biết về thế giới xung quanh mình"],"ans":1,"ex":"Vai trò cơ bản của **thế giới quan** là **định hướng cho nhận thức và hoạt động thực tiễn** của con người, vì nó quy định các nguyên tắc, thái độ, giá trị trong hành động. Thế giới quan đúng đắn giúp con người hoạt động có hiệu quả, còn thế giới quan sai lầm dẫn tới hành động sai. Các phương án khác chỉ nêu khía cạnh phụ, chưa phải vai trò cơ bản."},{"id":"C1-073","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Quan điểm “Tồn tại là được tri giác” thuộc trường phái triết học nào?","opts":["Duy tâm khách quan","Duy vật","Duy tâm chủ quan","Nhị nguyên"],"ans":2,"ex":"Mệnh đề **“Tồn tại là được tri giác”** (esse est percipi) của **G. Béccơli** (Anh, thế kỷ XVIII) cho rằng sự vật chỉ tồn tại khi được cảm giác, tri giác. Coi cảm giác của chủ thể là cái có trước, quyết định sự tồn tại của sự vật là lập trường điển hình của **chủ nghĩa duy tâm chủ quan**."},{"id":"C1-074","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Khi đứng trước những thất bại trong hoạt động sản xuất kinh doanh, mỗi người chúng ta cần phân tích nguyên nhân từ nhiều phía: thị trường, chính sách, năng lực nội bộ, rồi tìm giải pháp tổng thể thay vì chỉ đổ lỗi cho một yếu tố.”. Quan điểm này phản ánh vai trò nào của triết học?","opts":["Vai trò của triết học trong việc định hướng các hoạt động kinh tế","Vai trò của triết học trong việc định hướng giá trị đạo đức xã hội","Trang bị phương pháp luận biện chứng cho nhận thức và định hướng hoạt động thực tiễn","Vai trò của triết học trong phát triển năng lực tư duy cá nhân"],"ans":2,"ex":"Quan điểm phân tích nguyên nhân từ nhiều phía và tìm giải pháp tổng thể thể hiện **nguyên tắc toàn diện** của **phép biện chứng duy vật**. Đây là vai trò của triết học trong việc trang bị **phương pháp luận** cho nhận thức và định hướng hoạt động thực tiễn. Phương án A chỉ nêu lĩnh vực áp dụng, chưa chỉ ra bản chất phương pháp luận của vấn đề."},{"id":"C1-075","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Dù con người có nhận thức hay không thì các quy luật tự nhiên như trái đất quay quanh mặt trời vẫn tồn tại khách quan.”. Quan điểm này phản ánh nội dung nào trong vấn đề cơ bản của triết học?","opts":["Thừa nhận vật chất có trước, ý thức có sau và phụ thuộc vào vật chất","Khẳng định ý thức quyết định vật chất","Phủ nhận vai trò của cả vật chất lẫn ý thức","Cả vật chất và ý thức đều cùng tồn tại và có tác động ngang nhau"],"ans":0,"ex":"Khẳng định quy luật tự nhiên tồn tại **khách quan**, không phụ thuộc vào ý thức con người là lập trường **duy vật**: vật chất có trước, ý thức có sau, ý thức là sự phản ánh vật chất. Đây là cách giải quyết mặt thứ nhất của vấn đề cơ bản theo chủ nghĩa duy vật. Phương án B là duy tâm, D là nhị nguyên luận."},{"id":"C1-076","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Thế giới chỉ tồn tại trong ý niệm của con người; nếu con người không nhận thức được thì thế giới sẽ không có.”. Quan điểm này thể hiện lập trường nào về mặt bản thể luận trong triết học?","opts":["Duy tâm chủ quan","Duy tâm khách quan","Duy vật biện chứng","Thuyết nhị nguyên"],"ans":0,"ex":"Cho rằng thế giới chỉ tồn tại trong ý niệm, nhận thức **của con người** và không có thế giới nếu con người không nhận thức là coi ý thức chủ thể quyết định sự tồn tại của sự vật, tức lập trường **duy tâm chủ quan**. Duy tâm khách quan sẽ đặt nguồn gốc thế giới ở một tinh thần khách quan, độc lập với con người."},{"id":"C1-077","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"“Thế giới rộng lớn và phức tạp, con người không thể nào nhận thức được hết, vì vậy nhận thức là bất khả thi.”. Quan điểm trên thuộc lập trường nào về mặt nhận thức luận trong triết học?","opts":["Duy tâm khách quan","Thuyết bất khả tri","Duy vật biện chứng","Thuyết khả tri"],"ans":1,"ex":"Phủ nhận khả năng nhận thức thế giới của con người là lập trường **thuyết bất khả tri** (tiêu biểu D. Hium, I. Cantơ với “vật tự nó”). Chủ nghĩa duy vật biện chứng theo **thuyết khả tri**: thế giới vô tận nên nhận thức không bao giờ hoàn tất, nhưng con người vẫn ngày càng nhận thức sâu hơn thông qua thực tiễn. Sai lầm ở đây là đồng nhất “không biết hết” với “không thể biết”."},{"id":"C1-078","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Trong tác phẩm “Tuyên ngôn của Đảng Cộng sản”, Mác và Ăngghen khẳng định: “Triết học không chỉ để giải thích thế giới, mà còn nhằm cải tạo thế giới.”. Phát biểu này phản ánh bản chất chính trị nào của triết học Mác - Lênin?","opts":["Triết học chỉ là khoa học thuần túy, không gắn với chính trị","Triết học phục vụ lợi ích của mọi giai cấp một cách trung lập","Triết học là vũ khí lý luận của giai cấp công nhân và nhân dân lao động trong cuộc đấu tranh giải phóng xã hội","Triết học chỉ có ý nghĩa trong việc cải tạo thế giới tự nhiên"],"ans":2,"ex":"Tư tưởng triết học không chỉ giải thích mà phải **cải tạo thế giới** thể hiện **tính thực tiễn và tính cách mạng** của triết học Mác – Lênin. Về bản chất chính trị, nó là **vũ khí lý luận** của giai cấp công nhân và nhân dân lao động trong cuộc đấu tranh giải phóng xã hội, chứ không trung lập hay “thuần túy”. Lưu ý: luận điểm này vốn được phát biểu trong Luận cương thứ 11 của **“Luận cương về Phoiơbắc”** (Mác, 1845)."},{"id":"C1-079","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Phát biểu nào sau đây thể hiện bản chất cách mạng của triết học Mác - Lênin?","opts":["Triết học Mác - Lênin chỉ tập trung vào việc giải thích thế giới","Triết học Mác - Lênin gắn liền với sự nghiệp giải phóng giai cấp, giải phóng dân tộc và giải phóng con người","Triết học Mác - Lênin phục vụ lợi ích cho mọi giai cấp trong quá trình phát triển xã hội","Triết học Mác - Lênin phủ nhận vai trò của thực tiễn cách mạng"],"ans":1,"ex":"**Bản chất cách mạng** của triết học Mác – Lênin thể hiện ở chỗ nó gắn liền với sự nghiệp **giải phóng giai cấp, giải phóng dân tộc và giải phóng con người**, không chỉ giải thích mà còn cải tạo thế giới. Nó mang tính giai cấp công nhân rõ ràng, coi thực tiễn cách mạng là cơ sở, nên các phương án A, C, D đều trái với bản chất ấy."},{"id":"C1-080","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Phát minh khoa học tự nhiên nào dưới đây không phải là tiền đề trực tiếp đưa đến sự ra đời của triết học Mác - Lênin?","opts":["Thuyết tế bào","Thuyết tiến hóa của Đác-uyn","Thuyết vạn vật hấp dẫn","Định luật bảo toàn và chuyển hóa năng lượng"],"ans":2,"ex":"Ba phát minh khoa học tự nhiên được Ăngghen nêu là tiền đề trực tiếp của triết học Mác (giữa thế kỷ XIX) gồm: **định luật bảo toàn và chuyển hóa năng lượng**, **học thuyết tế bào** và **thuyết tiến hóa** của Đácuyn. **Thuyết vạn vật hấp dẫn** của Niutơn (thế kỷ XVII) là thành tựu của cơ học cổ điển, gắn với thời kỳ hình thành phương pháp tư duy siêu hình, không thuộc ba tiền đề này."},{"id":"C1-081","chapter":1,"topic":"Chương 1: Khái luận về triết học và triết học Mác – Lênin","q":"Trong ba phát minh khoa học tự nhiên làm tiền đề cho sự ra đời triết học Mác - Lênin, định luật bảo toàn và chuyển hóa năng lượng có vai trò đặc biệt ở chỗ nào?","opts":["Xác định nguồn gốc sự sống của con người từ loài động vật bậc thấp","Khẳng định tính thống nhất, tính bất biến và sự vận động không ngừng của thế giới vật chất thông qua sự chuyển hóa giữa các dạng năng lượng","Giải thích cơ sở vi mô của sự sống, chứng minh mọi cơ thể sống đều được cấu tạo từ tế bào","Bác bỏ quan điểm duy vật, khẳng định vai trò tuyệt đối của ý thức trong việc sáng tạo thế giới"],"ans":1,"ex":"**Định luật bảo toàn và chuyển hóa năng lượng** chứng minh các dạng vận động của vật chất (cơ, nhiệt, điện…) không tự sinh ra, không mất đi mà chuyển hóa lẫn nhau; qua đó khẳng định **tính thống nhất vật chất** và sự vận động không ngừng của thế giới. Ý “bất biến” ở đây hiểu là tổng năng lượng được bảo toàn. Phương án A nói về thuyết tiến hóa, C về thuyết tế bào."},{"id":"C2-001","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đặc điểm chung của các quan niệm triết học duy vật thời kỳ cổ đại về vật chất là gì?","opts":["Đồng nhất vật chất với nguyên tử","Đồng nhất vật chất với dạng cụ thể của vật chất","Đồng nhất vật chất với khối lượng","Đồng nhất vật chất với ý thức"],"ans":1,"ex":"Chủ nghĩa duy vật cổ đại (Talet, Anaximen, Hêraclít, Đêmôcrít; Ngũ hành ở phương Đông) có xu hướng **đồng nhất vật chất với một hay vài dạng cụ thể** như nước, lửa, không khí, nguyên tử. Đây là quan niệm trực quan, chất phác nhưng có giá trị vì lấy chính giới tự nhiên để giải thích thế giới. Phương án nguyên tử chỉ đúng với Đêmôcrít, không phải đặc điểm chung; đồng nhất với khối lượng là đặc điểm thời cận đại."},{"id":"C2-002","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đặc điểm chung của các quan niệm triết học duy vật thời kỳ cận đại về vật chất là gì?","opts":["Đồng nhất vật chất với dạng cụ thể của vật chất","Đồng nhất vật chất với khối lượng; giải thích sự vận động của thế giới vật chất trên nền tảng cơ học.","Đồng nhất vật chất với nguyên tử","Đồng nhất vật chất với ý thức"],"ans":1,"ex":"Thế kỷ XVII–XVIII, dưới ảnh hưởng của cơ học Niutơn, các nhà duy vật cận đại **đồng nhất vật chất với khối lượng**, coi vận động chỉ là vận động cơ học và giải thích thế giới bằng các quy luật cơ học. Đó là **chủ nghĩa duy vật siêu hình, máy móc**. Đồng nhất vật chất với dạng cụ thể là đặc điểm thời cổ đại, còn đồng nhất với ý thức là lập trường duy tâm."},{"id":"C2-003","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ba phát minh khoa học nào dưới đây có vai trò to lớn cho sự ra đời của chủ nghĩa duy vật biện chứng?","opts":["Định luật bảo toàn và chuyển hóa năng lượng; thuyết tế bào; thuyết tiến hóa","Thuyết tế bào; định luật newton; thuyết tiến hóa","Định luật bảo toàn và chuyển hóa năng lượng; thuyết nguyên tử; thuyết tế bào.","Thuyết tiến hóa; định luật vạn vật hấp dẫn; thuyết tế bào."],"ans":0,"ex":"Ph. Ăngghen chỉ ra ba phát minh lớn giữa thế kỷ XIX làm tiền đề khoa học tự nhiên cho chủ nghĩa duy vật biện chứng: **định luật bảo toàn và chuyển hóa năng lượng**, **học thuyết tế bào** và **học thuyết tiến hóa** của Đácuyn. Chúng cho thấy thế giới là một chỉnh thể thống nhất, vận động, chuyển hóa và phát triển. Định luật Niutơn hay thuyết nguyên tử là thành tựu gắn với quan niệm cơ học trước đó."},{"id":"C2-004","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng điền vào chỗ trống sau: … là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh, và tồn tại không lệ thuộc vào cảm giác?","opts":["Vật chất","Ý thức","Cảm giác","Tri giác"],"ans":0,"ex":"Đây là **định nghĩa vật chất của V.I. Lênin** trong tác phẩm \"Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán\" (1908). Vật chất được xác định là **thực tại khách quan**, tồn tại độc lập với ý thức nhưng được cảm giác phản ánh. Ý thức, cảm giác, tri giác đều là cái phản ánh, tức thuộc mặt chủ quan, nên không thể điền vào chỗ trống."},{"id":"C2-005","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, vật chất là:","opts":["Thực tại khách quan và chủ quan, được ý thức phản ánh.","Tồn tại ở các dạng vật chất cụ thể, có thể cảm nhận được.","Thực tại khách quan độc lập với ý thức, không phụ thuộc vào ý thức","Thực tại khách quan không nhận thức được."],"ans":2,"ex":"Theo chủ nghĩa duy vật biện chứng, vật chất là **thực tại khách quan**, tồn tại độc lập, không phụ thuộc vào ý thức, và con người có thể nhận thức được. Phương án gắn vật chất với \"chủ quan\" là sai; quy vật chất về các dạng cụ thể là sai lầm của duy vật cũ; còn cho rằng không nhận thức được là quan điểm của thuyết không thể biết."},{"id":"C2-006","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Thuộc tính cơ bản nhất, phổ biến nhất của vật chất là gì?","opts":["Không tồn tại khách quan","Tồn tại khách quan","Thế giới khách quan","Phụ thuộc vào ý thức con người"],"ans":1,"ex":"**Tồn tại khách quan**, tức tồn tại bên ngoài và không lệ thuộc vào ý thức con người, là thuộc tính cơ bản, phổ biến nhất của mọi dạng vật chất. Đây là tiêu chuẩn để phân biệt cái gì là vật chất và cái gì không phải. Các phương án phủ nhận tính khách quan hoặc gắn vật chất với ý thức đều trái với định nghĩa của Lênin."},{"id":"C2-007","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng về phạm trù vật chất theo quan điểm của triết học Mác - Lênin?","opts":["Vật chất là nguyên tử","Vật chất là nước","Vật chất là đất,nước, lửa, không khí","vật chất là hiện thực khách quan"],"ans":3,"ex":"Triết học Mác – Lênin không đồng nhất vật chất với bất kỳ vật thể cụ thể nào mà xác định vật chất là **hiện thực (thực tại) khách quan**. Các phương án nguyên tử, nước, hay đất – nước – lửa – không khí là quan niệm của chủ nghĩa duy vật cổ đại, coi một dạng cụ thể là bản nguyên của thế giới."},{"id":"C2-008","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nội dung nào dưới đây trong định nghĩa vật chất của V.I. Lênin giải quyết được mặt thứ nhất của vấn đề cơ bản của triết học?","opts":["Vật chất là một phạm trù triết học dùng để chỉ thực tại khách quan","Vật chất phụ thuộc vào cảm giác của con người","Thực tại khách quan được cảm giác chép lại, chụp lại, phản ảnh","Thực tại khách quan tồn tại không lệ thuộc vào cảm giác"],"ans":3,"ex":"Mặt thứ nhất của vấn đề cơ bản của triết học hỏi vật chất và ý thức cái nào có trước, quyết định cái nào. Mệnh đề \"thực tại khách quan **tồn tại không lệ thuộc vào cảm giác**\" khẳng định vật chất có trước, là tính thứ nhất. Còn mệnh đề \"được cảm giác chép lại, chụp lại, phản ánh\" giải quyết **mặt thứ hai**, tức khả năng nhận thức thế giới."},{"id":"C2-009","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng về điểm đặc biệt và tính sáng tạo trong phương pháp định nghĩa vật chất của V.I. Lênin?","opts":["Định nghĩa vật chất thông qua đối lập với ý thức","Định nghĩa vật chất thông qua vận động","Định nghĩa vật chất thông qua tồn tại","Định nghĩa vật chất thông qua khái niệm"],"ans":0,"ex":"Vật chất là phạm trù rộng nhất, nên không thể định nghĩa theo cách thông thường (quy về một khái niệm rộng hơn). Lênin đã sáng tạo khi **định nghĩa vật chất thông qua đối lập với ý thức**: vật chất là cái tồn tại khách quan, ý thức là cái phản ánh nó. Cách này vừa khẳng định tính thứ nhất của vật chất, vừa vượt qua hạn chế của duy vật cũ."},{"id":"C2-010","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hãy chỉ ra một đáp án sai khi phân tích về nội dung định nghĩa vật chất dưới đây?","opts":["Vật chất là tất cả những gì tồn tại trong thế giới khách quan","Vật chất là tất cả những cái gây nên cảm giác ở con người khi bằng cách nào đó trực tiếp hay gián tiếp tác động nên giác quan của con người","Vật chất là những vật cụ thể tồn tại trong thế giới khách quan","Khái niệm vật chất không có nghĩa gì khác hơn là thực tại khách quan tồn tại độc lập với ý thức con người và được ý thức con người phản ánh"],"ans":2,"ex":"Định nghĩa của Lênin khái quát thuộc tính chung nhất của mọi dạng vật chất là tồn tại khách quan, gây nên cảm giác và được ý thức phản ánh. Do đó, coi vật chất chỉ là **những vật cụ thể** là sai, vì đó là lối đồng nhất vật chất với vật thể của duy vật cũ. Các phương án còn lại đều diễn đạt đúng nội dung định nghĩa."},{"id":"C2-011","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo Ph. Ăngghen, một trong những phương thức tồn tại cơ bản của vật chất là gì?","opts":["Phát triển","Vận động","Chuyển hóa","Vật thể hữu hình"],"ans":1,"ex":"Trong \"Chống Đuyrinh\" và \"Biện chứng của tự nhiên\", Ph. Ăngghen khẳng định **vận động là phương thức tồn tại của vật chất**. Vật chất chỉ tồn tại bằng cách vận động, và qua vận động mà biểu hiện sự tồn tại của mình. Phát triển chỉ là một khuynh hướng của vận động, còn chuyển hóa hay vật thể hữu hình không phải là phương thức tồn tại."},{"id":"C2-012","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, khẳng định nào sau đây là đúng?","opts":["Vận động là tuyệt đối, đứng im là tương đối, tạm thời","Vận động và đứng im phải được quan niệm là tuyệt đối","Vận động và đứng im chỉ là tương đối, tạm thời","Đứng im là tuyệt đối, vận động là tương đối"],"ans":0,"ex":"Vận động là **tuyệt đối** vì nó là phương thức tồn tại của vật chất, có ở mọi nơi, mọi lúc. Đứng im là **tương đối, tạm thời**, vì nó chỉ xảy ra trong một quan hệ nhất định, với một hình thức vận động nhất định, và bản thân nó cũng là một trạng thái đặc biệt của vận động (vận động trong cân bằng). Coi đứng im là tuyệt đối là quan điểm siêu hình."},{"id":"C2-013","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng về vận động của vật chất:","opts":["Vật chất chỉ có một phương thức tồn tại là vận động.","Vận động là sự dịch chuyển vị trí của các vật thể trong không gian.","Vận động là do ngoại lực tác động.","Vận động của vật chất là cố hữu, tuyệt đối, vô hạn."],"ans":3,"ex":"Vận động là thuộc tính **cố hữu** của vật chất, không do ai sáng tạo ra, không mất đi, nên mang tính **tuyệt đối, vô hạn**. Quy vận động về sự dịch chuyển vị trí là quan điểm cơ học; cho rằng vận động do ngoại lực gây ra là sai, vì nguồn gốc của vận động nằm bên trong sự vật. Vật chất còn tồn tại trong không gian và thời gian, nên nói vận động là phương thức tồn tại \"duy nhất\" cũng không chính xác."},{"id":"C2-014","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nguồn gốc vận động của vật chất theo triết học Mác – Lênin là:","opts":["Ở bên ngoài sự vật hiện tượng do sự tương tác hay do sự tác động.","Do ý thức tinh thần tư tưởng quyết định","Ở trong bản thân sự vật hiện tượng do sự tác động của các mặt, các yếu tố trong sự vật hiện tượng gây ra","Do các lực lượng siêu nhiên tạo ra"],"ans":2,"ex":"Theo phép biện chứng duy vật, vận động là **tự thân vận động**. Nguồn gốc của nó nằm ngay trong sự vật, do sự tác động lẫn nhau, tức mâu thuẫn, giữa các mặt, các yếu tố bên trong gây ra. Tìm nguồn gốc ở cú hích bên ngoài là quan điểm siêu hình; quy về ý thức hoặc lực lượng siêu nhiên là quan điểm duy tâm, tôn giáo."},{"id":"C2-015","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan niệm của Triết học Mác – Lênin, thế giới thống nhất ở cái gì?","opts":["Thống nhất ở Vật chất và Tinh thần","Ta cho nó thống nhất thì nó thống nhất","Thống nhất ở tính vật chất của nó","Thống nhất vì do Thượng đế sinh ra"],"ans":2,"ex":"Ph. Ăngghen khẳng định: **tính thống nhất thực sự của thế giới là ở tính vật chất của nó**. Mọi bộ phận của thế giới đều là những dạng cụ thể của vật chất, có nguồn gốc vật chất, chịu sự chi phối của các quy luật khách quan; ý thức cũng chỉ là thuộc tính của dạng vật chất có tổ chức cao. Các phương án nhị nguyên, chủ quan hay thần học đều sai."},{"id":"C2-016","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Xã hội loài người có được coi là một bộ phận của thế giới vật chất không?","opts":["Có, vì nó được xem là cấp độ đặc biệt của tổ chức vật chất và là cấp độ cao nhất của cấu trúc vật chất. Trong xã hội đó, tuy nhân tố hoạt động là những con người có ý thức, song không làm mất đi tính vật chất, khách quan của đời sống xã hội, của các quan hệ vật chất xã hội.","Có, vì xã hội loài người suy cho cùng cũng là vật chất và là cấp độ cao nhất của cấu trúc vật chất.","Không, vì xã hội loài người thuộc về ý thức, với những hoạt động nhận thức và tư duy sâu sắc, đặc trưng của con người.","Không, vì xét đến cùng con người là sản phẩm phát triển cao nhất của tự nhiên nhờ vào tư duy vượt trội của mình."],"ans":0,"ex":"Xã hội là **dạng tổ chức đặc biệt, cao nhất của thế giới vật chất**. Tuy hoạt động xã hội do những con người có ý thức tiến hành, nhưng đời sống xã hội vẫn có cơ sở vật chất khách quan (sản xuất vật chất, quan hệ sản xuất). Phương án A đầy đủ nhất vì nêu được cả tính đặc thù (vai trò của ý thức) lẫn tính vật chất, khách quan của xã hội."},{"id":"C2-017","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan niệm của Triết học Mác - Lênin, ý thức là gì?","opts":["Hình ảnh của thế giới khách quan","Hình ảnh phản ánh sự vận động và phát triển của thế giới khách quan","Là một phần chức năng của bộ óc con người","Là hình ảnh phản ánh sáng tạo lại hiện thực khách quan"],"ans":3,"ex":"Theo chủ nghĩa duy vật biện chứng, ý thức là **hình ảnh chủ quan của thế giới khách quan**, là sự phản ánh **năng động, sáng tạo** hiện thực khách quan vào bộ óc người. Hai phương án đầu chưa nêu được tính sáng tạo, vốn là điểm phân biệt ý thức với các hình thức phản ánh thấp hơn. Còn \"chức năng của bộ óc\" mới chỉ nói về cơ quan vật chất của ý thức."},{"id":"C2-018","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng nhất về Ý thức theo quan điểm của Triết học Mác – Lênin.","opts":["Nguồn gốc trực tiếp quan trọng nhất quyết định sự ra đời và phát triển của ý thức là lao động, là thực tiễn xã hội.","Ý thức phản ánh hiện thực khách quan vào bộ óc con người thông qua lao động, ngôn ngữ và các quan hệ xã hội.","Ý thức là sản phẩm xã hội, là một hiện tượng xã hội","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Ý thức có nguồn gốc tự nhiên (bộ óc và thế giới khách quan) và **nguồn gốc xã hội** (lao động, ngôn ngữ). Trong đó lao động, thực tiễn xã hội là nguồn gốc trực tiếp, quan trọng nhất. Vì hình thành và tồn tại gắn với các quan hệ xã hội nên ý thức về bản chất là **sản phẩm xã hội, một hiện tượng xã hội**. Cả ba nhận định đều đúng nên chọn D."},{"id":"C2-019","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng nhất về nguồn gốc tự nhiên của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng.","opts":["Bộ óc người","Thế giới bên ngoài","Bộ óc người cùng với thế giới bên ngoài tác động lên bộ óc người","Lao động và ngôn ngữ"],"ans":2,"ex":"**Nguồn gốc tự nhiên** của ý thức gồm hai yếu tố: **bộ óc người**, là dạng vật chất có tổ chức cao nhất, và **thế giới khách quan tác động lên bộ óc**, tạo ra quá trình phản ánh. Thiếu một trong hai thì không có ý thức. Lao động và ngôn ngữ thuộc về nguồn gốc xã hội."},{"id":"C2-020","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng nhất về nguồn gốc xã hội của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng.","opts":["Lao động","Ngôn ngữ","Lao động và ngôn ngữ","Bộ óc người và thế giới khách quan"],"ans":2,"ex":"Ph. Ăngghen viết: trước hết là **lao động**, sau đó và đồng thời với lao động là **ngôn ngữ**, đó là hai sức kích thích chủ yếu biến bộ óc vượt thành bộ óc người. Hai yếu tố này hợp thành **nguồn gốc xã hội** của ý thức. Bộ óc và thế giới khách quan là nguồn gốc tự nhiên."},{"id":"C2-021","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Điều kiện cần cho sự ra đời của ý thức là gì?","opts":["Bộ não người","Bộ não người và hiện thực khách quan tương tác với nó","Năng lực chế tạo và sử dụng công cụ lao động","Năng lực ngôn ngữ phát triển"],"ans":1,"ex":"Nguồn gốc tự nhiên, gồm **bộ óc người và thế giới khách quan tác động vào nó**, là **điều kiện cần** cho sự ra đời của ý thức. Nó cung cấp cơ quan và đối tượng của sự phản ánh. Tuy nhiên, chỉ riêng điều kiện này thì chưa đủ để ý thức ra đời."},{"id":"C2-022","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Điều kiện đủ cho sự ra đời của ý thức là gì?","opts":["Lao động và ngôn ngữ","Bộ não người và hiện thực khách quan","Năng lực chế tạo và sử dụng công cụ lao động","Ngôn ngữ phát triển với cả tiếng nói và chữ viết"],"ans":0,"ex":"**Nguồn gốc xã hội**, tức **lao động và ngôn ngữ**, là **điều kiện đủ** cho sự ra đời của ý thức. Lao động giúp con người tác động vào tự nhiên, làm bộc lộ thuộc tính của sự vật và hoàn thiện bộ óc; ngôn ngữ là vỏ vật chất của tư duy và công cụ giao tiếp. Bộ não và hiện thực khách quan chỉ là điều kiện cần."},{"id":"C2-023","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ngôn ngữ có vai trò như thế nào đối với quá trình hình thành, tồn tại và phát triển của ý thức?","opts":["Giúp con người khái quát, trừu tượng hoá, suy nghĩ độc lập, tách khỏi sự vật cảm tính, giao tiếp trao đổi tư tưởng, lưu giữ, kế thừa những tri thức, kinh nghiệm phong phú của xã hội đã tích luỹ được qua các thế hệ, thời kỳ lịch sử.","Giúp con giao tiếp, trao đổi tư tưởng, lưu giữ, kế thừa những tri thức, kinh nghiệm phong phú của xã hội đã tích luỹ được qua các thế hệ, thời kỳ lịch sử.","Giúp con người khái quát, trừu tượng hoá, suy nghĩ độc lập, lưu giữ, kế thừa những tri thức, kinh nghiệm phong phú của xã hội đã tích luỹ được qua các thế hệ, thời kỳ lịch sử.","Giúp con người trao đổi tư tưởng, lưu giữ, kế thừa những tri thức, kinh nghiệm phong phú của xã hội đã tích luỹ được qua các thế hệ, thời kỳ lịch sử."],"ans":0,"ex":"Ngôn ngữ là **vỏ vật chất của tư duy**, là hiện thực trực tiếp của tư tưởng. Nhờ ngôn ngữ, con người có thể khái quát, trừu tượng hóa, suy nghĩ tách khỏi sự vật cảm tính, giao tiếp, trao đổi tư tưởng, và lưu giữ, truyền lại tri thức qua các thế hệ. Phương án A đầy đủ nhất; các phương án khác đều thiếu một số vai trò."},{"id":"C2-024","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nếu có bộ óc của con người và có thế giới khách quan nhưng không có hoạt động thực tiễn xã hội thì ý thức có ra đời không? Vì sao?","opts":["Không, vì hoạt động thực tiễn làm cho ý thức phát triển","Không, vì hoạt động thực tiễn xã hội là nguồn gốc trực tiếp của ý thức","Có, vì bộ não con người là quan trọng nhất","Có, vì bộ não và hiện thực khách quan là điều kiện cần để ý thức ra đời"],"ans":1,"ex":"Bộ óc và thế giới khách quan mới là điều kiện cần. Ý thức chỉ ra đời khi có **hoạt động thực tiễn xã hội** (lao động và ngôn ngữ), vì đây là **nguồn gốc trực tiếp**, quyết định sự hình thành ý thức. Phương án A chưa chính xác vì nó chỉ nói thực tiễn làm ý thức \"phát triển\", chưa nêu được thực tiễn là nguồn gốc làm ý thức ra đời."},{"id":"C2-025","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng điền vào chỗ trống: “Ý thức chẳng qua chỉ là ... được đem chuyển vào trong đầu óc con người và được cải biến đi trong đó\"?","opts":["Vật chất","Cảm giác","Hình ảnh","Suy nghĩ"],"ans":0,"ex":"Đây là luận điểm của C. Mác trong lời bạt \"Tư bản\": ý thức chẳng qua chỉ là **cái vật chất** được đem chuyển vào trong đầu óc con người và được cải biến đi trong đó. Luận điểm này vừa khẳng định ý thức có nội dung là thế giới vật chất, vừa nhấn mạnh tính chủ quan, sáng tạo của sự phản ánh."},{"id":"C2-026","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Bản chất của ý thức theo quan điểm của chủ nghĩa duy vật biện chứng là gì?","opts":["Hình ảnh của thế giới chủ quan và khách quan","Quá trình vật chất vận động bên trong bộ não","Sự phản ánh tích cực, năng động, sáng tạo thế giới khách quan vào trong đầu óc con người","Tiếp nhận và xử lý các kích thích từ môi trường bên ngoài vào bên trong bộ não"],"ans":2,"ex":"**Bản chất của ý thức** là sự phản ánh **tích cực, năng động, sáng tạo** thế giới khách quan vào bộ óc người; ý thức là hình ảnh chủ quan của thế giới khách quan và có bản chất xã hội. Coi ý thức là quá trình vật chất trong não là quan điểm duy vật tầm thường; coi nó chỉ là sự tiếp nhận, xử lý kích thích thì chưa nói lên tính sáng tạo."},{"id":"C2-027","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Yếu tố căn bản để phân biệt trình độ phản ánh ý thức của con người với trình độ phản ánh tâm lý của động vật là gì?","opts":["Tính tích cực, chủ động, năng động, sáng tạo","Tính thích nghi","Phản xạ có điều kiện","Phản ánh vô điều kiện"],"ans":0,"ex":"Tâm lý động vật chỉ là phản ánh mang tính bản năng, nhằm thích nghi với môi trường (phản xạ có và không điều kiện). Ý thức con người khác về chất ở **tính tích cực, chủ động, năng động, sáng tạo**: con người có thể khái quát, dự báo, tạo ra tri thức mới và cải tạo thế giới. Tính thích nghi hay phản xạ là những đặc điểm chung với động vật."},{"id":"C2-028","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Tại sao ý thức có khả năng tác động trở lại hiện thực khách quan?","opts":["Ý thức là thuộc tính của một dạng vật chất đặc biệt","Ý thức có thể phản ánh đúng hiện thực khách quan","Ý thức có thể phản ánh sáng tạo, tích cực ngoài giới hạn của hiện thực khách quan","Do hoạt động thực tiễn có ý thức của con người"],"ans":2,"ex":"Vì ý thức là sự phản ánh **sáng tạo, tích cực**, nó không chỉ sao chép thế giới mà còn tạo ra tri thức mới, mục đích, kế hoạch, mô hình mà hiện thực chưa có. Chính khả năng vượt trước hiện thực đó tạo cơ sở để ý thức định hướng và tác động trở lại hiện thực. Tuy nhiên, sự tác động này chỉ thực hiện được thông qua **hoạt động thực tiễn** của con người."},{"id":"C2-029","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, mệnh đề nào dưới đây là đúng?","opts":["Ý thức là tồn tại duy nhất, tuyệt đối, là tính thứ nhất từ đó sinh ra tất cả; còn thế giới vật chất chỉ là bản sao, biểu hiện khác của ý thức tinh thần, là tính thứ hai, do ý thức tinh thần sinh ra.","Vật chất sinh ra ý thức và quyết định ý thức nhưng không chịu sự tác động gì từ ý thức.","Vật chất và ý thức có mối quan hệ biện chứng, tác động lẫn nhau trong đó vật chất là cái có trước, sinh ra và quyết định ý thức, còn ý thức sau khi được sinh ra cũng có tính độc lập tương đối, có khả năng tác động trở lại vật chất.","Vật chất là tồn tại duy nhất, tuyệt đối, là tính thứ nhất từ đó sinh ra ý thức, đồng thời tồn tại độc lập, riêng rẽ hoàn toàn với ý thức."],"ans":2,"ex":"Theo chủ nghĩa duy vật biện chứng, vật chất và ý thức có **quan hệ biện chứng**: vật chất có trước, sinh ra và quyết định ý thức; ý thức có **tính độc lập tương đối** và tác động trở lại vật chất thông qua thực tiễn. Phương án A là quan điểm duy tâm; phương án B và D là quan điểm duy vật siêu hình vì phủ nhận vai trò của ý thức."},{"id":"C2-030","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Dựa trên cơ sở nào để triết học Mác – Lênin cho rằng: Vật chất và ý thức là hai hiện tượng chung nhất của thế giới hiện thực, mặc dù khác nhau về bản chất, nhưng giữa chúng luôn có mối liên hệ biện chứng?","opts":["Nhận thức đúng về nguồn gốc ra đời của ý thức","Nhận thức đúng về mối quan hệ giữa vật chất và ý thức","Nhận thức đúng về nguồn gốc ra đời của vật chất","Nhận thức đúng về tính quyết định của vật chất với ý thức"],"ans":1,"ex":"Kết luận rằng vật chất và ý thức khác nhau về bản chất nhưng gắn bó biện chứng được rút ra từ **sự nhận thức đúng về mối quan hệ giữa vật chất và ý thức**: vật chất quyết định ý thức, còn ý thức tác động trở lại vật chất. Các phương án khác chỉ nêu một khía cạnh (nguồn gốc của ý thức, hay tính quyết định của vật chất), chưa bao quát được mối quan hệ hai chiều."},{"id":"C2-031","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hãy xác định mệnh đề đúng về vai trò của ý thức?","opts":["Ý thức cải biến hiện thực thông qua khoa học","Ý thức tự nó cải tạo được hiện thực","Ý thức cải biến hiện thực thông qua hoạt động thực tiễn của con người","Ý thức phản ánh nhưng không thể cải biến hiện thực"],"ans":2,"ex":"Bản thân ý thức không trực tiếp làm thay đổi được gì trong hiện thực. Ý thức chỉ **cải biến hiện thực thông qua hoạt động thực tiễn** của con người: định hướng mục tiêu, xây dựng kế hoạch, tổ chức hành động. Phương án \"tự nó cải tạo\" là quan điểm duy tâm; \"không thể cải biến\" là quan điểm duy vật siêu hình; khoa học cũng chỉ phát huy tác dụng khi được vận dụng vào thực tiễn."},{"id":"C2-032","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ý thức có thể tác động ngược trở lại vật chất thông qua hoạt động nào dưới đây?","opts":["Nhận thức cảm tính","Tự bản thân ý thức đã tác động ngược trở lại vật chất","Thông qua lực lượng siêu nhiên ở bên ngoài","Hoạt động thực tiễn"],"ans":3,"ex":"Ý thức tác động trở lại vật chất **thông qua hoạt động thực tiễn**. Tri thức, ý chí, tình cảm chỉ trở thành lực lượng vật chất khi con người vận dụng chúng để tác động vào thế giới. Nhận thức cảm tính chỉ là một giai đoạn của nhận thức; cho rằng ý thức tự tác động hoặc do lực lượng siêu nhiên là quan điểm duy tâm."},{"id":"C2-033","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng về vai trò của vật chất đối với ý thức theo quan điểm của chủ nghĩa duy vật biện chứng?","opts":["Vật chất quyết định nguồn gốc và nội dung của ý thức; nội dung của ý thức là sự phản ánh đối với vật chất","Vật chất quyết định sự biến đổi, phát triển của ý thức; sự biến đổi của ý thức là sự phản ánh đối với sự biến đổi của vật chất","Vật chất là nhân tố quyết định, phát huy tính năng động sáng tạo của ý thức trong hoạt động thực tiễn","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Vật chất quyết định ý thức trên nhiều phương diện: **nguồn gốc**, **nội dung**, **bản chất** và **sự vận động, biến đổi** của ý thức. Đồng thời, các điều kiện vật chất cũng quyết định việc ý thức phát huy tính năng động sáng tạo được đến đâu trong thực tiễn. Cả ba nhận định đều đúng nên chọn D."},{"id":"C2-034","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu tục ngữ, thành ngữ nào sau đây phản ánh vai trò quyết định của vật chất đối với ý thức?","opts":["Nước chảy đá mòn","Có thực mới vực được đạo","Tốt gỗ hơn tốt nước sơn","Ở bầu thì tròn ở ống thì dài"],"ans":1,"ex":"\"Có thực mới vực được đạo\" cho thấy phải có điều kiện vật chất (cái ăn, cái mặc) thì mới nói đến đời sống tinh thần, đạo đức. Câu này thể hiện **vai trò quyết định của vật chất đối với ý thức**. \"Nước chảy đá mòn\" gần với quy luật lượng – chất; \"tốt gỗ hơn tốt nước sơn\" nói về nội dung và hình thức."},{"id":"C2-035","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu thành ngữ nào sau đây phản ánh sự tác động trở lại của ý thức đối với vật chất?","opts":["Rút dây động rừng","Có thực mới vực được đạo","Thuận vợ thuận chồng tát biển Đông cũng cạn","Đi một ngày đàng học một sàng khôn"],"ans":2,"ex":"\"Thuận vợ thuận chồng tát biển Đông cũng cạn\" đề cao sự đồng lòng, thống nhất ý chí, tức yếu tố tinh thần, có thể tạo nên sức mạnh cải biến hoàn cảnh. Đây là biểu hiện của **sự tác động trở lại của ý thức đối với vật chất**. \"Có thực mới vực được đạo\" thì nói chiều ngược lại; \"rút dây động rừng\" gần với nguyên lý mối liên hệ phổ biến."},{"id":"C2-036","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khi sinh viên không ngừng học tập, chiếm lĩnh tri thức, làm chủ khoa học công nghệ để thay đổi hoàn cảnh, tương lai của mình.., điều này phản ánh nội dung nào sau đây?","opts":["Vật chất là cái có trước và giữ vai trò quyết định","Vật chất tồn tại song song với ý thức","Vai trò của ý thức trong sự tác động trở lại vật chất","Vai trò của vật chất tác động trở lại ý thức"],"ans":2,"ex":"Tri thức khoa học là một bộ phận của ý thức. Khi được tiếp thu và vận dụng vào hoạt động thực tiễn, tri thức giúp con người cải biến hoàn cảnh sống của mình. Đó là **vai trò tác động trở lại của ý thức đối với vật chất**. Không có \"vật chất tác động trở lại ý thức\" vì vật chất là cái quyết định; còn quan niệm tồn tại song song là nhị nguyên luận."},{"id":"C2-037","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đảng Cộng sản Việt Nam đã khẳng định: “Mọi chủ trương, đường lối của Đảng phải xuất phát từ thực tế, tôn trọng quy luật khách quan\". Quan điểm này vận dụng từ nội dung triết học nào dưới đây?","opts":["Nguyên lý về mối liên hệ phổ biến","Vật chất quyết định ý thức","Nguyên lý về sự phát triển","Cơ sở hệ tầng quyết định kiến trúc thượng tầng"],"ans":1,"ex":"Nguyên tắc \"xuất phát từ thực tế, tôn trọng quy luật khách quan\" là sự vận dụng trực tiếp luận điểm **vật chất quyết định ý thức**. Nội dung của ý thức do hiện thực khách quan quy định, nên mọi chủ trương phải căn cứ vào điều kiện vật chất hiện có và tránh bệnh chủ quan duy ý chí. Luận điểm cơ sở hạ tầng – kiến trúc thượng tầng thuộc chủ nghĩa duy vật lịch sử, không trực tiếp nói về điều này."},{"id":"C2-038","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vận dụng nội dung triết học nào dưới đây để giải thích hiện tượng: “Trẻ em ở thành thị trường năng động, thông minh hơn trẻ em ở nông thôn”?","opts":["Mối quan hệ nguyên nhân, kết quả","Nguyên lý về sự phát triển","Mối quan hệ giữa vật chất và ý thức","Nguyên lý mối liên hệ phổ biến"],"ans":2,"ex":"Môi trường sống, điều kiện vật chất, giáo dục và thông tin ở đô thị phong phú hơn, nên ảnh hưởng đến sự phát triển nhận thức, năng lực của trẻ. Đáp án gốc dùng **mối quan hệ giữa vật chất và ý thức** (vật chất quyết định ý thức) để giải thích hiện tượng này. Cần hiểu đây là xu hướng chịu tác động của hoàn cảnh, không phải kết luận tuyệt đối về trí thông minh."},{"id":"C2-039","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vận dụng nội dung triết học nào dưới đây để giải thích việc: “Xét về tương quan lực lượng, cơ sở vật chất có sự chênh lệch rất lớn nhưng Việt Nam đã giành thắng lợi trong cuộc đấu tranh chống lại 2 cường quốc lớn nhất thế giới là thực dân Pháp và đế quốc Mỹ ở thế kỷ XX”?","opts":["Vật chất quyết định ý thức","Tính độc lập tương đối của ý thức so với vật chất","Nguyên lý mối liên hệ phổ biến","Nguyên nhân và kết quả"],"ans":1,"ex":"Thắng lợi của Việt Nam trước những đối thủ vượt trội về vật chất là minh chứng cho **tính độc lập tương đối của ý thức**. Ý thức có thể tác động mạnh mẽ trở lại vật chất qua thực tiễn: tinh thần yêu nước, ý chí độc lập, đường lối đúng đắn đã trở thành sức mạnh vật chất. Nếu chỉ áp dụng \"vật chất quyết định ý thức\" một cách máy móc thì không giải thích được hiện tượng này."},{"id":"C2-040","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nguyên tắc phương pháp luận nào được rút ra từ mối quan hệ giữa vật chất và ý thức trong triết học Mác – Lênin?","opts":["Quan điểm toàn diện","Quan điểm khách quan","Quan điểm lịch sử - cụ thể","Quan điểm phát triển"],"ans":1,"ex":"Từ mối quan hệ vật chất – ý thức rút ra **nguyên tắc khách quan**: mọi nhận thức và hành động phải xuất phát từ thực tế khách quan, tôn trọng quy luật, đồng thời phát huy tính năng động chủ quan. Quan điểm toàn diện và lịch sử – cụ thể được rút ra từ nguyên lý mối liên hệ phổ biến; quan điểm phát triển được rút ra từ nguyên lý về sự phát triển."},{"id":"C2-041","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Điền vào chỗ trống: “… là sự thống nhất giữa thế giới quan duy vật biện chứng và phương pháp luận biện chứng duy vật; giữa lý luận nhận thức và lôgíc biện chứng; được chứng minh bằng sự phát triển của khoa học tự nhiên trước đó”.","opts":["Phép biện chứng","Phép biện chứng duy tâm","Phép biện chứng duy vật","Phép biện chứng chất phác"],"ans":2,"ex":"**Phép biện chứng duy vật** do C. Mác và Ph. Ăngghen sáng lập, V.I. Lênin phát triển. Đây là hình thức cao nhất của phép biện chứng, thống nhất thế giới quan duy vật với phương pháp luận biện chứng, thống nhất lý luận nhận thức với lôgíc biện chứng. Phép biện chứng chất phác (cổ đại) và phép biện chứng duy tâm (Hêghen) chưa đạt được sự thống nhất này."},{"id":"C2-042","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Thế nào là biện chứng khách quan?","opts":["Là khái niệm dùng để chỉ mối liên hệ biến đổi, phát triển khách quan vốn có của các sự vật hiện tượng","Là khái niệm dùng để chỉ mối liên hệ vốn có của ý niệm","Là khái niệm dùng để chỉ ra sự biến đổi của thế giới tinh thần","Là kết quả của biện chứng chủ quan"],"ans":0,"ex":"**Biện chứng khách quan** là biện chứng của bản thân thế giới vật chất. Nó chỉ các mối liên hệ, sự vận động, biến đổi, phát triển vốn có của sự vật, hiện tượng, tồn tại độc lập với ý thức. Biện chứng khách quan quyết định biện chứng chủ quan, chứ không phải ngược lại. Biện chứng của \"ý niệm\" là cách hiểu duy tâm của Hêghen."},{"id":"C2-043","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Thế nào là biện chứng chủ quan?","opts":["Là biện chứng của thế giới vật chất, tồn tại độc lập với ý thức của con người.","Là sự phản ánh biện chứng khách quan được phản ánh vào đầu óc con người, biện chứng của chính quá trình nhận thức, biện chứng của tư duy.","Là bản chất của biện chứng khách quan.","Là sự biến đổi do lực lượng siêu nhiên bên ngoài tác động vào bộ não con người."],"ans":1,"ex":"**Biện chứng chủ quan** là sự phản ánh biện chứng khách quan vào bộ óc con người, tức là biện chứng của quá trình nhận thức, của tư duy. Nó bị biện chứng khách quan quy định về nội dung. Phương án A mô tả biện chứng khách quan; phương án D mang tính duy tâm thần bí."},{"id":"C2-044","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"“Mối liên hệ” là gì?","opts":["Là khái niệm cơ bản của phép biện chứng được sử dụng để chỉ sự ràng buộc quy định lẫn nhau, đồng thời là sự tác động làm biến đổi lẫn nhau giữa các sự vật hiện tượng.","Là khái niệm của phép biện chứng dùng chỉ sự nương tựa vào nhau của thế giới tinh thần.","Là khái niệm của phép biện chứng dùng chỉ mối quan hệ một chiều giữa các sự vật, hiện tượng.","Là khái niệm của phép biện chứng dùng để chỉ sự tác động bên ngoài của các sự vật, hiện tượng."],"ans":0,"ex":"**Mối liên hệ** là phạm trù dùng để chỉ sự **quy định lẫn nhau, tác động qua lại và chuyển hóa lẫn nhau** giữa các sự vật, hiện tượng hoặc giữa các mặt, yếu tố trong một sự vật. Mối liên hệ mang tính nhiều chiều, cả bên trong lẫn bên ngoài. Vì vậy, các phương án \"một chiều\", \"chỉ bên ngoài\" hay \"thế giới tinh thần\" đều sai."},{"id":"C2-045","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Tính khách quan của mối liên hệ là gì?","opts":["Là mối liên hệ vốn có của thế giới các ý niệm","Là mối liên hệ vốn có của sự vật hiện tượng. Cơ sở của nó là tính thống nhất vật chất của thế giới.","Là mối liên hệ khách quan tồn tại bên trong ý thức của con người.","Là phụ thuộc vào ý chí của con người"],"ans":1,"ex":"Mối liên hệ có **tính khách quan** vì nó là cái vốn có của sự vật, hiện tượng, không phụ thuộc vào ý chí con người. **Cơ sở** của mối liên hệ phổ biến là **tính thống nhất vật chất của thế giới**: mọi sự vật chỉ là những dạng tồn tại khác nhau của một thế giới vật chất duy nhất. Coi mối liên hệ thuộc ý niệm hay ý thức là quan điểm duy tâm."},{"id":"C2-046","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu thành ngữ “Một con ngựa đau, cả tàu bỏ cỏ” tương đồng với nội dung triết học nào dưới đây?","opts":["Mối quan hệ nguyên nhân, kết quả","Nguyên lý về sự phát triển","Quy luật lượng – chất","Nguyên lý mối liên hệ phổ biến"],"ans":3,"ex":"\"Một con ngựa đau, cả tàu bỏ cỏ\" thể hiện sự gắn bó, tác động qua lại giữa các thành viên trong một tập thể: điều xảy ra với một cá thể ảnh hưởng đến những cá thể khác. Nội dung này tương đồng với **nguyên lý về mối liên hệ phổ biến**. Câu này không nhấn mạnh quan hệ sản sinh nhân quả hay sự biến đổi về lượng và chất."},{"id":"C2-047","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu thành ngữ nào dưới đây có nội dung tương đồng với nguyên lý về mối liên hệ phổ biến trong phép biện chứng duy vật?","opts":["Gieo nhân nào, gặt quả ấy","Đánh rắn động cỏ, rút dây động rừng","Hổ phụ sinh hổ tử","Mạnh vì gạo, bạo vì tiền"],"ans":1,"ex":"\"Đánh rắn động cỏ, rút dây động rừng\" cho thấy tác động vào một sự vật sẽ kéo theo ảnh hưởng đến các sự vật liên quan. Câu này tương đồng với **nguyên lý mối liên hệ phổ biến**. \"Gieo nhân nào gặt quả ấy\" nói về quan hệ nhân quả; \"hổ phụ sinh hổ tử\" nói về tính kế thừa, di truyền."},{"id":"C2-048","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn cụm từ thích hợp vào dấu … để được luận điểm đúng của chủ nghĩa duy vật biện chứng: “Khi xem xét các sự vật hiện tượng, các quan điểm toàn diện, quan điểm phát triển, quan điểm lịch sử cụ thể phải...”.","opts":["Tách rời nhau hoàn toàn.","Không tách rời nhau.","Có lúc tách rời nhau, có lúc không","Hoán đổi cho nhau"],"ans":1,"ex":"Ba quan điểm phương pháp luận **toàn diện, phát triển, lịch sử – cụ thể** đều được rút ra từ hai nguyên lý của phép biện chứng duy vật. Chúng bổ sung cho nhau nên phải được vận dụng **không tách rời nhau**. Xem xét toàn diện mà không thấy sự phát triển, hoặc không đặt sự vật vào hoàn cảnh cụ thể, sẽ rơi vào phiến diện hoặc chiết trung."},{"id":"C2-049","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn cụm từ thích hợp vào dấu … để được luận điểm của chủ nghĩa duy vật biện chứng: “Nguyên lý về mối liên hệ phổ biến và nguyên lý về sự phát triển phải…”.","opts":["Đồng nhất với nhau một cách hoàn toàn.","Độc lập với nhau một cách hoàn toàn.","Quan hệ chặt chẽ với nhau, nhưng không đồng nhất với nhau","Phải thống nhất với nhau"],"ans":2,"ex":"Hai nguyên lý của phép biện chứng duy vật **quan hệ chặt chẽ nhưng không đồng nhất**. Mối liên hệ, tác động qua lại là cơ sở, điều kiện của vận động và phát triển; phát triển là khuynh hướng chung của vận động trong các mối liên hệ. Mỗi nguyên lý có nội dung riêng và là cơ sở của những quan điểm phương pháp luận riêng."},{"id":"C2-050","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Cơ sở khoa học của quan điểm phát triển là gì?","opts":["Nguyên lý về mối liên hệ phổ biến.","Nguyên lý về sự phát triển.","Nguyên lý về tính thống nhất vật chất của thế giới","Cả ba đáp án trên"],"ans":1,"ex":"**Quan điểm phát triển** được rút ra trực tiếp từ **nguyên lý về sự phát triển**: mọi sự vật luôn vận động, phát triển, nên phải xem xét sự vật trong quá trình biến đổi và dự báo được khuynh hướng của nó. Nguyên lý mối liên hệ phổ biến là cơ sở của quan điểm toàn diện và quan điểm lịch sử – cụ thể."},{"id":"C2-051","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","opts":[".Nguyện vọng, ý chí của con người tự nó tác động đến sự phát triển.","Nguyện vọng, ý chí của con người không có ảnh hưởng gì đến sự phát triển.","Nguyện vọng, ý chí của con người có ảnh hưởng đến sự phát triển thông qua hoạt động thực tiễn","Sự phát triển chỉ là sự tăng lên về mặt số lượng"],"ans":2,"ex":"Phát triển mang **tính khách quan**, nguồn gốc của nó nằm trong mâu thuẫn bên trong sự vật. Nhưng nguyện vọng, ý chí của con người có thể thúc đẩy hoặc kìm hãm sự phát triển **thông qua hoạt động thực tiễn**. Cho rằng ý chí tự nó tác động là quan điểm duy tâm; phủ nhận hoàn toàn vai trò của ý chí là quan điểm máy móc; quy phát triển về sự tăng lên về lượng là quan điểm siêu hình."},{"id":"C2-052","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong xã hội sự phát triển biểu hiện ra như thế nào?","opts":["Sự xuất hiện các hợp chất mới.","Sự xuất hiện các giống loài động vật, thực vật mới thích ứng tốt hơn với môi trường.","Sự thay thế chế độ xã hội này bằng một chế độ xã hội khác dân chủ, văn minh hơn.","Tất cả đáp án trên"],"ans":2,"ex":"Phát triển biểu hiện khác nhau trong từng lĩnh vực: trong giới vô cơ là sự xuất hiện hợp chất mới; trong giới hữu cơ là các giống loài thích nghi tốt hơn; **trong xã hội** là **sự thay thế chế độ xã hội này bằng chế độ xã hội khác tiến bộ, văn minh hơn**. Hai phương án A và B thuộc lĩnh vực tự nhiên nên không phải câu trả lời."},{"id":"C2-053","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn cụm từ thích hợp vào dấu … để được định nghĩa về phạm trù: “phạm trù là những ... phản ánh những mặt, những thuộc tính, những mối liên hệ chung, cơ bản nhất của các sự vật và hiện tượng thuộc một lĩnh vực nhất định”.","opts":["Khái niệm.","Khái niệm rộng nhất.","Khái niệm cơ bản nhất.","Cả ba đáp án trên"],"ans":1,"ex":"Theo giáo trình, **phạm trù** là những **khái niệm rộng nhất** phản ánh những mặt, thuộc tính, mối liên hệ chung, cơ bản nhất của sự vật, hiện tượng **thuộc một lĩnh vực nhất định**. Mỗi khoa học có hệ thống phạm trù riêng, ví dụ phạm trù \"hàng hóa\" trong kinh tế học. Cần phân biệt với phạm trù triết học, vốn bao quát toàn bộ thế giới."},{"id":"C2-054","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"“Cái riêng, Cái chung”; “Nguyên nhân, Kết quả”; “Tất nhiên, Ngẫu nhiên”; “Nội dung, Hình thức”; “Bản chất, Hiện tượng”; “Khả năng, Hiện thực” đó là các … của triết học Mác – Lênin.","opts":["Cặp khái niệm","Thuật ngữ cơ bản","Cặp phạm trù cơ bản","Cặp phạm trù"],"ans":2,"ex":"Phép biện chứng duy vật nghiên cứu **sáu cặp phạm trù cơ bản**: cái riêng – cái chung, nguyên nhân – kết quả, tất nhiên – ngẫu nhiên, nội dung – hình thức, bản chất – hiện tượng, khả năng – hiện thực. Chúng phản ánh những mối liên hệ phổ biến, cơ bản nhất của thế giới. Gọi chúng là \"cặp phạm trù\" thì chưa đủ, phải là \"cặp phạm trù cơ bản\"."},{"id":"C2-055","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Các phạm trù được hình thành do đâu?","opts":["Một cách bẩm sinh trong ý thức của con người","Sẵn có ở bên ngoài, độc lập với ý thức của con người","Thông qua quá trình hoạt động, nhận thức và thực tiễn của con người","Tất cả các đáp án trên"],"ans":2,"ex":"Phạm trù không có sẵn trong ý thức (như chủ nghĩa duy lý tiên nghiệm của Cantơ quan niệm), cũng không tồn tại sẵn bên ngoài như những thực thể độc lập. Phạm trù **hình thành qua quá trình hoạt động nhận thức và thực tiễn** của con người. Vì vậy phạm trù có **nội dung khách quan, hình thức chủ quan** và luôn vận động, phát triển."},{"id":"C2-056","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn cụm từ thích hợp vào chỗ trống để được định nghĩa phạm trù triết học: “Phạm trù triết học là những ...(1)... phản ánh những mặt, những mối liên hệ cơ bản và phổ biến nhất của ...(2)... hiện thực”.","opts":["1- khái niệm, 2- các sự vật của.","1- Khái niệm rộng nhất, 2- một lĩnh vực của.","1- Khái niệm chung nhất, 2- toàn bộ thế giới","1- Khái niệm, 2- toàn bộ thế giới"],"ans":2,"ex":"**Phạm trù triết học** là những **khái niệm chung nhất**, phản ánh những mặt, mối liên hệ cơ bản và phổ biến nhất của **toàn bộ thế giới hiện thực**, bao gồm cả tự nhiên, xã hội và tư duy. Phạm trù của các khoa học cụ thể chỉ phản ánh \"một lĩnh vực\" nhất định; đây là điểm phân biệt giữa hai loại."},{"id":"C2-057","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Cái riêng là một phạm trù triết học được hiểu là?","opts":["Những mặt, những thuộc tính chung của nhiều sự vật","Một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định","Những nét, những thuộc tính chỉ có ở một sự vật","Các yếu tố cấu thành một hệ thống"],"ans":1,"ex":"**Cái riêng** là phạm trù chỉ **một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định**, ví dụ một con người hay một quốc gia cụ thể. Cần phân biệt: những thuộc tính chung của nhiều sự vật là **cái chung**, còn những nét chỉ có ở một sự vật là **cái đơn nhất**."},{"id":"C2-058","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Cái đơn nhất là một phạm trù triết học được hiểu là?","opts":["Tồn tại ở nhiều sự vật, hiện tượng","Chỉ tồn tại ở một sự vật, hiện tượng, tuyệt đối không lặp lại sự vật hiện tượng khác","Tồn tại ở một sự vật, hiện tượng, trong một quan hệ xác định","Không có phương án nào"],"ans":1,"ex":"**Cái đơn nhất** là phạm trù chỉ những mặt, đặc điểm **chỉ vốn có ở một sự vật, hiện tượng** (một kết cấu vật chất) và **không lặp lại** ở sự vật, hiện tượng khác. Ví dụ là dấu vân tay của mỗi người. Phương án \"tồn tại ở nhiều sự vật\" mô tả cái chung."},{"id":"C2-059","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Phạm trù triết học nào dùng để chỉ những thuộc tính chung, không những có ở một kết cấu vật chất nhất định mà còn được lặp lại trong nhiều sự vật, hiện tượng hay quá trình riêng lẻ khác?","opts":["Cái riêng","Cái chung","Cái đơn nhất","Tất cả đều sai"],"ans":1,"ex":"**Cái chung** là phạm trù chỉ những mặt, thuộc tính, mối liên hệ **lặp lại ở nhiều sự vật, hiện tượng** hay quá trình riêng lẻ. Ví dụ: mọi người đều có tư duy và ngôn ngữ. Cái riêng là bản thân từng sự vật; cái đơn nhất thì không lặp lại ở sự vật khác."},{"id":"C2-060","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Cái … chỉ tồn tại trong cái … thông qua cái riêng mà biểu hiện sự tồn tại của mình”.","opts":["Chung/Riêng","Riêng/Chung","Chung/Đơn nhất","Đơn nhất/Riêng"],"ans":0,"ex":"Theo quan điểm duy vật biện chứng, **cái chung chỉ tồn tại trong cái riêng, thông qua cái riêng** mà biểu hiện sự tồn tại của mình; không có cái chung thuần túy tách rời cái riêng. Ví dụ: \"con người nói chung\" chỉ tồn tại qua từng người cụ thể. Đảo ngược trật tự này là sai lầm của chủ nghĩa duy thực, vốn coi cái chung tồn tại độc lập."},{"id":"C2-061","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Cái … chỉ tồn tại trong mối liên hệ với cái …”.","opts":["Chung/Riêng","Riêng/Chung","Chung/Đơn nhất","Đơn nhất/Riêng"],"ans":1,"ex":"**Cái riêng chỉ tồn tại trong mối liên hệ với cái chung**: không có cái riêng nào tồn tại tuyệt đối biệt lập, mà mỗi cái riêng đều nằm trong các mối liên hệ dẫn tới cái chung. Luận điểm này bác bỏ chủ nghĩa duy danh, vốn chỉ thừa nhận cái riêng và coi cái chung chỉ là tên gọi."},{"id":"C2-062","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Cái … là cái toàn bộ, phong phú hơn cái …”.","opts":["Chung/Riêng","Riêng/Chung","Chung/Đơn nhất","Đơn nhất/Riêng"],"ans":1,"ex":"**Cái riêng là cái toàn bộ, phong phú hơn cái chung**, vì ngoài những đặc điểm chung, cái riêng còn có cái đơn nhất. Theo Lênin, cái riêng không gia nhập đầy đủ vào cái chung. Ví dụ: mỗi người, ngoài những thuộc tính chung của loài người, còn có cá tính riêng."},{"id":"C2-063","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Cái … là cái bộ phận, nhưng sâu sắc hơn cái …”.","opts":["Chung/Riêng","Riêng/Chung","Chung/Đơn nhất","Đơn nhất/Riêng"],"ans":0,"ex":"**Cái chung là cái bộ phận nhưng sâu sắc hơn cái riêng**, vì cái chung phản ánh những thuộc tính, mối liên hệ ổn định, tất nhiên, lặp lại ở nhiều cái riêng cùng loại. Do đó cái chung gắn với bản chất và quy luật. Đây là cơ sở để nhận thức phải tìm ra cái chung, và hoạt động thực tiễn phải dựa trên cái chung."},{"id":"C2-064","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Cái … và cái … có thể chuyển hóa lẫn nhau trong quá trình phát triển của sự vật”.","opts":["Chung/Riêng","Riêng/Chung","Chung/Đơn nhất","Đơn nhất/Riêng"],"ans":2,"ex":"Trong quá trình phát triển, **cái đơn nhất và cái chung có thể chuyển hóa lẫn nhau**. Cái mới ban đầu xuất hiện dưới dạng đơn nhất, sau đó phổ biến dần thành cái chung; ngược lại, cái cũ từ chỗ là cái chung dần mất đi và trở thành cái đơn nhất. Từ đây rút ra yêu cầu phương pháp luận: tạo điều kiện cho cái đơn nhất tích cực trở thành cái chung."},{"id":"C2-065","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Công cuộc xây dựng chủ nghĩa xã hội trên thế giới phải xuất phát từ tình hình cụ thể của từng đất nước. Đó là bài học về việc áp dụng sáng tạo nội dung nào trong triết học Mác - Lênin?","opts":["Cái chung phải tùy theo từng cái riêng cụ thể để vận dụng cho thích hợp.","Cái chung phải tùy theo từng cái đơn nhất cụ thể để vận dụng cho thích hợp.","Cái riêng phải dựa vào cái chung","Cái đặc thù của từng quốc gia"],"ans":0,"ex":"Lý luận về chủ nghĩa xã hội là **cái chung**; mỗi quốc gia với điều kiện lịch sử riêng là **cái riêng**. Vì cái chung chỉ tồn tại thông qua cái riêng, nên vận dụng cái chung phải **cá biệt hóa cho phù hợp với từng cái riêng cụ thể**, tránh rập khuôn máy móc hoặc cục bộ, xét lại. Đây là bài học vận dụng sáng tạo phép biện chứng giữa cái chung và cái riêng."},{"id":"C2-066","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đảng Cộng sản Việt Nam ra đời là sự kết hợp biện chứng bởi 3 yếu tố: phong trào đấu tranh của giai cấp công nhân, sự thấm nhuần của lý luận chủ nghĩa Mác – Lênin và phong trào yêu nước. Đây chính là sự vận dụng linh hoạt, sáng tạo của nội dung nào trong triết học?","opts":["Thống nhất giữa lý luận và thực tiễn","Vận dụng cái chung phải tính đến cái đặc thù, cái riêng","Quan điểm toàn diện","Không có đáp án nào đúng"],"ans":1,"ex":"Chủ nghĩa Mác – Lênin và phong trào công nhân là **cái chung** của quá trình hình thành đảng cộng sản trên thế giới. Ở Việt Nam, Hồ Chí Minh đã kết hợp thêm **phong trào yêu nước**, đây là **cái đặc thù, cái riêng** của một dân tộc thuộc địa. Như vậy, vận dụng cái chung đã có tính đến cái riêng. Ở góc độ rộng hơn, đây cũng là sự thống nhất giữa lý luận và thực tiễn."},{"id":"C2-067","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ở con người, yếu tố nào được coi là cái đặc thù, đơn nhất để phân biệt giữa người này với người khác?","opts":["Tên gọi","Nhóm máu","Dấu vân tay","Ngoại hình"],"ans":2,"ex":"**Dấu vân tay** là đặc điểm **không lặp lại** ở bất kỳ người nào khác, nên là ví dụ điển hình của **cái đơn nhất**. Tên gọi, nhóm máu hay ngoại hình đều có thể trùng nhau giữa nhiều người, nên chúng mang tính chung hoặc không đặc trưng tuyệt đối."},{"id":"C2-068","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Phạm trù nhằm chỉ sự tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau, gây ra một biến đổi nào đó, gọi là gì?","opts":["Nguyên nhân.","Kết quả.","Khả năng.","Không có đáp án nào đúng"],"ans":0,"ex":"**Nguyên nhân** là phạm trù chỉ **sự tác động lẫn nhau** giữa các mặt trong một sự vật, hoặc giữa các sự vật với nhau, gây ra một biến đổi nhất định. Cần lưu ý nguyên nhân là chính sự tác động, chứ không phải bản thân sự vật. Còn những biến đổi do tác động đó gây ra là **kết quả**."},{"id":"C2-069","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Phạm trù nhằm chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau gây ra, gọi là gì?","opts":["Nguyên nhân.","Kết quả.","Khả năng.","Hệ quả"],"ans":1,"ex":"**Kết quả** là phạm trù chỉ **những biến đổi xuất hiện** do sự tác động lẫn nhau giữa các mặt, các sự vật gây ra. Nguyên nhân sinh ra kết quả và luôn có trước kết quả. \"Hệ quả\" không phải là thuật ngữ của cặp phạm trù này; \"khả năng\" thuộc cặp phạm trù khả năng – hiện thực."},{"id":"C2-070","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Có rất nhiều loại nguyên nhân, như: nguyên nhân cơ bản, nguyên nhân chủ yếu, nguyên nhân bên trong, nguyên nhân bên ngoài, nguyên nhân chủ quan, nguyên nhân khách quan… Điều đó chứng tỏ:","opts":["Một kết quả chỉ có thể do một loại nguyên nhân gây ra.","Một kết quả có thể do nhiều loại nguyên nhân gây ra.","Một kết quả có thể không cần nguyên nhân gây ra.","Không thể nhận thức được quan hệ nguyên nhân – kết quả"],"ans":1,"ex":"Quan hệ nhân quả rất phức tạp: **một kết quả có thể do nhiều nguyên nhân gây ra**, và một nguyên nhân cũng có thể sinh ra nhiều kết quả. Vì thế cần phân loại nguyên nhân (cơ bản, chủ yếu, bên trong, bên ngoài, chủ quan, khách quan...) để xác định đúng vai trò của từng loại. Nói kết quả không cần nguyên nhân là phủ nhận tính khách quan, phổ biến của quan hệ nhân quả."},{"id":"C2-071","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hiện tượng “Đói nghèo” và “Dân trí thấp” thể hiện như thế nào trong mối quan hệ nhân quả?","opts":["Đói nghèo là nguyên nhân, dân trí thấp là kết quả.","Dân trí thấp là nguyên nhân, đói nghèo là kết quả.","Cả hai đều là nguyên nhân.","Hiện tượng này vừa là nguyên nhân vừa là kết quả của hiện tượng kia."],"ans":3,"ex":"Trong mối liên hệ phổ biến, nguyên nhân và kết quả có thể **đổi chỗ, chuyển hóa cho nhau**: cái trong quan hệ này là nguyên nhân thì trong quan hệ khác lại là kết quả. Đói nghèo dẫn đến dân trí thấp, và dân trí thấp lại làm đói nghèo kéo dài. Mỗi hiện tượng **vừa là nguyên nhân vừa là kết quả** của hiện tượng kia, tạo thành một vòng tác động qua lại."},{"id":"C2-072","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vật trong chân không luôn chuyển động với gia tốc 9,8 m/s2; nước ở áp suất 1 atmôtphe luôn sôi ở 100 0C. Điều này chứng tỏ…?","opts":["Giữa nguyên nhân và kết quả có mối quan hệ sản sinh.","Nguyên nhân luôn luôn có trước kết quả.","Một nguyên nhân nhất định, trong những hoàn cảnh giống nhau, sẽ tạo nên những kết quả giống nhau.","Đó là do lực lượng siêu nhiên ở bên ngoài quyết định và chi phối"],"ans":2,"ex":"Quan hệ nhân quả có **tính tất yếu**: **cùng một nguyên nhân, trong những điều kiện giống nhau, sẽ gây ra kết quả như nhau**. Các ví dụ về gia tốc rơi tự do hay nhiệt độ sôi của nước minh họa điều này. Phương án \"nguyên nhân có trước kết quả\" vẫn đúng về mặt lý thuyết nhưng không phải điều mà các ví dụ muốn chứng minh."},{"id":"C2-073","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong những hiện tượng của tự nhiên sau đây, hiện tượng nào thuộc mối quan hệ nhân quả?","opts":["Chớp – Sấm","Gà gáy – Trời sáng","Xuân – Hạ - Thu - Đông","Mưa, bão – chớp, sấm"],"ans":3,"ex":"Cần phân biệt quan hệ nhân quả với quan hệ chỉ **nối tiếp nhau về thời gian**. Gà gáy rồi trời sáng hay sự nối tiếp của bốn mùa không phải nhân quả. Chớp và sấm xuất hiện gần như đồng thời vì cùng do sự phóng điện gây ra, nên chớp không phải nguyên nhân của sấm. Theo đáp án gốc, các điều kiện của mưa bão (mây dông tích điện) là cái gây ra chớp, sấm, nên đây là quan hệ nhân quả."},{"id":"C2-074","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Cái do các nhân tố bên ngoài, do sự ngẫu hợp của nhiều hoàn cảnh bên ngoài quyết định, gọi là gì?","opts":["Tất nhiên.","Ngẫu nhiên.","Khả năng.","Không xác định"],"ans":1,"ex":"**Ngẫu nhiên** là phạm trù chỉ cái do các nhân tố bên ngoài, do sự **ngẫu hợp của nhiều hoàn cảnh bên ngoài** quyết định. Vì vậy nó có thể xuất hiện hoặc không, xuất hiện thế này hoặc thế khác. Ngược lại, **tất nhiên** do nguyên nhân cơ bản bên trong kết cấu vật chất quyết định, nên trong điều kiện nhất định thì phải xảy ra như thế."},{"id":"C2-075","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào chỗ trống: “Ngẫu nhiên là cái không do ...(1)... kết cấu vật chất quyết định, mà do ...(2)... quyết định”.","opts":["1- nguyên nhân, 2- hoàn cảnh bên ngoài.","1- Mối liên hệ bản chất bên trong, 2- nhân tố bên ngoài.","1- mối liên hệ bên ngoài, 2- mối liên hệ bên trong","1- mối liên hệ cơ bản, 2- mối liên hệ không cơ bản"],"ans":1,"ex":"**Ngẫu nhiên** không do mối liên hệ bản chất bên trong kết cấu vật chất quyết định, mà do các **nhân tố bên ngoài**, sự ngẫu hợp của hoàn cảnh quyết định. Ngược lại, cái tất nhiên là cái do mối liên hệ bản chất bên trong quy định. Đây là tiêu chí cơ bản để phân biệt hai phạm trù này."},{"id":"C2-076","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","opts":["Ngẫu nhiên và tất nhiên đều có nguyên nhân","Những hiện tượng chưa nhận thức được nguyên nhân là cái ngẫu nhiên.","Những hiện tượng nhận thức được nguyên nhân đều trở thành cái tất yếu","Cái tất nhiên là cái không thể nhận thức được"],"ans":0,"ex":"Theo chủ nghĩa duy vật biện chứng, **cả tất nhiên và ngẫu nhiên đều có nguyên nhân** và đều tồn tại khách quan: tất nhiên do nguyên nhân bên trong, ngẫu nhiên do nguyên nhân bên ngoài. Coi ngẫu nhiên là cái \"chưa biết nguyên nhân\" là sai lầm của quan niệm siêu hình (chẳng hạn của Đêmôcrít), vì nó đồng nhất ngẫu nhiên với sự hiểu biết hạn chế của con người."},{"id":"C2-077","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","opts":["Đối với sự phát triển của sự vật chỉ có cái tất nhiên mới có vai trò quan trọng.","Cái ngẫu nhiên không có vai trò gì đối với sự phát triển của sự vật","Cả cái tất yếu và cái ngẫu nhiên đều có vai trò quan trọng đối với sự phát triển của sự vật","Tất cả các đáp án đều đúng"],"ans":2,"ex":"**Cái tất nhiên** đóng vai trò **quyết định** chiều hướng phát triển của sự vật. **Cái ngẫu nhiên** có thể làm cho sự phát triển diễn ra nhanh hay chậm, và mang những sắc thái riêng. Cả hai đều có vai trò quan trọng, vì vậy hoạt động thực tiễn phải dựa vào cái tất nhiên nhưng không bỏ qua cái ngẫu nhiên."},{"id":"C2-078","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","opts":["Có tất nhiên thuần tuý tồn tại khách quan","Có ngẫu nhiên thuần tuý tồn tại khách quan","Không có cái tất nhiên và ngẫu nhiên thuần tuý tồn tại bên ngoài nhau","Cái tất nhiên chỉ tồn tại khi con người nhận thức được"],"ans":2,"ex":"Tất nhiên và ngẫu nhiên **thống nhất biện chứng**, không tồn tại thuần túy tách biệt nhau. Tất nhiên bao giờ cũng vạch đường đi cho mình thông qua vô số cái ngẫu nhiên, còn ngẫu nhiên là hình thức biểu hiện, là cái bổ sung cho tất nhiên. Phương án D sai vì tất nhiên tồn tại khách quan, không phụ thuộc vào việc con người có nhận thức được hay không."},{"id":"C2-079","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Tất nhiên biểu hiện sự tồn tại của mình thông qua vô vàn cái ngẫu nhiên.","Ngẫu nhiên là hình thức biểu hiện của cái tất nhiên.","Có cái ngẫu nhiên thuần tuý không thể hiện cái tất nhiên","Ở một số thời điểm, con người có thể không nhận thức được cái tất nhiên và ngẫu nhiên"],"ans":2,"ex":"Mệnh đề sai là cho rằng có **ngẫu nhiên thuần túy** không thể hiện tất nhiên. Theo Ph. Ăngghen, cái tất nhiên luôn biểu hiện qua vô số cái ngẫu nhiên, và cái ngẫu nhiên là **hình thức biểu hiện, cái bổ sung** của tất nhiên. Các phương án A, B, D đều phù hợp với quan điểm duy vật biện chứng."},{"id":"C2-080","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Nội dung là .... những mặt, những yếu tố, những quá trình tạo nên sự vật”.","opts":["Sự tác động","Sự kết hợp","Tổng hợp tất cả","Sự bao gồm"],"ans":2,"ex":"**Nội dung** là phạm trù chỉ **tổng hợp tất cả** những mặt, yếu tố, quá trình tạo nên sự vật. Ví dụ: nội dung của một cơ thể là tổng thể các cơ quan, quá trình sinh lý. Từ \"tổng hợp tất cả\" nhấn mạnh tính toàn bộ của nội dung, phân biệt nó với hình thức là phương thức tồn tại, cách tổ chức của nội dung."},{"id":"C2-081","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Hình thức là hệ thống ... giữa các yếu tố của sự vật”.","opts":["Mối liên hệ tương đối bền vững.","Hệ thống các bước chuyển hoá","Mặt đối lập","Mâu thuẫn được thiết lập"],"ans":0,"ex":"**Hình thức** là phương thức tồn tại và phát triển của sự vật, là **hệ thống các mối liên hệ tương đối bền vững** giữa các yếu tố cấu thành sự vật. Giáo trình chủ yếu nói đến **hình thức bên trong**, tức cấu trúc của nội dung. Mâu thuẫn hay bước chuyển hóa thuộc về các phạm trù và quy luật khác."},{"id":"C2-082","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Nội dung và hình thức không tách rời nhau.","Nội dung và hình thức luôn luôn phù hợp với nhau.","Không phải lúc nào nội dung và hình thức cũng phù hợp với nhau","Nội dung sẽ thông qua hình thức mà thể hiện ra"],"ans":1,"ex":"Nội dung và hình thức **thống nhất nhưng không phải lúc nào cũng phù hợp**. Nội dung là mặt động, biến đổi trước; hình thức tương đối ổn định nên có thể trở nên lạc hậu và kìm hãm nội dung, dẫn đến mâu thuẫn. Khi đó, hình thức cũ phải được thay bằng hình thức mới phù hợp hơn. Vì vậy mệnh đề \"luôn luôn phù hợp\" là sai."},{"id":"C2-083","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào chỗ trống: “Bản chất là tổng hợp tất cả những mặt, những mối liên hệ ...(1)...bên trong sự vật, quy định sự ...(2)... của sự vật”.","opts":["1- chung, 2- vận động và phát triển.","1- ngẫu nhiên, 2- tồn tại và biến đổi.","1- tất nhiên, tương đối ổn định, 2- vận động và phát triển","1- tất nhiên, tương đối ổn định, 2- tồn tại và biến đổi."],"ans":2,"ex":"Theo giáo trình, **bản chất** là tổng hợp tất cả những mặt, mối liên hệ **tất nhiên, tương đối ổn định** ở bên trong sự vật, quy định **sự vận động và phát triển** của sự vật. Bản chất gắn bó chặt chẽ với cái chung và quy luật. Các phương án \"chung\" hay \"ngẫu nhiên\" đều không nêu đúng đặc trưng của bản chất."},{"id":"C2-084","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Hiện tượng là ... của bản chất”.","opts":["Cơ sở.","Nguyên nhân","Biểu hiện ra bên ngoài","Nguồn gốc"],"ans":2,"ex":"**Hiện tượng** là sự **biểu hiện ra bên ngoài** của bản chất, tức những mặt, mối liên hệ mà ta có thể quan sát, cảm nhận được. Bản chất bộc lộ qua hiện tượng, còn hiện tượng là biểu hiện của bản chất. Hiện tượng không phải là cơ sở, nguyên nhân hay nguồn gốc của bản chất."},{"id":"C2-085","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Luận điểm nào sau đây là luận điểm của chủ nghĩa duy vật biện chứng về bản chất, hiện tượng?","opts":["Bản chất tồn tại khách quan bên ngoài sự vật","Hiện tượng là tổng hợp các cảm giác của con người","Bản chất và hiện tượng đều tồn tại khách quan, là cái vốn có của sự vật","Hiện tượng và bản chất luôn thống nhất với nhau"],"ans":2,"ex":"Theo chủ nghĩa duy vật biện chứng, **bản chất và hiện tượng đều tồn tại khách quan**, là cái vốn có của sự vật. Bản chất nằm bên trong sự vật chứ không ở ngoài nó. Coi hiện tượng là tổng hợp cảm giác là quan điểm duy tâm chủ quan. Bản chất và hiện tượng vừa thống nhất vừa mâu thuẫn, nên nói chúng \"luôn thống nhất\" là phiến diện."},{"id":"C2-086","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, đáp án nào sau đây là đúng?","opts":["Bản chất nào hiện tượng ấy, bản chất thay đổi hiện tượng biểu hiện nó cũng thay đổi","Bản chất không được biểu hiện ở hiện tượng","Bản chất nào hiện tượng ấy, bản chất hoàn toàn đồng nhất với hiện tượng.","Bản chất tồn tại khách quan bên ngoài sự vật"],"ans":0,"ex":"Bản chất và hiện tượng **thống nhất**: **bản chất nào hiện tượng ấy**, và khi bản chất thay đổi thì hiện tượng biểu hiện nó cũng thay đổi theo. Tuy vậy, chúng không đồng nhất hoàn toàn, vì hiện tượng phong phú hơn, còn bản chất sâu sắc hơn và hiện tượng có thể phản ánh bản chất một cách xuyên tạc. Bản chất cũng không tồn tại ngoài sự vật."},{"id":"C2-087","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, đáp án nào sau đây là sai?","opts":["Bản chất và hiện tượng không hoàn toàn phù hợp nhau.","Cùng một bản chất có thể biểu hiện ở nhiều hiện tượng khác nhau","Một bản chất không thể biểu hiện ở nhiều hiện tượng khác nhau","Một hiện tượng không thể nói lên được bản chất của sự vật"],"ans":2,"ex":"Cặp phạm trù **bản chất – hiện tượng**: bản chất là tổng hợp các mặt, mối liên hệ tất nhiên, tương đối ổn định bên trong; hiện tượng là sự biểu hiện ra bên ngoài của bản chất. Hai mặt thống nhất nhưng không hoàn toàn phù hợp, và một bản chất có thể biểu hiện qua nhiều hiện tượng khác nhau tùy điều kiện. Vì vậy khẳng định một bản chất không thể biểu hiện ở nhiều hiện tượng là sai."},{"id":"C2-088","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Người Việt Nam có Câu “Người khôn dồn ra nét mặt, què quặt hiện ra chân tay” tương đồng với nội dung cặp phạm trù nào của phép biện chứng?","opts":["Cái riêng, cái chung","Nguyên nhân, kết quả","Nội dung, hình thức","Bản chất, hiện tượng"],"ans":3,"ex":"Câu tục ngữ cho thấy cái bên trong (trí khôn, khiếm khuyết) bộc lộ ra cái bên ngoài (nét mặt, chân tay). Đó chính là quan hệ **bản chất – hiện tượng**: bản chất bao giờ cũng bộc lộ qua hiện tượng, hiện tượng là sự biểu hiện của bản chất. Không nên nhầm với nội dung – hình thức, vốn nói về các yếu tố cấu thành và phương thức tổ chức của sự vật."},{"id":"C2-089","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Khả năng là phạm trù triết học chỉ ... khi có các điều kiện thích hợp”.","opts":["Cái đang có, đang tồn tại","Cái chưa có, nhưng sẽ có","Cái không thể có","Cái tiền đề để tạo nên sự vật mới"],"ans":1,"ex":"Theo giáo trình, **khả năng** là phạm trù chỉ cái chưa xuất hiện, chưa có trong thực tế nhưng sẽ xuất hiện và trở thành hiện thực khi có các điều kiện tương ứng. Khả năng gắn với xu hướng vận động của sự vật, khác với cái không thể có. Cái đang có, đang tồn tại thuộc phạm trù hiện thực."},{"id":"C2-090","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …: “Hiện thực là phạm trù triết học chỉ cái…”.","opts":["Mối liên hệ giữa các sự vật.","Chưa có, chưa tồn tại","Đã từng xuất hiện và tồn tại","Hiện có đang tồn tại"],"ans":3,"ex":"**Hiện thực** là phạm trù chỉ cái hiện có, đang tồn tại trên thực tế và trong tư duy, bao gồm cả sự tồn tại vật chất lẫn tinh thần. Nó đối lập với khả năng là cái chưa có nhưng sẽ có. Phương án đã từng xuất hiện không đúng vì cái đã qua và không còn tồn tại thì không còn là hiện thực nữa."},{"id":"C2-091","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, đáp án nào sau đây là sai?","opts":["Cái hiện chưa có nhưng sẽ có là khả năng.","Cái hiện đang có là hiện thực.","Cái chưa cảm nhận được là khả năng","Mọi khả năng đều có thể trở thành hiện thực"],"ans":2,"ex":"Phân biệt khả năng và hiện thực dựa vào sự tồn tại khách quan: cái chưa có nhưng sẽ có là **khả năng**, cái đang có là **hiện thực**. Việc con người cảm nhận được hay chưa là tiêu chí chủ quan, không quyết định một cái là khả năng hay hiện thực, vì có những hiện thực tồn tại mà con người chưa cảm nhận được. Do đó đồng nhất cái chưa cảm nhận được với khả năng là sai."},{"id":"C2-092","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan niệm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Cùng một sự vật, trong những điều kiện nhất định tồn tại nhiều khả năng.","Một sự vật trong những điều kiện nhất định chỉ tồn tại một khả năng.","Hiện thực thay đổi khả năng cũng thay đổi","Hiện thực và khả năng có mối quan hệ biện chứng"],"ans":1,"ex":"Theo phép biện chứng duy vật, trong một sự vật ở những điều kiện nhất định thường tồn tại **nhiều khả năng**: khả năng thực tế và khả năng trừu tượng, khả năng tất nhiên và khả năng ngẫu nhiên. Khả năng nảy sinh từ hiện thực nên khi hiện thực thay đổi thì khả năng cũng thay đổi. Vì vậy cho rằng sự vật chỉ có một khả năng là sai."},{"id":"C2-093","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, đáp án nào sau đây là đúng?","opts":["Trong hoạt động thực tiễn phải dựa vào khả năng.","Trong hoạt động thực tiễn phải dựa vào hiện thực, đồng thời phải tính đến khả năng","Trong hoạt động thực tiễn phải dựa vào hiện thực, không cần tính đến khả năng.","Trong hoạt động thực tiễn nên dựa vào nhận thức cảm tính, bản năng"],"ans":1,"ex":"Ý nghĩa phương pháp luận của cặp phạm trù **khả năng – hiện thực**: trong hoạt động thực tiễn phải dựa vào hiện thực, vì chỉ hiện thực mới là cái tồn tại thực sự. Đồng thời cần tính đến các khả năng để dự kiến phương án, chủ động tạo điều kiện cho khả năng tốt trở thành hiện thực. Chỉ dựa vào khả năng là ảo tưởng, còn bỏ qua khả năng sẽ dẫn đến bị động."},{"id":"C2-094","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vai trò của quy luật từ những sự thay đổi dần về lượng dẫn đến sự thay đổi về chất và ngược lại (quy luật lượng – chất)?","opts":["Chỉ ra nguồn gốc, động lực phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Được coi là hạt nhân cơ bản của phép biện chứng duy vật.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng."],"ans":1,"ex":"Ba quy luật cơ bản có vai trò khác nhau. **Quy luật lượng – chất** chỉ ra cách thức, phương thức của sự vận động, phát triển: tích lũy dần về lượng vượt quá độ sẽ dẫn tới bước nhảy về chất. Quy luật mâu thuẫn chỉ ra nguồn gốc, động lực và được coi là hạt nhân; quy luật phủ định của phủ định chỉ ra khuynh hướng của sự phát triển."},{"id":"C2-095","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào chỗ trống: “Chất là phạm trù triết học dùng để chỉ ... (1) ... khách quan ... (2) ... là sự thống nhất hữu cơ những thuộc tính làm cho sự vật là nó chứ không là cái khác”.","opts":["1- Tính quy định, 2- Vốn có của sự vật.","1- Mối liên hệ, 2- Của các sự vật.","1- Các nguyên nhân, 2- Của các sự vật","1- Các nguyên nhân, 2- Vốn có của sự vật"],"ans":0,"ex":"**Chất** là phạm trù chỉ tính quy định khách quan vốn có của sự vật, là sự thống nhất hữu cơ các thuộc tính làm cho sự vật là nó mà không phải cái khác. Chất gắn liền với sự vật, không tồn tại tách rời sự vật. Các phương án về mối liên hệ hay nguyên nhân không phản ánh đúng định nghĩa này."},{"id":"C2-096","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Mỗi sự vật có nhiều thuộc tính.","Mỗi thuộc tính biểu hiện một mặt chất của sự vật.","Mỗi thuộc tính có thể đóng vai trò là tính quy định về chất trong một quan hệ nhất định.","Mỗi sự vật chỉ có một tính quy định về chất"],"ans":3,"ex":"Mỗi sự vật có nhiều thuộc tính, mỗi thuộc tính biểu hiện một mặt chất của sự vật. Tùy từng mối quan hệ cụ thể mà một thuộc tính có thể giữ vai trò tính quy định về chất, nên mỗi sự vật **có nhiều chất** chứ không chỉ một. Khẳng định mỗi sự vật chỉ có một tính quy định về chất là sai."},{"id":"C2-097","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào chỗ trống: “Lượng là phạm trù triết học dùng để chỉ...(1) ... của sự vật về mặt ...(2) ... của sự vận động và phát triển cũng như các thuộc tính của sự vật”.","opts":["1- tính quy định vốn có, 2- số lượng, quy mô, trình độ, nhịp điệu","1- mối liên hệ và phụ thuộc, 2- bản chất bên trong.","1- mức độ quy mô, 2- chất lượng, phẩm chất","1- tính quy định vốn có, 2- chất lượng, phẩm chất"],"ans":0,"ex":"**Lượng** là phạm trù chỉ tính quy định vốn có của sự vật về mặt số lượng, quy mô, trình độ, nhịp điệu của sự vận động và phát triển cũng như các thuộc tính của sự vật. Lượng có thể đo bằng đại lượng chính xác hoặc nhận biết bằng tư duy trừu tượng. Các phương án gắn lượng với chất lượng, phẩm chất là nhầm sang phạm trù chất."},{"id":"C2-098","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, đáp án nào sau đây là sai?","opts":["Lượng là tính quy định vốn có của sự vật.","Lượng nói lên quy mô, trình độ phát triển của sự vật","Lượng tồn tại khách quan gắn liền với sự vật","Lượng phụ thuộc vào ý chí của con người."],"ans":3,"ex":"Lượng là tính quy định vốn có, tồn tại **khách quan** gắn liền với sự vật, nói lên quy mô, trình độ phát triển của nó. Như mọi thuộc tính của thế giới vật chất, lượng không phụ thuộc vào ý chí con người; con người chỉ nhận thức và đo lường nó. Vì vậy cho rằng lượng phụ thuộc vào ý chí là sai."},{"id":"C2-099","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Sự phân biệt giữa chất và lượng phụ thuộc vào ý chí của con người.","Chất và lượng của sự vật đều tồn tại khách quan.","Không có chất lượng thuần tuý tồn tại bên ngoài sự vật.","Sự phân biệt giữa chất và lượng của sự vật có tính chất tương đối."],"ans":0,"ex":"Chất và lượng đều tồn tại **khách quan**, không có chất hay lượng thuần túy bên ngoài sự vật. Sự phân biệt giữa chất và lượng chỉ có tính tương đối, tùy theo mối quan hệ cụ thể: cái là chất trong quan hệ này có thể là lượng trong quan hệ khác. Sự phân biệt đó do quan hệ khách quan quy định chứ không do ý chí con người, nên luận điểm A sai."},{"id":"C2-100","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Sự biến đổi về chất là kết quả sự biến đổi về lượng của sự vật.","Không phải sự biến đổi về lượng nào cũng là ngay lập tức đưa đến sự thay đổi của chất.","Chất mới ra đời sẽ có sự tác động ngược trở lại đối với lượng","Chất mới ra đời không có tác động gì đến sự thay đổi của lượng"],"ans":3,"ex":"Quy luật lượng – chất có chiều ngược lại: chất mới ra đời sẽ **tác động trở lại lượng**, quy định quy mô, tốc độ, nhịp điệu mới của sự vận động và phát triển. Sự thay đổi về lượng chỉ dẫn đến thay đổi về chất khi vượt quá độ. Phủ nhận tác động của chất mới đối với lượng là sai."},{"id":"C2-101","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khoảng giới hạn lớn hơn 0 0C và nhỏ hơn 100 0C của nước trong điều kiện áp suất bình thường được gọi là gì trong quy luật lượng - chất?","opts":["Lượng","Độ","Bước nhảy","Chất"],"ans":1,"ex":"**Độ** là khoảng giới hạn trong đó sự thay đổi về lượng chưa làm thay đổi căn bản chất của sự vật. Với nước ở áp suất bình thường, nhiệt độ thay đổi trong khoảng từ trên 0°C đến dưới 100°C thì nước vẫn ở trạng thái lỏng. Vì vậy khoảng này là độ, không phải lượng hay bước nhảy."},{"id":"C2-102","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Giới hạn 0 0C và 100 0C của nước trong điều kiện áp suất bình thường được gọi là gì trong quy luật lượng - chất?","opts":["Lượng","Độ","Bước nhảy","Điểm nút"],"ans":3,"ex":"**Điểm nút** là thời điểm mà tại đó sự thay đổi về lượng đã đủ làm thay đổi về chất của sự vật. Các mốc 0°C và 100°C là giới hạn của độ, tại đó nước chuyển sang thể rắn hoặc thể hơi. Độ là khoảng nằm giữa hai điểm nút, còn bước nhảy là sự chuyển hóa diễn ra tại điểm nút."},{"id":"C2-103","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khi nước chuyển từ trạng thái lỏng sang trạng thái khí tại 100 0C được gọi là gì trong quy luật lượng - chất?","opts":["Độ","Chuyển hoá","Bước nhảy","Tiệm tiến"],"ans":2,"ex":"**Bước nhảy** là sự chuyển hóa về chất của sự vật do sự thay đổi về lượng trước đó gây ra; nó kết thúc một giai đoạn và mở đầu giai đoạn mới. Nước chuyển từ lỏng sang hơi ở 100°C là bước nhảy diễn ra tại điểm nút. Độ chỉ khoảng giới hạn chưa thay đổi chất, còn tiệm tiến là sự thay đổi dần dần."},{"id":"C2-104","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đâu là nội dung quy luật lượng – chất?","opts":["Phát triển của sự vật chỉ bao hàm sự thay đổi về lượng.","Phát triển của sự vật chỉ bao hàm sự thay đổi về chất.","Quá trình phát triển của sự vật là quá trình chuyển hoá từ sự thay đổi dần dần về lượng sang sự thay đổi về chất và ngược lại","Chất không có tác động gì đến sự thay đổi của lượng"],"ans":2,"ex":"Nội dung **quy luật lượng – chất**: mọi sự vật là thể thống nhất giữa chất và lượng; sự thay đổi dần về lượng vượt quá độ sẽ dẫn đến thay đổi về chất thông qua bước nhảy. Chất mới ra đời lại tác động trở lại lượng, tạo ra lượng mới. Các phương án chỉ nói một chiều về lượng hoặc chất, hay phủ nhận tác động của chất, đều không đầy đủ."},{"id":"C2-105","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu ca dao: “Một cây làm chẳng nên non. Ba cây chụm lại nên hòn núi cao” thể hiện nội dung quy luật nào của phép biện chứng duy vật?","opts":["Quy luật mâu thuẫn","Quy luật phủ định của phủ định","Quy luật chuyển hoá từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Cả ba đáp án trên"],"ans":2,"ex":"Một cây đơn lẻ chưa đủ tạo nên núi, nhưng khi số lượng cây tăng lên và kết hợp lại thì tạo nên chất mới là hòn núi cao. Hình ảnh này minh họa **quy luật lượng – chất**: tích lũy về lượng đến mức nhất định sẽ làm thay đổi về chất. Câu ca dao không trực tiếp nói về mâu thuẫn hay phủ định."},{"id":"C2-106","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Giải thích hiện tượng “quá mù ra mưa” trên cơ sở của nội dung triết học nào?","opts":["Nguyên nhân, kết quả","Lượng đổi chất đổi","Nguyên lý mối liên hệ phổ biến","Nội dung, hình thức"],"ans":1,"ex":"Hơi nước tích tụ trong không khí (sương mù dày lên) là sự thay đổi dần về lượng; khi vượt quá độ sẽ ngưng tụ thành mưa, tức là thay đổi về chất. Hiện tượng này giải thích bằng **quy luật lượng đổi – chất đổi**. Dù có yếu tố nhân quả, nội dung cốt lõi ở đây là sự chuyển hóa từ lượng sang chất."},{"id":"C2-107","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu thành ngữ “Có công mài sắt, có ngày nên kim” tương đồng với nội dung triết học nào dưới đây?","opts":["Nguyên nhân, kết quả","Quy luật lượng – chất","Nguyên lý mối liên hệ phổ biến","Nội dung, hình thức"],"ans":1,"ex":"Sự kiên trì mài sắt là quá trình tích lũy dần về lượng, đến một lúc nhất định thanh sắt trở thành cây kim, tức là có sự thay đổi về chất. Thành ngữ phản ánh **quy luật lượng – chất** và bài học phải kiên trì tích lũy về lượng. Đây không đơn thuần là quan hệ nhân quả mà nhấn mạnh quá trình tích lũy dẫn đến bước nhảy."},{"id":"C2-108","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu tục ngữ, thành ngữ: “Tốt quá hóa lốp”; “Mèo già hóa cáo” tương đồng với nội dung triết học nào?","opts":["Quy luật phủ định của phủ định","Nguyên nhân và kết quả","Quy luật lượng chất","Bản chất, hiện tượng"],"ans":2,"ex":"Tốt quá mức thì hóa hỏng, mèo già lâu năm thì tinh ranh như cáo: đều cho thấy khi lượng thay đổi vượt quá giới hạn (độ) thì chất của sự vật biến đổi. Đây là biểu hiện của **quy luật lượng – chất**. Bài học rút ra là phải biết giữ gìn độ, tránh thái quá."},{"id":"C2-109","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vận dụng nội dung triết học nào của phép biện chứng duy vật để giải thích hiện tượng xảy ra trong thực tế: Có những người tiêm vắc xin phòng chống bệnh lại bị mắc chính bệnh tiêm phòng mà trước khi đó người được tiêm khỏe mạnh, chưa từng mắc bệnh?","opts":["Quy luật lượng – chất","Quy luật phủ định của phủ định","Khả năng, hiện thực","Nội dung, hình thức"],"ans":0,"ex":"Theo đáp án gốc, hiện tượng này được giải thích bằng **quy luật lượng – chất**: vắc xin chứa mầm bệnh đã làm yếu; nếu liều lượng, độc lực hoặc trạng thái cơ thể vượt quá giới hạn (độ) thích hợp thì sự thay đổi về lượng dẫn đến thay đổi về chất, khiến người được tiêm phát bệnh. Bài học là phải tôn trọng độ, chú ý đến lượng phù hợp trong mọi tác động."},{"id":"C2-110","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong hoạt động nhận thức và thực tiễn sai lầm của sự chủ quan, nóng vội là do không tôn trọng quy luật nào?","opts":["Quy luật lượng - chất","Quy luật phủ định của phủ định","Quy luật mâu thuẫn","Cả ba đáp án trên"],"ans":0,"ex":"Theo **quy luật lượng – chất**, sự thay đổi về chất chỉ xảy ra khi lượng được tích lũy đến điểm nút. Chủ quan, nóng vội là muốn thực hiện bước nhảy khi chưa có đủ tích lũy về lượng, tức là vi phạm quy luật này. Ý nghĩa phương pháp luận là phải kiên trì tích lũy về lượng, tránh tả khuynh."},{"id":"C2-111","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong hoạt động nhận thức và thực tiễn, sai lầm của trì trệ bảo thủ là do không tôn trọng quy luật nào của phép biện chứng duy vật?","opts":["Quy luật lượng - chất.","Quy luật phủ định của phủ định.","Quy luật mâu thuẫn","Cả ba đáp án trên"],"ans":0,"ex":"Theo **quy luật lượng – chất**, khi lượng đã tích lũy đủ đến điểm nút thì phải kịp thời thực hiện bước nhảy. Trì trệ, bảo thủ là không dám thực hiện bước nhảy khi điều kiện đã chín muồi, coi phát triển chỉ là thay đổi về lượng, đó là biểu hiện hữu khuynh. Vì vậy sai lầm này do không tôn trọng quy luật lượng – chất."},{"id":"C2-112","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Quy luật mâu thuẫn có vị trí, vai trò như thế nào trong phép biện chứng duy vật?","opts":["Là hạt nhân của phép biện chứng duy vật, vạch ra nguồn gốc bên trong của sự vận động và phát triển.","Vạch ra xu hướng của sự phát triển.","Vạch ra cách thức của sự phát triển","Cả a và c"],"ans":0,"ex":"**Quy luật thống nhất và đấu tranh của các mặt đối lập** được V.I. Lênin coi là hạt nhân của phép biện chứng, vì nó vạch ra nguồn gốc, động lực bên trong của sự vận động và phát triển. Xu hướng phát triển do quy luật phủ định của phủ định chỉ ra, còn cách thức do quy luật lượng – chất chỉ ra."},{"id":"C2-113","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vai trò của quy luật thống nhất và đấu tranh của các mặt đối lập (quy luật mâu thuẫn)?","opts":["Chỉ ra nguồn gốc, động lực của sự vận động, phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng.","Tất cả các đáp án trên."],"ans":0,"ex":"Vai trò của **quy luật mâu thuẫn** là chỉ ra nguồn gốc, động lực của sự vận động và phát triển: sự thống nhất và đấu tranh của các mặt đối lập bên trong sự vật làm cho nó vận động. Phương thức, cách thức thuộc về quy luật lượng – chất; xu hướng, khuynh hướng thuộc về quy luật phủ định của phủ định. Vì vậy chọn tất cả là không đúng."},{"id":"C2-114","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Mâu thuẫn nổi lên hàng đầu ở một giai đoạn phát triển nhất định của sự vật, chi phối các mâu thuẫn khác trong giai đoạn đó được gọi là mâu thuẫn gì?","opts":["Mâu thuẫn cơ bản","Mâu thuẫn chủ yếu","Mâu thuẫn thứ yếu.","Mâu thuẫn đối kháng"],"ans":1,"ex":"Căn cứ vào vai trò trong từng giai đoạn, giáo trình phân biệt **mâu thuẫn chủ yếu** và thứ yếu. Mâu thuẫn chủ yếu nổi lên hàng đầu ở một giai đoạn nhất định, chi phối các mâu thuẫn khác trong giai đoạn đó. Khác với mâu thuẫn cơ bản là mâu thuẫn quy định bản chất sự vật, tồn tại suốt quá trình phát triển."},{"id":"C2-115","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong mâu thuẫn biện chứng, các mặt đối lập quan hệ với nhau như thế nào?","opts":["Chỉ thống nhất với nhau.","Chỉ có mặt đấu tranh với nhau.","Vừa thống nhất, vừa đấu tranh với nhau","Tồn tại độc lập với nhau"],"ans":2,"ex":"Trong **mâu thuẫn biện chứng**, các mặt đối lập vừa thống nhất (nương tựa, đòi hỏi có nhau, đồng nhất ở những mặt nhất định) vừa đấu tranh (tác động qua lại theo xu hướng bài trừ, phủ định nhau). Thống nhất là tương đối, tạm thời; đấu tranh là tuyệt đối. Chỉ thấy một mặt thống nhất hoặc đấu tranh là siêu hình."},{"id":"C2-116","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong lý luận về mâu thuẫn người ta gọi hai cực dương và âm của thanh nam châm là gì?","opts":["Hai mặt","Hai mặt đối lập","Hai yếu tố.","Hai thuộc tính"],"ans":1,"ex":"**Mặt đối lập** là những mặt có đặc điểm, thuộc tính, xu hướng vận động trái ngược nhau nhưng cùng tồn tại khách quan trong một sự vật. Cực dương và cực âm của nam châm là ví dụ điển hình: trái ngược nhau nhưng không thể tách rời. Gọi đơn thuần là hai mặt hay hai thuộc tính thì chưa nói lên tính đối lập."},{"id":"C2-117","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Vai trò của quy luật phủ định của phủ định?","opts":["Chỉ ra nguồn gốc, động lực phát triển của sự vật, hiện tượng.","Chỉ ra phương thức, cách thức của sự vận động, biến đổi, phát triển của sự vật hiện tượng.","Được coi là hạt nhân cơ bản của phép biện chứng duy vật.","Chỉ ra xu hướng, khuynh hướng vận động, phát triển của sự vật, hiện tượng."],"ans":3,"ex":"**Quy luật phủ định của phủ định** chỉ ra khuynh hướng của sự phát triển: sự vật phát triển theo đường xoáy ốc đi lên, qua nhiều lần phủ định biện chứng, cái mới kế thừa cái cũ ở trình độ cao hơn. Nguồn gốc, động lực là vai trò của quy luật mâu thuẫn (hạt nhân); cách thức là vai trò của quy luật lượng – chất."},{"id":"C2-118","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong quy luật phủ định của phủ định, sự thay thế sự vật này bằng sự vật kia được gọi là gì?","opts":["Mâu thuẫn","Tồn tại","Vận động","Phủ định"],"ans":3,"ex":"**Phủ định** là sự thay thế sự vật này bằng sự vật khác trong quá trình vận động và phát triển. Phép biện chứng phân biệt phủ định nói chung với **phủ định biện chứng**, tức là tự phủ định, có tính khách quan và kế thừa, tạo điều kiện cho phát triển. Mâu thuẫn hay vận động là những khái niệm rộng hơn, không chỉ đúng sự thay thế này."},{"id":"C2-119","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Con đường phát triển của sự vật mà quy luật phủ định của phủ định vạch ra là con đường nào?","opts":["Đường thẳng đi lên","Đường tròn khép kín","Đường xoáy ốc đi lên","Đường rích rắc"],"ans":2,"ex":"Theo quy luật phủ định của phủ định, phát triển diễn ra theo **đường xoáy ốc đi lên**: sau hai lần phủ định, sự vật dường như quay lại cái ban đầu nhưng ở trình độ cao hơn. Hình ảnh xoáy ốc thể hiện tính kế thừa, tính lặp lại và tính tiến lên. Đường thẳng bỏ qua tính quanh co, còn đường tròn khép kín là quan niệm tuần hoàn."},{"id":"C2-120","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Phủ định biện chứng có tính khách quan","Phủ định biện chứng là kết quả giải quyết những mâu thuẫn bên trong sự vật","Phủ định biện chứng phụ thuộc vào ý thức của con người","Phủ định biện chứng có tính kế thừa"],"ans":2,"ex":"**Phủ định biện chứng** là tự phủ định, do giải quyết mâu thuẫn bên trong sự vật nên có tính **khách quan**, đồng thời có tính kế thừa: giữ lại yếu tố tích cực của cái cũ. Nó không phụ thuộc vào ý muốn chủ quan của con người. Vì vậy khẳng định phủ định biện chứng phụ thuộc vào ý thức là sai."},{"id":"C2-121","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là sai?","opts":["Phủ định của phủ định có tính khách quan và kế thừa","Phủ định của phủ định hoàn toàn lặp lại cái ban đầu","Phủ định của phủ định lặp lại cái ban đầu trên cơ sở mới cao hơn","Phủ định biện chứng làm cho sự vật phát triển lên một tầm cao mới"],"ans":1,"ex":"Kết quả của **phủ định của phủ định** là sự lặp lại một số đặc trưng của cái ban đầu nhưng trên cơ sở mới, cao hơn, chứ không phải quay lại nguyên vẹn. Đó là tính chất xoáy ốc của phát triển, có tính khách quan và kế thừa. Cho rằng nó hoàn toàn lặp lại cái ban đầu là quan niệm tuần hoàn, siêu hình."},{"id":"C2-122","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, mục đích của nhận thức là gì?","opts":["Thỏa mãn sự hiểu biết của con người","Phục vụ nhu cầu thực tiễn của con người","Phục vụ hoạt động lao động sản xuất","Giúp con người hiểu bản chất của mình"],"ans":1,"ex":"Theo chủ nghĩa duy vật biện chứng, **thực tiễn là mục đích của nhận thức**: nhận thức không nhằm thỏa mãn hiểu biết thuần túy mà để phục vụ nhu cầu cải tạo tự nhiên và xã hội. Tri thức chỉ có ý nghĩa khi được vận dụng vào thực tiễn. Lao động sản xuất chỉ là một hình thức thực tiễn nên phương án C chưa đầy đủ."},{"id":"C2-123","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Giai đoạn nhận thức diễn ra trên cơ sở sự tác động trực tiếp của các sự vật lên các giác quan của con người là giai đoạn nhận thức nào ?","opts":["Nhận thức lý tính","Nhận thức Khoa học","Nhận thức lý luận","Nhận thức cảm tính"],"ans":3,"ex":"Theo V.I. Lênin, quá trình nhận thức đi từ trực quan sinh động đến tư duy trừu tượng. **Nhận thức cảm tính** (trực quan sinh động) là giai đoạn đầu, diễn ra trên cơ sở sự tác động trực tiếp của sự vật lên các giác quan. Nhận thức lý tính là giai đoạn phản ánh gián tiếp, khái quát bằng tư duy."},{"id":"C2-124","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nhận thức cảm tính được thực hiện dưới các hình thức nào?","opts":["Khái niệm và phán đoán","Cảm giác, tri giác và khái niệm","Cảm giác, tri giác và biểu tượng","Cảm giác, Suy luận, Phán đoán"],"ans":2,"ex":"**Nhận thức cảm tính** gồm ba hình thức: **cảm giác** (phản ánh từng thuộc tính riêng lẻ), **tri giác** (phản ánh tương đối toàn vẹn sự vật) và **biểu tượng** (hình ảnh sự vật được tái hiện khi không còn trực tiếp tác động). Khái niệm, phán đoán, suy luận là các hình thức của nhận thức lý tính."},{"id":"C2-125","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hình thức nào là hình thức đầu tiên của giai đoạn nhận thức cảm tính?","opts":["Khái niệm","Biểu tượng","Cảm giác","Tri giác"],"ans":2,"ex":"**Cảm giác** là hình thức đầu tiên, giản đơn nhất của nhận thức cảm tính, phản ánh từng thuộc tính riêng lẻ khi sự vật tác động trực tiếp lên giác quan. Lênin gọi cảm giác là hình ảnh chủ quan của thế giới khách quan. Từ cảm giác mới hình thành tri giác rồi biểu tượng."},{"id":"C2-126","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đặc điểm chung của các hình thức nhận thức cảm tính là gì?","opts":["Trực tiếp, bề ngoài","Gián tiếp, bề ngoài","Trực tiếp, bản chất","Gián tiếp, bản chất"],"ans":0,"ex":"Các hình thức nhận thức cảm tính đều phản ánh **trực tiếp** sự vật qua giác quan và chủ yếu phản ánh cái **bề ngoài**, chưa đi sâu vào bản chất. Đây vừa là ưu điểm (sinh động, cụ thể) vừa là hạn chế. Phản ánh gián tiếp, đi vào bản chất là đặc điểm của nhận thức lý tính."},{"id":"C2-127","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Sự phản ánh trừu tượng, khái quát những đặc điểm chung, bản chất của các sự vật được gọi là giai đoạn nhận thức nào?","opts":["Nhận thức cảm tính","Nhận thức lý tính","Nhận thức kinh nghiệm","Nhận thức Khoa học"],"ans":1,"ex":"**Nhận thức lý tính** (tư duy trừu tượng) là giai đoạn phản ánh gián tiếp, trừu tượng và khái quát những thuộc tính, đặc điểm chung, bản chất của sự vật. Nó được hình thành trên cơ sở tài liệu của nhận thức cảm tính. Nhận thức cảm tính chỉ phản ánh trực tiếp, bề ngoài nên không phù hợp."},{"id":"C2-128","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Tư duy trừu tượng được thể hiện dưới các hình thức cơ bản nào?","opts":["Khái niệm, Biểu tượng, Tri giác","Suy luận, Biểu tượng, Tri giác","Khái niệm, Suy luận, Phán đoán","Cảm giác, Suy luận, Phán đoán"],"ans":2,"ex":"Nhận thức lý tính được thực hiện qua ba hình thức: **khái niệm** (phản ánh những đặc tính bản chất), **phán đoán** (liên kết các khái niệm để khẳng định hoặc phủ định) và **suy luận** (rút ra tri thức mới từ các phán đoán). Biểu tượng, tri giác, cảm giác thuộc nhận thức cảm tính."},{"id":"C2-129","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan niệm của Triết học Mác - Lênin, thực tiễn là gì?","opts":["Hoạt động của con người","Hoạt động vật chất của con người","Hoạt động vật chất của con người có tính mục đích.","Hoạt động vật chất của con người, nhằm cải tạo tự nhiên theo yêu cầu của con người"],"ans":3,"ex":"Theo đáp án gốc, **thực tiễn** là hoạt động vật chất của con người nhằm cải tạo tự nhiên theo yêu cầu của con người. Giáo trình định nghĩa đầy đủ: thực tiễn là toàn bộ hoạt động vật chất có mục đích, mang tính lịch sử – xã hội nhằm cải biến tự nhiên và xã hội. Phương án D nêu được tính vật chất và mục đích cải tạo, nên đầy đủ hơn các phương án còn lại."},{"id":"C2-130","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án thích hợp vào dấu …:\"Thực tiễn là toàn bộ những ... có mục đích, mang tính lịch sử xã hội của con người nhằm cải tạo tự nhiên và xã hội\".","opts":["Hoạt động.","Hoạt động vật chất","Hoạt động có mục đích","Hoạt động vật chất có mục đích, mang tính lịch sử - xã hội"],"ans":1,"ex":"Định nghĩa trong giáo trình: **thực tiễn** là toàn bộ những **hoạt động vật chất** có mục đích, mang tính lịch sử – xã hội của con người nhằm cải biến tự nhiên và xã hội. Chỗ trống chỉ cần cụm hoạt động vật chất, vì phần có mục đích, mang tính lịch sử – xã hội đã có sẵn ở phía sau. Đặc trưng vật chất phân biệt thực tiễn với hoạt động tinh thần."},{"id":"C2-131","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hình thức hoạt động thực tiễn cơ bản nhất quy định đến các hình thức khác là hình thức nào?","opts":["Hoạt động sản xuất vật chất","Hoạt động chính trị xã hội","Hoạt động quan sát và thực nghiệm khoa học","Hoạt động tinh thần"],"ans":0,"ex":"Thực tiễn có ba hình thức cơ bản: hoạt động sản xuất vật chất, hoạt động chính trị – xã hội và hoạt động thực nghiệm khoa học. **Sản xuất vật chất** là hình thức cơ bản, nguyên thủy nhất, quyết định sự tồn tại của xã hội và quy định các hình thức thực tiễn khác. Hoạt động tinh thần không phải là thực tiễn."},{"id":"C2-132","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hoạt động thực tiễn là hoạt động chủ yếu, cơ bản dẫn đến sự ra đời của ý thức, vì:","opts":["Hoạt động thực tiễn là quá trình con người sử dụng công cụ lao động tác động vào đối tượng hiện thực buộc chúng phải bộc lộ thuộc tính, kết cấu, bản chất… qua đó, con người nhận biết được nó.","Hoạt động thực tiễn là hoạt động cơ bản của con người","Hoạt động thực tiễn là hoạt động giúp con người nhận thức và cải tạo thế giới","Hoạt động thực tiễn là quá trình con người cải tạo tự nhiên bắt chúng phải bộc lộ thuộc tính, kết cấu, bản chất.. qua đó con người nhận biết nó"],"ans":0,"ex":"Thực tiễn là cơ sở của nhận thức và ý thức vì trong thực tiễn, con người dùng **công cụ lao động** tác động vào đối tượng hiện thực, buộc chúng bộc lộ thuộc tính, kết cấu, bản chất; nhờ đó con người nhận biết được chúng. Phương án A đầy đủ nhất vì nêu được vai trò của công cụ và đối tượng hiện thực nói chung, cả tự nhiên và xã hội."},{"id":"C2-133","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Thực tiễn đóng vai trò gì đối với nhận thức?","opts":["Là cơ sở, động lực, mục đích của nhận thức và là tiêu chuẩn để kiểm tra chân lý","Là điểm khởi đầu của nhận thức","Tồn tại song hành, hỗ trợ quá trình nhận thức","Là đích đến của nhận thức"],"ans":0,"ex":"Vai trò của **thực tiễn đối với nhận thức**: thực tiễn là cơ sở, động lực, mục đích của nhận thức và là tiêu chuẩn để kiểm tra chân lý. Thực tiễn cung cấp tài liệu, đặt ra yêu cầu và kiểm nghiệm tính đúng đắn của tri thức. Các phương án khác chỉ nêu một khía cạnh hoặc mô tả sai mối quan hệ."},{"id":"C2-134","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu thành ngữ nào dưới đây phản ánh mối quan hệ giữa nhận thức và thực tiễn?","opts":["Có công mài sắt, có ngày nên kim","Nước chảy, đá mòn","Gieo gió, gặt bão","Đi một ngày đàng học một sàng khôn"],"ans":3,"ex":"Câu tục ngữ cho thấy qua hoạt động thực tiễn (đi, trải nghiệm) con người tích lũy được hiểu biết, tức là **thực tiễn là cơ sở của nhận thức**. Các câu còn lại chủ yếu thể hiện quy luật lượng – chất (mài sắt nên kim, nước chảy đá mòn) hoặc quan hệ nhân quả (gieo gió gặt bão)."},{"id":"C2-135","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, bệnh giáo điều là do tuyệt đối hóa vai trò của yếu tố nào dưới đây?","opts":["Vai trò của cảm tính","Vai trò của lý tính","Vai trò của kinh nghiệm","Vai trò của lý luận"],"ans":3,"ex":"**Bệnh giáo điều** là tuyệt đối hóa vai trò của **lý luận**, coi thường kinh nghiệm thực tiễn, vận dụng lý luận một cách máy móc, không tính đến điều kiện cụ thể. Ngược lại, bệnh kinh nghiệm là tuyệt đối hóa kinh nghiệm, coi thường lý luận. Cả hai đều vi phạm nguyên tắc thống nhất giữa lý luận và thực tiễn."},{"id":"C2-136","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nguyên tắc thống nhất giữa lý luận với thực tiễn là nguyên tắc được rút ra trực tiếp từ nghiên cứu nội dung triết học nào dưới đây?","opts":["Mối quan hệ giữa nhận thức và ý thức","Lý luận về nhận thức","Mối quan hệ giữa khả năng và hiện thực","Mối quan hệ giữa nội dung và hình thức"],"ans":1,"ex":"Nguyên tắc **thống nhất giữa lý luận và thực tiễn** được rút ra từ **lý luận nhận thức** của chủ nghĩa duy vật biện chứng, đặc biệt từ vai trò của thực tiễn đối với nhận thức. Lý luận phải xuất phát từ thực tiễn, được thực tiễn kiểm nghiệm và quay lại chỉ đạo thực tiễn. Các cặp phạm trù khả năng – hiện thực, nội dung – hình thức không trực tiếp đặt ra nguyên tắc này."},{"id":"C2-137","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Hãy lựa chọn câu trả lời đúng. Chân lý là gì?","opts":["Suy luận của con người","Tri thức đúng, phù hợp với hiện thực khách quan và được thực tiễn kiểm nghiệm.","Tri thức phù hợp với hiện thực","Là cái được Thượng Đế định sẵn"],"ans":1,"ex":"Theo chủ nghĩa duy vật biện chứng, **chân lý** là tri thức phù hợp với hiện thực khách quan và đã được thực tiễn kiểm nghiệm. Hai yếu tố then chốt là sự phù hợp với hiện thực và sự kiểm nghiệm của thực tiễn. Phương án C thiếu yếu tố kiểm nghiệm, còn cái được Thượng đế định sẵn là quan niệm duy tâm."},{"id":"C2-138","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Chọn đáp án đúng điền vào chỗ trống: “Chân lý là những tri thức.... với hiện thực khách quan và được thực tiễn kiểm nghiệm”.","opts":["Đầy đủ","Đúng đắn","Hợp lý","Phù hợp"],"ans":3,"ex":"Định nghĩa trong giáo trình: **chân lý** là những tri thức **phù hợp** với hiện thực khách quan và được thực tiễn kiểm nghiệm. Thuật ngữ phù hợp nhấn mạnh quan hệ giữa nội dung tri thức với hiện thực khách quan. Chân lý có tính khách quan, tương đối, tuyệt đối và cụ thể."},{"id":"C2-139","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khái niệm nào dưới đây chỉ sự phản ánh hiện thực khách quan vào bộ não người một cách tích cực, năng động, sáng tạo dựa trên cơ sở thực tiễn và đưa ra tri thức đúng?","opts":["Ý thức","Nhận thức","Chân lý","Thực tiễn"],"ans":2,"ex":"Theo đáp án gốc, khái niệm được hỏi là **chân lý**, vì điểm nhấn là kết quả: tri thức đúng, phù hợp với hiện thực khách quan. Cần lưu ý, giáo trình định nghĩa **nhận thức** là quá trình phản ánh tích cực, tự giác, sáng tạo thế giới khách quan vào bộ óc người trên cơ sở thực tiễn; còn chân lý là sản phẩm tri thức đúng của quá trình ấy. Ý thức và thực tiễn không phù hợp ở đây."},{"id":"C2-140","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Tiêu chuẩn để kiểm tra chân lý là gì?","opts":["Tri thức đựơc nhiều người công nhận","Tri thức do các thế hệ trước để lại","Lời nói của các vĩ nhân","Thực tiễn"],"ans":3,"ex":"Theo chủ nghĩa Mác – Lênin, **thực tiễn là tiêu chuẩn của chân lý**. Chỉ khi vận dụng tri thức vào thực tiễn và đạt được kết quả phù hợp thì mới xác định được tính đúng đắn của nó. Số đông thừa nhận, truyền thống hay lời vĩ nhân không phải là tiêu chuẩn khách quan. Tiêu chuẩn thực tiễn vừa có tính tuyệt đối vừa có tính tương đối."},{"id":"C2-141","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Tính thống nhất vật chất của thế giới được hiểu như thế nào?","opts":["Chỉ có một thế giới tồn tại đó là thế giới vật chất, ngoài ra không có thế giới nào khác","Thế giới vật chất là một chỉnh thể vừa thống nhất, vừa đa dạng. Thống nhất ở tính vật chất và đa dạng ở các hình thức tồn tại của nó.","Lịch sử loài người là kết quả của sự tiến hoá lâu dài của giới tự nhiên, của vật chất nói chung, nó không phải là thế giới bên cạnh của thế giới tự nhiên.","Tất cả đáp án đều đúng"],"ans":3,"ex":"Theo chủ nghĩa duy vật biện chứng, **tính thống nhất của thế giới là ở tính vật chất** của nó. Chỉ có một thế giới duy nhất là thế giới vật chất; thế giới ấy vừa thống nhất ở tính vật chất, vừa đa dạng ở các dạng tồn tại; xã hội loài người là sản phẩm tiến hóa của tự nhiên chứ không tách rời. Ba phương án đều đúng nên chọn tất cả."},{"id":"C2-142","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nhà triết học nào coi lửa là thực thể đầu tiên của thế giới và đó là lập trường triết học nào?","opts":["Đê-mô-crít, - chủ nghĩa duy vật ngây thơ chất phác","Hê-ra-clít, - chủ nghĩa duy vật ngây thơ chất phác","Hê-ra-clít, - chủ nghĩa duy tâm khách quan","Ana-ximen, - chủ ngiã duy vật tự phát"],"ans":1,"ex":"**Hêraclít** (thế kỷ VI–V TCN) coi lửa là bản nguyên của thế giới, mọi vật đều sinh ra từ lửa và chuyển hóa lẫn nhau. Đây là lập trường của **chủ nghĩa duy vật chất phác** thời cổ đại, đồng nhất vật chất với một vật thể cụ thể. Đêmôcrít gắn với thuyết nguyên tử, Anaximen coi không khí là bản nguyên."},{"id":"C2-143","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Lao động có vai trò như thế nào đối với quá trình hình thành và phát triển của ý thức?","opts":["Nhờ lao động, con người tác động vào tự nhiên, làm cho tự nhiên bộc lộ những thuộc tính của mình, giúp con người nhận thức phong phú và sâu sắc hơn về thế giới.","Lao động đã mài sắc những giác quan của con người và giúp con người tích luỹ được ngày càng nhiều tri thức hơn.","Nhờ lao động mà con người trao đổi với nhau nhiều tri thức, do vậy hiểu biết của con người lại càng được nâng lên.","Tất cả đáp án đều đúng"],"ans":3,"ex":"**Lao động** là yếu tố xã hội quyết định sự hình thành ý thức. Qua lao động, con người tác động vào tự nhiên, buộc nó bộc lộ thuộc tính; các giác quan và bộ óc được hoàn thiện, tri thức được tích lũy; nhu cầu trao đổi trong lao động làm xuất hiện ngôn ngữ. Cả ba phương án đều phản ánh đúng vai trò của lao động."},{"id":"C2-144","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Nội dung nào dưới đây phản ánh đầy đủ nhất về bản chất của ý thức?","opts":["Ý thức có tính năng động, sáng tạo & mang bản chất xã hội","Ý thức mang bản chất xã hội","Ý thức mang bản chất tự nhiên","Tất cả đáp án đều đúng"],"ans":3,"ex":"Theo đáp án gốc, bản chất của ý thức được phản ánh đầy đủ khi gộp các phương án. Giáo trình nhấn mạnh ý thức là hình ảnh chủ quan của thế giới khách quan, có tính **năng động, sáng tạo** và mang **bản chất xã hội**. Yếu tố tự nhiên (bộ óc người) là nguồn gốc tự nhiên, là tiền đề vật chất của ý thức, nên đáp án gốc tính cả mặt này."},{"id":"C2-145","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ý nghĩa phương pháp luận được rút ra từ Mối quan hệ giữa vật chất và ý thức là gì?","opts":["Trong nhận thức và hoạt động phải có quan điểm khách quan","Mục tiêu và phương pháp đều phải căn cứ vào điều kiện khách quan thực tế, không được chủ quan duy ý chí.","Cần Phát huy tính năng động sáng tạo của ý thức","Tất cả đáp án đều đúng"],"ans":3,"ex":"Từ mối quan hệ **vật chất quyết định ý thức, ý thức tác động trở lại vật chất**, rút ra ý nghĩa phương pháp luận: phải tôn trọng khách quan, xuất phát từ thực tế khách quan, chống chủ quan duy ý chí; đồng thời phát huy tính năng động, sáng tạo của ý thức. Vì vậy cả ba phương án đều đúng."},{"id":"C2-146","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Quan điểm nào cho rằng, không gian, thời gian, vận động không liên quan với nhau và ở bên ngoài vật chất?","opts":["Chủ nghĩa duy vật siêu hình","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy vật chất phác"],"ans":0,"ex":"**Chủ nghĩa duy vật siêu hình** (thế kỷ XVII–XVIII, gắn với cơ học Newton) coi không gian là cái hộp trống, thời gian là dòng chảy thuần túy, tách rời nhau và tách rời vật chất vận động. Chủ nghĩa duy vật biện chứng khẳng định vận động, không gian, thời gian là những hình thức tồn tại của vật chất, gắn bó không tách rời."},{"id":"C2-147","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo chủ nghĩa duy vật biện chứng, nguồn gốc \"duy nhất và cuối cùng\" của nhận thức là gì?","opts":["Thế giới tâm linh","Thế giới khách quan","Thế giới sự vật cảm tính","Tư duy con người"],"ans":1,"ex":"Theo chủ nghĩa duy vật biện chứng, **thế giới khách quan** là nguồn gốc duy nhất và cuối cùng của nhận thức; nhận thức là sự phản ánh thế giới vật chất vào bộ óc người. Thế giới sự vật cảm tính chỉ là một phần, còn coi tư duy hay thế giới tâm linh là nguồn gốc là quan điểm duy tâm."},{"id":"C2-148","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Bổ sung để được một khẳng định đúng: “Định nghĩa về vật chất của V.I.Lênin...”?","opts":["Thừa nhận vật chất tồn tại bên ngoài và độc lập với ý thức con người, thông qua các dạng cụ thể của vật chất","Thừa nhận vật chất nói chung tồn tại vĩnh viễn, tách rời các dạng cụ thể của vật chất","Đồng nhất vật chất nói chung với một dạng cụ thể của vật chất","Đồng nhất vật chất với khối lượng"],"ans":0,"ex":"Trong định nghĩa của **V.I. Lênin**, vật chất là thực tại khách quan, tồn tại độc lập với ý thức và được ý thức phản ánh. Vật chất nói chung không tồn tại tách rời mà tồn tại thông qua các dạng cụ thể. Đồng nhất vật chất với một dạng cụ thể hay với khối lượng là sai lầm của chủ nghĩa duy vật trước Mác."},{"id":"C2-149","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Bổ sung để được một nhận định đúng theo phép biện chứng duy vật: “Phát triển là xu hướng vận động ...”?","opts":["Luôn tiến bộ của thế giới vật chất, xảy ra bên ngoài sự ổn định của sự vật, do sự giải quyết mâu thuẫn gây ra, thông qua bước nhảy về chất và hướng theo xu thế phủ định của phủ định.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra trong thế giới vật chất.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra bên ngoài sự vận động cụ thể của các sự vật cá biệt.","Từ thấp đến cao, từ đơn giản đến phức tạp, từ chưa hoàn thiện đến hoàn thiện, xảy ra bên trong một sự vật cá biệt."],"ans":1,"ex":"Theo phép biện chứng duy vật, **phát triển** là quá trình vận động theo khuynh hướng đi lên từ thấp đến cao, từ đơn giản đến phức tạp, từ kém hoàn thiện đến hoàn thiện hơn, diễn ra trong thế giới vật chất. Phát triển không phải luôn tiến bộ một cách thẳng tắp và không xảy ra bên ngoài sự vận động của các sự vật cụ thể."},{"id":"C2-150","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo phép biện chứng duy vật, luận điểm nào sau đây là sai?","opts":["Về cơ bản, hiện tượng và bản chất thống nhất với nhau","Có hiện tượng biểu hiện đúng bản chất nhưng cũng có hiện tượng biểu hiện không đúng bản chất","Để hành động hiệu quả, chúng ta không chỉ dựa vào bản chất mà trước tiên cần xuất phát từ hiện tượng","Hiện tượng và bản chất là những cái đối lập nhau"],"ans":2,"ex":"Ý nghĩa phương pháp luận của cặp **bản chất – hiện tượng**: muốn nhận thức đúng sự vật phải đi sâu tìm hiểu bản chất, và trong hoạt động thực tiễn phải căn cứ vào **bản chất** chứ không căn cứ vào hiện tượng. Hiện tượng chỉ là điểm xuất phát để nhận thức, có thể phản ánh xuyên tạc bản chất. Vì vậy cho rằng hành động trước tiên phải xuất phát từ hiện tượng là sai."},{"id":"C2-151","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Đỉnh cao nhất của tư tưởng duy vật cổ đại về vật chất là quan điểm nào?","opts":["Quan niệm về lửa là bản nguyên của thế giới","Quan niệm thuyết nguyên tử của Lơ-xíp và Đê-mô-crít.","Quan niệm về con số là bản nguyên của thế giới.","Quan niệm về nước là bản nguyên của thế giới"],"ans":1,"ex":"**Thuyết nguyên tử** của Lơxíp và Đêmôcrít được xem là đỉnh cao của chủ nghĩa duy vật cổ đại: coi vật chất được cấu tạo từ những hạt nhỏ nhất, không thể phân chia là nguyên tử. Quan niệm này mang tính khái quát cao hơn việc quy vật chất về lửa hay nước. Con số là bản nguyên là quan điểm của trường phái Pitago."},{"id":"C2-152","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Định nghĩa về vật chất của Lênin được đề cập trong tác phẩm nào?","opts":["Biện chứng của tự nhiên","Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán","Bút ký triết học","Nhà nước và cách mạng"],"ans":1,"ex":"Định nghĩa vật chất của **V.I. Lênin** được nêu trong tác phẩm **Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán** (1908), nhằm phê phán chủ nghĩa Makhơ và khắc phục khủng hoảng trong vật lý học. Biện chứng của tự nhiên là của Ăngghen; Bút ký triết học và Nhà nước và cách mạng là những tác phẩm khác của Lênin."},{"id":"C2-153","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Quan điểm sau đây thuộc trường phái triết học nào: “Cái gì cảm giác được đều là vật chất”?","opts":["Chủ nghĩa duy vật siêu hình","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy tâm chủ quan"],"ans":3,"ex":"Theo đáp án gốc, quan điểm này thuộc **chủ nghĩa duy tâm chủ quan**, vì nó lấy cảm giác của chủ thể làm thước đo tồn tại của sự vật, gần với luận điểm của Béccơli và phái Makhơ: vật chất bị quy về cái được cảm giác. Chủ nghĩa duy vật biện chứng khẳng định vật chất tồn tại khách quan, không phụ thuộc vào việc có được cảm giác hay không."},{"id":"C2-154","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Quy luật nào được V.I. Lênin gọi là hạt nhân của phép biện chứng duy vật?","opts":["Quy luật chuyển hóa từ những sự thay đổi về lượng thành những thay đổi về chất và ngược lại","Quy luật thống nhất và đấu tranh giữa các mặt đối lập","Quy luật phủ định của phủ định","Quy luật đấu tranh giai cấp"],"ans":1,"ex":"**V.I. Lênin** gọi **quy luật thống nhất và đấu tranh giữa các mặt đối lập** là hạt nhân của phép biện chứng, vì nó chỉ ra nguồn gốc, động lực của mọi sự vận động và phát triển. Hai quy luật kia chỉ ra cách thức và khuynh hướng phát triển. Đấu tranh giai cấp là quy luật của xã hội có giai cấp, không phải quy luật cơ bản của phép biện chứng."},{"id":"C2-155","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Ph. Ăngghen đã cho rằng: Đối với những ai phủ nhận (...) thì mọi quy luật của tự nhiên đều là giả thuyết?","opts":["Tính phổ biến","Tính nhân quả","Tính tất yếu","Tính biện chứng"],"ans":3,"ex":"Theo đáp án gốc, **Ph. Ăngghen** nhấn mạnh rằng các quy luật tự nhiên phản ánh mối liên hệ tất yếu, khách quan, biện chứng của thế giới. Nếu phủ nhận **tính biện chứng** của tự nhiên, gồm các mối liên hệ nhân quả, tất yếu, thì quy luật mất cơ sở khách quan và chỉ còn là giả thuyết chủ quan. Lưu ý: nhiều tài liệu dẫn câu này với cụm tính nhân quả."},{"id":"C2-156","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"“Nếu không có ý thức con người thì thế giới không tồn tại.”. Quan điểm này phủ nhận nội dung nào trong triết học Mác - Lênin?","opts":["Ý thức có tính sáng tạo","Vật chất tồn tại khách quan, độc lập với ý thức","Ý thức có thể tác động trở lại vật chất","Nhận thức mang tính lịch sử - xã hội"],"ans":1,"ex":"Quan điểm cho rằng thế giới không tồn tại nếu không có ý thức con người là duy tâm chủ quan, phủ nhận nguyên lý cơ bản: **vật chất tồn tại khách quan, độc lập với ý thức** và quyết định ý thức. Theo chủ nghĩa duy vật biện chứng, thế giới tồn tại trước con người, ý thức chỉ là sự phản ánh thế giới đó."},{"id":"C2-157","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong các yếu tố cấu thành của ý thức, yếu tố nào là quan trọng nhất và chi phối các yếu tốc còn lại?","opts":["Ý chí","Tri thức","Tình cảm","Niềm tin"],"ans":1,"ex":"Ý thức có kết cấu gồm tri thức, tình cảm, ý chí (niềm tin)... Trong đó **tri thức** là yếu tố cơ bản, cốt lõi, phương thức tồn tại của ý thức; nó định hướng và chi phối các yếu tố khác. Tình cảm, ý chí chỉ thực sự có hiệu quả khi dựa trên tri thức đúng đắn."},{"id":"C2-158","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Để thực hiện thành công mục tiêu phấn đấu “Vì một Việt Nam không còn đói nghèo” vào năm 2030, trước hết người nghèo cần được khơi dậy ý chí tự lực, tự cường, khát vọng vươn lên thoát nghèo. Tuy nhiên, ý chí, khát vọng này cần được thể hiện trong hoạt động lao động sản xuất, học tập để nâng cao trình độ, giúp người nghèo có kế sinh nhai ổn định và có thu nhập tốt hơn, từ đó có thể thoát nghèo bền vững. Điều này thể hiện khía cạnh nào trong mối quan hệ biện chứng giữa vật chất và ý thức?","opts":["Ý thức quyết định vật chất","Vật chất và ý thức có vai trò ngang nhau","Ý thức tác động trở lại vật chất thông qua hoạt động thực tiễn","Ý thức độc lập hoàn toàn với vật chất"],"ans":2,"ex":"Ý chí, khát vọng thoát nghèo là yếu tố ý thức, nhưng chỉ phát huy tác dụng khi được hiện thực hóa bằng lao động, học tập. Điều này thể hiện **ý thức tác động trở lại vật chất thông qua hoạt động thực tiễn**. Ý thức tự nó không làm thay đổi hiện thực, nên ý thức quyết định vật chất hay độc lập hoàn toàn là sai."},{"id":"C2-159","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"“Mọi sự vật, hiện tượng luôn gắn bó trong mối liên hệ phổ biến.”. Quan điểm này phản ánh nội dung nguyên lý nào của triết học Mác-Lênin?","opts":["Nguyên lý về sự phát triển","Nguyên lý về mối liên hệ phổ biến","Nguyên lý khách quan","Nguyên lý thực tiễn"],"ans":1,"ex":"**Nguyên lý về mối liên hệ phổ biến** khẳng định mọi sự vật, hiện tượng đều tồn tại trong mối liên hệ, tác động, ràng buộc lẫn nhau; mối liên hệ có tính khách quan, phổ biến và đa dạng. Từ đó rút ra quan điểm toàn diện. Nguyên lý về sự phát triển nói về khuynh hướng vận động đi lên."},{"id":"C2-160","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khi nhìn vào sự thay đổi của công nghệ từ 2G → 3G → 4G → 5G, chúng ta thấy biểu hiện rõ của nguyên lý nào?","opts":["Nguyên lý về mối liên hệ phổ biến","Nguyên lý về sự phù hợp giữa ý thức và vật chất","Nguyên lý về sự phát triển","Nguyên lý khách quan"],"ans":2,"ex":"Chuỗi 2G đến 5G là quá trình vận động đi lên, thế hệ sau kế thừa và hoàn thiện hơn thế hệ trước. Đây là biểu hiện của **nguyên lý về sự phát triển**: phát triển là vận động từ thấp đến cao, từ đơn giản đến phức tạp. Từ nguyên lý này rút ra quan điểm phát triển trong nhận thức và hành động."},{"id":"C2-161","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong quá trình phát triển, Việt Nam coi giáo dục và đào tạo là “quốc sách hàng đầu”. Theo quan điểm của triết học Mác - Lênin, điều này thể hiện việc:","opts":["Xác định đúng nguyên nhân cơ bản để tạo ra kết quả là phát triển con người toàn diện và bền vững","Tuyệt đối hóa vai trò của giáo dục","Giáo dục và đào tạo vừa là động lực, vừa là mục tiêu của quá trình phát triển","Chỉ tập trung vào lý luận mà thiếu thực tiễn"],"ans":0,"ex":"Theo cặp phạm trù **nguyên nhân – kết quả**, muốn có kết quả phải tìm đúng nguyên nhân tạo ra nó. Coi giáo dục, đào tạo là quốc sách hàng đầu là xác định đúng nguyên nhân cơ bản để phát triển nguồn nhân lực, con người toàn diện và phát triển bền vững. Đây không phải tuyệt đối hóa giáo dục hay thiếu thực tiễn."},{"id":"C2-162","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Theo quan điểm duy vật biện chứng, việc Việt Nam tăng cường hội nhập quốc tế tạo ra nhiều cơ hội nhưng cũng những thách thức trong quá trình phát triển kinh tế - xã hội. Điều này thể hiện:","opts":["Mối quan hệ nhân - quả mang luôn tác động qua lại","Một nguyên nhân có thể tạo ra nhiều kết quả khác nhau, tùy thuộc vào điều kiện cụ thể","Luôn xuất hiện cả nguyên nhân tích cực và nguyên nhân tiêu cực","Kết quả luôn phụ thuộc hoàn toàn vào hoàn cảnh cụ thể"],"ans":0,"ex":"Theo đáp án gốc, ví dụ thể hiện tính chất **tác động qua lại** của quan hệ nhân quả: hội nhập (nguyên nhân) tạo ra cơ hội và thách thức (kết quả), rồi các kết quả này lại tác động trở lại tiến trình hội nhập và phát triển. Giáo trình cũng chỉ ra một nguyên nhân có thể sinh ra nhiều kết quả; phương án B gần nội dung này nhưng đáp án gốc nhấn mạnh tính tác động qua lại."},{"id":"C2-163","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"“Không có sự vật nào tồn tại mà không chứa đựng mâu thuẫn bên trong nó”, luận điểm này của C. Mác phản ánh nội dung nào của quy luật thống nhất và đấu tranh giữa các mặt đối lập?","opts":["Mâu thuẫn là hiện tượng ngẫu nhiên","Mâu thuẫn là nguồn gốc bên ngoài của vận động","Mâu thuẫn là nguồn gốc, động lực của sự phát triển","Mâu thuẫn chỉ tồn tại trong tư duy con người"],"ans":2,"ex":"Luận điểm nêu tính **phổ biến của mâu thuẫn**: mọi sự vật đều chứa mâu thuẫn bên trong. Sự đấu tranh của các mặt đối lập là **nguồn gốc, động lực** bên trong của vận động và phát triển. Mâu thuẫn có tính khách quan, không ngẫu nhiên, không chỉ tồn tại trong tư duy và không phải là nguồn gốc bên ngoài."},{"id":"C2-164","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Một kim loại khi được nung nóng dần sẽ đến một điểm nhất định chuyển từ thể rắn sang thể lỏng. Đây là biểu hiện của quy luật nào?","opts":["Quy luật nhân quả","Quy luật chuyển hóa từ những thay đổi về lượng thành thay đổi về chất và ngược lại","Quy luật phủ định của phủ định","Quy luật mâu thuẫn"],"ans":1,"ex":"Nung nóng kim loại là tăng dần về lượng (nhiệt độ); đến điểm nút (nhiệt độ nóng chảy) thì xảy ra bước nhảy, kim loại chuyển từ rắn sang lỏng. Đây là biểu hiện của **quy luật lượng – chất**. Nhân quả không phải là một trong ba quy luật cơ bản của phép biện chứng."},{"id":"C2-165","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Trong tiến trình phát triển xã hội loài người, các hình thái kinh tế - xã hội lần lượt thay thế nhau từ Cộng sản nguyên thủy → Chiếm hữu nô lệ → Phong kiến → Tư bản chủ nghĩa → Cộng sản chủ nghĩa. Điều này minh họa cho quy luật nào?","opts":["Quy luật lượng - chất","Quy luật mâu thuẫn","Quy luật phủ định của phủ định","Quy luật nhân quả"],"ans":2,"ex":"Các hình thái kinh tế – xã hội thay thế nhau là chuỗi các lần **phủ định biện chứng**: hình thái sau ra đời từ hình thái trước, kế thừa và vượt qua nó. Từ công hữu nguyên thủy qua chế độ tư hữu đến công hữu ở trình độ cao hơn trong chủ nghĩa cộng sản thể hiện đường xoáy ốc. Vì vậy ví dụ minh họa quy luật phủ định của phủ định."},{"id":"C2-166","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Để một giả thuyết khoa học mới được thừa nhận, thì cần phải kiểm chứng bằng thí nghiệm và thực nghiệm. Điều này thể hiện quan điểm nào của triết học Mác - Lênin?","opts":["Tuyệt đối hóa vai trò của thực tiễn","Thực tiễn là tiêu chuẩn của chân lý","Thực tiễn phụ thuộc vào lý luận","Nhận thức không cần qua thực tiễn"],"ans":1,"ex":"Giả thuyết khoa học phải được kiểm chứng bằng thí nghiệm, thực nghiệm (một hình thức thực tiễn) mới được thừa nhận là chân lý. Điều này thể hiện quan điểm **thực tiễn là tiêu chuẩn của chân lý**. Đây không phải tuyệt đối hóa thực tiễn, mà là khẳng định vai trò kiểm nghiệm khách quan của thực tiễn."},{"id":"C2-167","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Văn kiện Đại hội đại biểu toàn quốc lần thứ XIII của Đảng xác định phải tiếp tục nắm vững và xử lý tốt mối quan hệ lớn “Giữa tăng trưởng kinh tế và phát triển văn hóa, thực hiện tiến bộ, công bằng xã hội, bảo vệ môi trường”. Quan điểm này thể hiện phương pháp luận nào của triết học Mác - Lênin?","opts":["Siêu hình","Biện chứng","Chủ quan","Toàn diện"],"ans":1,"ex":"Xem xét tăng trưởng kinh tế trong mối liên hệ với văn hóa, công bằng xã hội và môi trường là cách tiếp cận **biện chứng**: thấy các mặt trong mối liên hệ, tác động qua lại và phát triển. Quan điểm toàn diện là một nguyên tắc cụ thể nằm trong phương pháp biện chứng; đáp án gốc chọn phương pháp luận chung là biện chứng. Siêu hình xem xét sự vật cô lập, tĩnh tại."},{"id":"C2-168","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Thế nào là phép biện chứng duy tâm?","opts":["Là phép biện chứng được xác lập trên lập trường của chủ nghĩa duy tâm","Là phép biện chứng của vật chất","Là phép biện chứng giải thích về nguồn gốc của sự vận động, biến đổi thế giới dưới lập trường duy vật","Là khái niệm dùng để chỉ thế giới quan duy tâm"],"ans":0,"ex":"**Phép biện chứng duy tâm** là phép biện chứng được xây dựng trên lập trường duy tâm, tiêu biểu là triết học cổ điển Đức với đỉnh cao là **Hêghen**: coi biện chứng của ý niệm, tinh thần sinh ra biện chứng của sự vật. Mác đã kế thừa hạt nhân hợp lý và cải tạo nó trên lập trường duy vật."},{"id":"C2-169","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Phương pháp siêu hình thống trị triết học vào thời kì nào?","opts":["Thế kỉ XV - XVI","Thế kỉ XVII - XVIII","Thế kỉ XVIII - XIX","Thế kỉ XIX - XX"],"ans":1,"ex":"**Phương pháp siêu hình** thống trị triết học và khoa học châu Âu vào **thế kỷ XVII – XVIII**, gắn với sự phát triển của cơ học và phương pháp phân tích, phân loại trong khoa học tự nhiên. Đến cuối thế kỷ XVIII – XIX, những phát minh khoa học đã làm lộ rõ hạn chế của nó và mở đường cho phép biện chứng."},{"id":"C2-170","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Câu nói của Lênin: “Từ trực quan sinh động đến tư duy trừu tượng, từ tư duy trừu tượng đến thực tiễn, đó là con đường biện chứng của nhận thức chân lý” phản ánh điều gì?","opts":["Vai trò quyết định của thực tiễn trong quá trình nhận thức và kiểm nghiệm chân lý","Nhận thức là quá trình thuần túy tư duy logic, không liên quan đến thực tiễn","Sự phát triển nhận thức của con người phụ thuộc hoàn toàn vào thực tiễn","Nhận thức do kinh nghiệm được tích lũy từ thực tiễn"],"ans":0,"ex":"Câu nói của **V.I. Lênin** trong Bút ký triết học khái quát con đường biện chứng của nhận thức: từ nhận thức cảm tính lên lý tính, rồi trở về thực tiễn. Thực tiễn vừa là cơ sở vừa là nơi kiểm nghiệm chân lý, giữ **vai trò quyết định** trong quá trình nhận thức. Nhận thức không phải thuần túy tư duy logic, cũng không phụ thuộc hoàn toàn vào thực tiễn."},{"id":"C2-171","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Sự phát triển mạnh mẽ của trí tuệ nhân tạo ngày nay phản ánh khía cạnh nào của mối quan hệ giữa vật chất và ý thức trong triết học?","opts":["Ý thức có thể tồn tại độc lập và sáng tạo ra thế giới vật chất","Sự phản ánh năng động, sáng tạo của ý thức đối với hiện thực khách quan","Vật chất chỉ là sản phẩm của tư duy con người","So với vật chất thì ý thức ngày càng có vai trò quan trọng hơn"],"ans":1,"ex":"Trí tuệ nhân tạo là sản phẩm của trí tuệ con người, thể hiện **tính năng động, sáng tạo của ý thức**: ý thức không chỉ phản ánh hiện thực mà còn sáng tạo ra tri thức, công cụ mới cải tạo thế giới. Ý thức không tồn tại độc lập hay sáng tạo ra thế giới vật chất; vật chất vẫn quyết định ý thức."},{"id":"C2-172","chapter":2,"topic":"Chương 2: Chủ nghĩa duy vật biện chứng","q":"Khẳng định: “vật chất là phức hợp những cảm giác của con người\", đó là quan điểm của trường phái triết học nào?","opts":["Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy vật siêu hình"],"ans":1,"ex":"Quan điểm vật chất là phức hợp những cảm giác thuộc **chủ nghĩa duy tâm chủ quan** (Béccơli, Makhơ), coi cảm giác của chủ thể là cái có trước, sự vật chỉ là tổ hợp cảm giác. Lênin phê phán quan điểm này trong Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán. Duy tâm khách quan lại coi ý niệm tuyệt đối là bản nguyên."},{"id":"C3-001","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, sản xuất là một loại hình hoạt động đặc trưng của con người và xã hội loài người, bao gồm:","opts":["Sản xuất vật chất","Sản xuất tinh thần","Sản xuất ra bản thân con người","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Chủ nghĩa duy vật lịch sử coi **sản xuất** là hoạt động đặc trưng của con người, gồm ba loại hình gắn bó với nhau: **sản xuất vật chất** (tạo ra của cải vật chất), **sản xuất tinh thần** (tạo ra giá trị tư tưởng, văn hóa) và **sản xuất ra bản thân con người** (tái sản xuất con người, nòi giống). Trong đó sản xuất vật chất là nền tảng, nhưng cả ba đều thuộc khái niệm sản xuất, nên chọn phương án bao quát tất cả."},{"id":"C3-002","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền vào chỗ trống, khái niệm… là hoạt động không ngừng sáng tạo ra các giá trị vật chất và tinh thần nhằm mục đích thỏa mãn nhu cầu tồn tại và phát triển của con người.","opts":["Sản xuất vật chất","Sản xuất tinh thần","Sản xuất","Sản xuất ra bản thân con người"],"ans":2,"ex":"Định nghĩa này nói đến cả giá trị **vật chất và tinh thần**, nên đó là khái niệm **sản xuất** nói chung – hoạt động không ngừng sáng tạo nhằm thỏa mãn nhu cầu tồn tại và phát triển của con người. Các phương án sản xuất vật chất, sản xuất tinh thần hay sản xuất ra con người chỉ là từng loại hình bộ phận, hẹp hơn phạm vi định nghĩa nêu ra."},{"id":"C3-003","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vai trò quyết định của sản xuất vật chất được thể hiện:","opts":["Là nhân tố quyết định sự tồn tại, phát triển của con người và xã hội","Là hoạt động nền tảng làm phát sinh, phát triển những mối quan hệ xã hội","Là cơ sở của sự hình thành, biến đổi và phát triển của xã hội loài người","Tất cả các phương án đều đúng"],"ans":3,"ex":"Theo C.Mác và Ph.Ăngghen, trước hết con người phải ăn, uống, ở, mặc rồi mới làm chính trị, khoa học, nghệ thuật. Vì vậy **sản xuất vật chất** là nhân tố quyết định sự tồn tại, phát triển của con người và xã hội; là nền tảng làm phát sinh các quan hệ xã hội (kinh tế, chính trị, pháp quyền...); và là cơ sở cho sự hình thành, biến đổi, phát triển của xã hội. Cả ba biểu hiện đều đúng."},{"id":"C3-004","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Phương thức sản xuất bao gồm:","opts":["Lực lượng sản xuất, quan hệ sản xuất và cơ sở hạ tầng","Lực lượng sản xuất và quan hệ sản xuất","Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng và kiến trúc thượng tầng","Tất cả các đáp án trên đều không đúng"],"ans":1,"ex":"**Phương thức sản xuất** là cách thức con người tiến hành sản xuất vật chất ở một giai đoạn lịch sử nhất định, là sự thống nhất giữa **lực lượng sản xuất** ở một trình độ nhất định và **quan hệ sản xuất** tương ứng. Cơ sở hạ tầng và kiến trúc thượng tầng là cặp phạm trù khác, phản ánh quan hệ kinh tế – chính trị, không phải bộ phận cấu thành phương thức sản xuất."},{"id":"C3-005","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Mối quan hệ nào sau đây được coi là mối quan hệ song trùng trong quá trình sản xuất?","opts":["Nhận thức và thực tiễn","Cơ sở hạ tầng và kiến trúc thượng tầng","Lực lượng sản xuất và quan hệ sản xuất","Tồn tại xã hội và ý thức xã hội"],"ans":2,"ex":"Quá trình sản xuất luôn đồng thời diễn ra hai mối quan hệ: quan hệ giữa con người với tự nhiên (**lực lượng sản xuất**) và quan hệ giữa người với người (**quan hệ sản xuất**). Vì hai mối quan hệ này cùng tồn tại song song, không tách rời trong một quá trình, nên được gọi là quan hệ “song trùng”. Các cặp còn lại thuộc lĩnh vực nhận thức hoặc cấu trúc xã hội."},{"id":"C3-006","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Phạm trù thể hiện mối quan hệ giữa con người với tự nhiên trong quá trình sản xuất là:","opts":["Lực lượng sản xuất","Quan hệ sản xuất","Tư liệu sản xuất","Phương thức sản xuất"],"ans":0,"ex":"**Lực lượng sản xuất** là sự kết hợp giữa người lao động với tư liệu sản xuất, tạo ra sức sản xuất và năng lực thực tiễn cải biến giới tự nhiên. Nó biểu hiện mối quan hệ giữa con người với tự nhiên. Ngược lại, quan hệ sản xuất là quan hệ giữa người với người; tư liệu sản xuất chỉ là một yếu tố của lực lượng sản xuất; phương thức sản xuất là sự thống nhất của cả hai."},{"id":"C3-007","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong lực lượng sản xuất, nhân tố hàng đầu giữ vai trò quyết định là?","opts":["Người lao động","Công cụ lao động","Tư liệu sản xuất","Tư liệu lao động"],"ans":0,"ex":"Lực lượng sản xuất gồm **người lao động** và **tư liệu sản xuất**. V.I.Lênin khẳng định lực lượng sản xuất hàng đầu của toàn thể nhân loại là công nhân, người lao động. Người lao động là chủ thể sáng tạo, sử dụng và cải tiến công cụ, nên giữ vai trò quyết định. Công cụ lao động là yếu tố động nhất, cách mạng nhất nhưng vẫn do con người tạo ra và sử dụng."},{"id":"C3-008","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong nền sản xuất Tư bản chủ nghĩa, bản chất mối quan hệ giữa người lao động với tư liệu sản xuất là gì?","opts":["Người lao động làm chủ tư liệu sản xuất","Người lao động phụ thuộc vào tư liệu sản xuất","Người lao động và tư liệu sản xuất có quan hệ ngang bằng nhau","Không có đáp án nào đúng"],"ans":1,"ex":"Trong chủ nghĩa tư bản, tư liệu sản xuất thuộc sở hữu tư nhân của nhà tư bản; người lao động (công nhân) bị tách khỏi tư liệu sản xuất, phải bán sức lao động để được kết hợp với chúng. Do đó người lao động ở vào thế **phụ thuộc** vào tư liệu sản xuất và vào người sở hữu chúng. Họ không làm chủ tư liệu sản xuất, càng không có quan hệ ngang bằng."},{"id":"C3-009","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong tư liệu sản xuất, yếu tố nào được coi là yếu tố động nhất, cách mạng nhất?","opts":["Con người và công cụ lao động","Công cụ lao động","Đối tượng lao động","Tư liệu lao động"],"ans":1,"ex":"Tư liệu sản xuất gồm **đối tượng lao động** và **tư liệu lao động**; trong tư liệu lao động, **công cụ lao động** là yếu tố trực tiếp tác động vào đối tượng lao động. Công cụ luôn được cải tiến, là nguyên nhân sâu xa của mọi biến đổi kinh tế, nên là yếu tố **động nhất, cách mạng nhất**. Phương án có “con người” sai vì con người không thuộc tư liệu sản xuất."},{"id":"C3-010","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Yếu tố nào sau đây không thuộc lực lượng sản xuất?","opts":["Quan hệ về sở hữu tư liệu sản xuất","Người lao động","Tư liệu sản xuất","Khoa học và công nghệ"],"ans":0,"ex":"Lực lượng sản xuất gồm người lao động, tư liệu sản xuất, và ngày nay **khoa học – công nghệ** trở thành lực lượng sản xuất trực tiếp. Còn **quan hệ sở hữu tư liệu sản xuất** là một mặt của **quan hệ sản xuất** (quan hệ giữa người với người), nên không thuộc lực lượng sản xuất."},{"id":"C3-011","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, trình độ của lực lượng sản xuất thể hiện ở:","opts":["Trình độ công cụ lao động và người lao động","Trình độ tổ chức và phân công lao động xã hội","Trình độ ứng dụng khoa học và công nghệ vào sản xuất","Tất cả các phương án trên đều đúng"],"ans":3,"ex":"Trình độ của lực lượng sản xuất là khả năng của con người chinh phục, cải biến tự nhiên, thể hiện ở: trình độ của **công cụ lao động** và **người lao động** (kỹ năng, kinh nghiệm, tri thức); trình độ **tổ chức, phân công lao động xã hội**; và trình độ **ứng dụng khoa học – công nghệ** vào sản xuất. Vì vậy phương án tổng hợp là đúng."},{"id":"C3-012","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Phạm trù thể hiện mối quan hệ giữa con người với con người trong quá trình sản xuất là:","opts":["Lực lượng sản xuất","Quan hệ sản xuất","Tư liệu sản xuất","Phương thức sản xuất"],"ans":1,"ex":"**Quan hệ sản xuất** là tổng hợp các quan hệ kinh tế – vật chất giữa người với người trong quá trình sản xuất, gồm quan hệ sở hữu tư liệu sản xuất, quan hệ tổ chức – quản lý và quan hệ phân phối. Đây là quan hệ xã hội cơ bản, vật chất, khách quan, không phụ thuộc ý muốn chủ quan. Lực lượng sản xuất thì biểu hiện quan hệ người – tự nhiên."},{"id":"C3-013","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong quan hệ sản xuất, quan hệ nào giữ vai trò quyết định?","opts":["Quan hệ về sở hữu đối với tư liệu sản xuất","Quan hệ về tổ chức, quản lý quá trình sản xuất","Quan hệ về phân phối kết quả của quá trình sản xuất","Tất cả các phương án trên đều sai"],"ans":0,"ex":"Trong ba mặt của quan hệ sản xuất, **quan hệ sở hữu đối với tư liệu sản xuất** là quan hệ xuất phát, cơ bản, giữ vai trò quyết định. Ai nắm tư liệu sản xuất thì người đó quyết định việc tổ chức, quản lý sản xuất và phân phối sản phẩm. Hai quan hệ còn lại tuy có tác động trở lại nhưng chịu sự chi phối của quan hệ sở hữu."},{"id":"C3-014","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong quan hệ sản xuất, quan hệ nào kích thích trực tiếp vào lợi ích của người lao động?","opts":["Quan hệ về sở hữu đối với tư liệu sản xuất","Quan hệ về tổ chức, quản lý quá trình sản xuất","Quan hệ về phân phối kết quả của quá trình sản xuất","Không có đáp án nào đúng"],"ans":2,"ex":"**Quan hệ phân phối kết quả sản xuất** quyết định phần của cải mà mỗi người được hưởng, do đó **kích thích trực tiếp** vào lợi ích của người lao động, là “chất xúc tác” thúc đẩy hoặc kìm hãm sản xuất. Quan hệ sở hữu giữ vai trò quyết định, quan hệ tổ chức – quản lý có vai trò chi phối quy mô, tốc độ sản xuất, nhưng không trực tiếp tác động lợi ích như quan hệ phân phối."},{"id":"C3-015","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự hình thành, biến đổi và phát triển của quan hệ sản xuất bị quyết định bởi:","opts":["Ý chí của con người","Lực lượng siêu nhiên","Trình độ phát triển của lực lượng sản xuất","Trình độ phát triển của kiến trúc thượng tầng"],"ans":2,"ex":"Theo **quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất**, lực lượng sản xuất là nội dung, quan hệ sản xuất là hình thức; lực lượng sản xuất quyết định sự hình thành, biến đổi của quan hệ sản xuất. Quan hệ sản xuất mang tính khách quan, không do ý chí con người hay lực lượng siêu nhiên quyết định; kiến trúc thượng tầng cũng không quyết định nó."},{"id":"C3-016","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quan hệ sản xuất KHÔNG bao gồm quan hệ nào sau đây?","opts":["Quan hệ về sở hữu đối với tư liệu sản xuất","Quan hệ về tổ chức, quản lý quá trình sản xuất","Quan hệ về phân phối kết quả của quá trình sản xuất","Quan hệ mua – bán"],"ans":3,"ex":"Quan hệ sản xuất gồm ba mặt: **sở hữu tư liệu sản xuất**, **tổ chức – quản lý sản xuất** và **phân phối kết quả sản xuất**. Quan hệ mua – bán là quan hệ trao đổi trên thị trường, thuộc khâu lưu thông chứ không phải một trong ba mặt cấu thành quan hệ sản xuất theo giáo trình."},{"id":"C3-017","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quy luật xã hội nào được coi là cơ bản nhất và giữ vai trò quyết định đối với sự vận động, phát triển của xã hội?","opts":["Quy luật đấu tranh giai cấp","Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất","Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng","Quy luật tồn tại xã hội quyết định ý thức xã hội"],"ans":1,"ex":"**Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất** là quy luật cơ bản nhất của sự vận động, phát triển xã hội, vì nó tác động trong mọi hình thái kinh tế – xã hội và quyết định sự thay thế phương thức sản xuất. Các quy luật khác (cơ sở hạ tầng – kiến trúc thượng tầng, tồn tại xã hội – ý thức xã hội, đấu tranh giai cấp) đều dựa trên và chịu sự chi phối của quy luật này."},{"id":"C3-018","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nếu quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất, thì:","opts":["Thúc đẩy sự phát triển của lực lượng sản xuất","Kìm hãm sự phát triển của lực lượng sản xuất","Không thay đổi sự phát triển của lực lượng sản xuất","Vừa kìm hãm, vừa thúc đẩy sự phát triển của lực lượng sản xuất"],"ans":0,"ex":"Khi **quan hệ sản xuất phù hợp** với trình độ lực lượng sản xuất, các yếu tố của sản xuất kết hợp hài hòa, người lao động được kích thích lợi ích, do đó quan hệ sản xuất trở thành động lực **thúc đẩy** lực lượng sản xuất phát triển. Ngược lại, khi không phù hợp (lạc hậu hoặc vượt trước), nó sẽ kìm hãm, thậm chí phá hoại lực lượng sản xuất."},{"id":"C3-019","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quan hệ sản xuất không phù hợp với trình độ phát triển của lực lượng sản xuất được biểu hiện ở:","opts":["Quan hệ sản xuất lỗi thời, lạc hậu hơn","Quan hệ sản xuất tiến bộ, vượt trước một cách giả tạo","Xây dựng quan hệ sản xuất thiếu đồng bộ","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Sự không phù hợp của quan hệ sản xuất có nhiều biểu hiện: quan hệ sản xuất **lỗi thời, lạc hậu** hơn lực lượng sản xuất; quan hệ sản xuất **vượt trước một cách giả tạo** (như duy ý chí trong cải tạo quan hệ sở hữu); hoặc các mặt của quan hệ sản xuất được xây dựng **thiếu đồng bộ**. Tất cả đều làm kìm hãm sản xuất, nên chọn phương án tổng hợp."},{"id":"C3-020","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Xây dựng nền kinh tế thị trường định hướng xã hội chủ nghĩa là mô hình kinh tế tổng quát, là sự vận dụng quy luật xã hội nào trong phát triển kinh tế ở Việt Nam hiện nay?","opts":["Cơ sở hạ tầng quyết định kiến trúc thượng tầng","Quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất","Tồn tại xã hội quyết định ý thức xã hội","Đấu tranh giai cấp"],"ans":1,"ex":"Ở Việt Nam, lực lượng sản xuất còn nhiều trình độ khác nhau, nên Đảng chủ trương phát triển **kinh tế thị trường định hướng xã hội chủ nghĩa** với nhiều hình thức sở hữu, nhiều thành phần kinh tế. Đây là sự vận dụng **quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất**, nhằm tạo quan hệ sản xuất thích ứng để giải phóng sức sản xuất."},{"id":"C3-021","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống: Khái niệm … dùng để chỉ toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội.","opts":["Kiến trúc thượng tầng","Lực lượng sản xuất","Tồn tại xã hội","Cơ sở hạ tầng"],"ans":3,"ex":"**Cơ sở hạ tầng** là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định, gồm quan hệ sản xuất thống trị, quan hệ sản xuất tàn dư và quan hệ sản xuất mầm mống. Khác với kiến trúc thượng tầng (tư tưởng, thiết chế), cơ sở hạ tầng thuộc đời sống kinh tế; nó cũng khác lực lượng sản xuất vì không bao gồm quan hệ người – tự nhiên."},{"id":"C3-022","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, trong cơ sở hạ tầng của xã hội thì yếu tố nào giữ vai trò quyết định?","opts":["Quan hệ sản xuất tàn dư","Quan hệ sản xuất thống trị","Quan hệ sản xuất mầm mống","Tất cả các phương án đều đúng"],"ans":1,"ex":"Trong cơ sở hạ tầng có ba loại quan hệ sản xuất: **thống trị**, **tàn dư** (của xã hội cũ) và **mầm mống** (của xã hội tương lai). **Quan hệ sản xuất thống trị** giữ vai trò chủ đạo, quyết định tính chất, đặc trưng của cơ sở hạ tầng và qua đó quyết định tính chất của kiến trúc thượng tầng. Các quan hệ tàn dư, mầm mống chỉ giữ vị trí thứ yếu."},{"id":"C3-023","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống: Theo chủ nghĩa duy vật lịch sử, cơ sở hạ tầng là phương diện … của xã hội.","opts":["Kinh tế","Chính trị","Xã hội","Văn hóa"],"ans":0,"ex":"**Cơ sở hạ tầng** chính là cơ cấu kinh tế của xã hội, tức toàn bộ các quan hệ sản xuất, nên nó là phương diện **kinh tế** của đời sống xã hội. Trong khi đó, chính trị, pháp quyền, văn hóa, tư tưởng thuộc về kiến trúc thượng tầng – phương diện chính trị – xã hội được xây dựng trên nền tảng kinh tế ấy."},{"id":"C3-024","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống: Khái niệm … dùng để chỉ toàn bộ những tư tưởng xã hội cùng với các thiết chế chính trị - xã hội tương ứng, được hình thành trên một cơ sở hạ tầng nhất định.","opts":["Cơ sở hạ tầng","Kiến trúc thượng tầng","Lực lượng sản xuất","Tồn tại xã hội"],"ans":1,"ex":"**Kiến trúc thượng tầng** là toàn bộ những tư tưởng xã hội (chính trị, pháp quyền, đạo đức, tôn giáo, nghệ thuật, triết học...) cùng các thiết chế chính trị – xã hội tương ứng (nhà nước, đảng phái, giáo hội, đoàn thể...) hình thành trên một cơ sở hạ tầng nhất định. Trong đó **nhà nước** là bộ phận quyền lực nhất."},{"id":"C3-025","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống: Theo chủ nghĩa duy vật lịch sử, kiến trúc thượng tầng là phương diện… của xã hội.","opts":["Kinh tế","Chính trị - xã hội","Sản xuất","Tiêu dùng"],"ans":1,"ex":"Nếu cơ sở hạ tầng là phương diện kinh tế, thì **kiến trúc thượng tầng** là phương diện **chính trị – xã hội** của xã hội, bao gồm các hình thái ý thức xã hội và thiết chế chính trị – xã hội. Sản xuất và tiêu dùng là các khâu của đời sống kinh tế, không phải đặc trưng của kiến trúc thượng tầng."},{"id":"C3-026","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong kiến trúc thượng tầng, yếu tố nào thường biến đổi nhanh khi cơ sở hạ tầng thay đổi?","opts":["Đạo đức","Tôn giáo","Nhà nước","Tất cả các phương án trên đều sai"],"ans":2,"ex":"Khi cơ sở hạ tầng thay đổi, các bộ phận của kiến trúc thượng tầng biến đổi không đồng thời. Những bộ phận gắn trực tiếp với kinh tế như **nhà nước**, chính trị, pháp luật thay đổi nhanh chóng. Còn các bộ phận như **đạo đức, tôn giáo**, nghệ thuật, triết học biến đổi chậm, thậm chí tồn tại lâu dài sau khi cơ sở kinh tế sinh ra chúng đã mất."},{"id":"C3-027","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Thực chất của mối quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng là:","opts":["Quan hệ giữa đời sống vật chất và đời sống tinh thần của xã hội","Quan hệ giữa kinh tế và chính trị","Quan hệ giữa vật chất và tinh thần","Quan hệ giữa tồn tại xã hội với ý thức xã hội"],"ans":1,"ex":"Về thực chất, quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng là mối quan hệ giữa **kinh tế và chính trị**: kinh tế quyết định chính trị, chính trị tác động trở lại kinh tế. Các phương án vật chất – tinh thần hay tồn tại xã hội – ý thức xã hội là những cặp phạm trù khác, rộng hơn hoặc thuộc nội dung khác của chủ nghĩa duy vật lịch sử."},{"id":"C3-028","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chủ nghĩa duy vật lịch sử khẳng định cơ sở hạ tầng quyết định kiến trúc thượng tầng, bởi vì:","opts":["Quan hệ vật chất quyết định quan hệ tinh thần và thể chế","Tính tất yếu kinh tế xét đến cùng quyết định tính tất yếu chính trị - xã hội","Quan hệ vật chất quyết định quan hệ tinh thần và tính tất yếu kinh tế xét đến cùng quyết định tính tất yếu chính trị - xã hội","Do vai trò sức mạnh vật chất của bộ máy tổ chức – thể chế"],"ans":2,"ex":"Cơ sở hạ tầng quyết định kiến trúc thượng tầng vì hai lý do cơ bản: **quan hệ vật chất quyết định quan hệ tinh thần và thể chế**, và **tính tất yếu kinh tế xét đến cùng quyết định tính tất yếu chính trị – xã hội**. Phương án kết hợp cả hai lý do là đầy đủ nhất. Vai trò sức mạnh của bộ máy thể chế là lý do kiến trúc thượng tầng tác động ngược lại, không phải lý do quyết định."},{"id":"C3-029","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vì sao kiến trúc thượng tầng tác động trở lại cơ sở hạ tầng?","opts":["Do tính độc lập tương đối của kiến trúc thượng tầng","Do tính năng động, sáng tạo, tích cực, tự giác của ý thức, tinh thần, tư tưởng","Do vai trò sức mạnh vật chất của bộ máy tổ chức – thể chế","Tất cả các đáp án trên"],"ans":3,"ex":"Kiến trúc thượng tầng tác động trở lại cơ sở hạ tầng vì: nó có **tính độc lập tương đối**; ý thức, tư tưởng có **tính năng động, sáng tạo, tự giác**; và các thiết chế (nhà nước, đảng phái...) có **sức mạnh vật chất** của bộ máy tổ chức. Ba nguyên nhân này bổ sung cho nhau, nên phương án tổng hợp là đúng."},{"id":"C3-030","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Kiến trúc thượng tầng tác động trở lại cơ sở hạ tầng nhằm:","opts":["Củng cố, hoàn thiện và bảo vệ cơ sở hạ tầng sinh ra nó, thực chất là bảo vệ lợi ích kinh tế của giai cấp thống trị","Ngăn chặn cơ sở hạ tầng mới, xoá bỏ tàn dư cơ sở hạ tầng cũ","Định hướng, tổ chức, xây dựng chế độ kinh tế","Tất cả các phương án nêu trên"],"ans":3,"ex":"Sự tác động trở lại của kiến trúc thượng tầng thể hiện ở chức năng xã hội cơ bản: **củng cố, bảo vệ cơ sở hạ tầng** sinh ra nó (thực chất là bảo vệ lợi ích kinh tế của giai cấp thống trị); **ngăn chặn** cơ sở hạ tầng mới, đấu tranh xóa bỏ tàn dư cũ; đồng thời **định hướng, tổ chức, xây dựng** chế độ kinh tế. Vì vậy cả ba nội dung đều đúng."},{"id":"C3-031","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là nội dung cơ sở hạ tầng quyết định kiến trúc thượng tầng?","opts":["Quyết định sự ra đời của kiến trúc thượng tầng","Quyết định cơ cấu và tính chất của kiến trúc thượng tầng","Quyết định sự vận động, phát triển của kiến trúc thượng tầng","Quyết định tính độc lập tương đối của kiến trúc thượng tầng"],"ans":3,"ex":"Vai trò quyết định của cơ sở hạ tầng thể hiện ở chỗ nó quyết định **sự ra đời**, **cơ cấu, tính chất** và **sự vận động, phát triển** của kiến trúc thượng tầng. Còn **tính độc lập tương đối** là thuộc tính vốn có của kiến trúc thượng tầng, là cơ sở để nó tác động trở lại, chứ không phải nội dung do cơ sở hạ tầng quyết định."},{"id":"C3-033","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo C.Mác: Sự phát triển của những hình thái kinh tế - xã hội là một quá trình…","opts":["Lịch sử - tự nhiên","Lịch sử - xã hội","Lịch sử - khoa học","Lịch sử - tôn giáo"],"ans":0,"ex":"Trong lời tựa tập I bộ **Tư bản**, C.Mác viết: “Tôi coi sự phát triển của những hình thái kinh tế – xã hội là một **quá trình lịch sử – tự nhiên**”. Nghĩa là xã hội vận động theo các quy luật khách quan, không phụ thuộc ý chí con người, tương tự như quá trình tự nhiên, dù được thực hiện thông qua hoạt động có ý thức của con người."},{"id":"C3-034","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Yếu tố nào sau đây không thuộc cấu trúc của hình thái kinh tế - xã hội?","opts":["Lực lượng sản xuất","Quan hệ sản xuất","Điều kiện tự nhiên","Kiến trúc thượng tầng"],"ans":2,"ex":"**Hình thái kinh tế – xã hội** là xã hội ở từng giai đoạn lịch sử với kiểu **quan hệ sản xuất** đặc trưng, phù hợp với một trình độ **lực lượng sản xuất** nhất định và một **kiến trúc thượng tầng** tương ứng. Ba yếu tố này là cấu trúc cơ bản. **Điều kiện tự nhiên** (môi trường địa lý) là điều kiện thường xuyên của sản xuất, nhưng không phải yếu tố cấu thành hình thái."},{"id":"C3-035","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, nguyên nhân sâu xa của sự phát triển của các hình thái kinh tế - xã hội trong lịch sử là:","opts":["Ý muốn chủ quan của con người","Sự phát triển của quan hệ sản xuất","Ý muốn của Thượng Đế","Sự phát triển của lực lượng sản xuất"],"ans":3,"ex":"Sự phát triển của **lực lượng sản xuất** là nguyên nhân sâu xa: lực lượng sản xuất phát triển làm quan hệ sản xuất thay đổi, kéo theo sự biến đổi cơ sở hạ tầng và kiến trúc thượng tầng, dẫn tới thay thế hình thái kinh tế – xã hội. Quan hệ sản xuất chỉ biến đổi do bị lực lượng sản xuất quyết định; ý muốn chủ quan hay Thượng đế là quan điểm duy tâm."},{"id":"C3-036","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Thời đại đồ đồng tương ứng với hình thái kinh tế - xã hội nào trong lịch sử xã hội loài người?","opts":["Hình thái kinh tế - xã hội Cộng sản nguyên thủy","Hình thái kinh tế - xã hội Chiếm hữu nô lệ","Hình thái kinh tế - xã hội Phong kiến","Hình thái kinh tế - xã hội Tư bản"],"ans":1,"ex":"Mỗi trình độ công cụ lao động gắn với một kiểu quan hệ sản xuất. Công cụ đồ đá tương ứng với xã hội **cộng sản nguyên thủy**; công cụ **kim loại (đồ đồng)** làm năng suất tăng, xuất hiện của cải dư thừa và tư hữu, dẫn tới xã hội **chiếm hữu nô lệ**. Đến đồ sắt và cối xay quay tay gắn với phong kiến, máy hơi nước gắn với tư bản chủ nghĩa."},{"id":"C3-037","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của C. Mác: lịch sử xã hội loài người là một tiến trình nối tiếp nhau từ thấp đến cao của các hình thái kinh tế - xã hội?","opts":["Công xã nguyên thủy, chiếm hữu nô lệ, phong kiến, tư bản chủ nghĩa, xã hội chủ nghĩa","Cộng sản nguyên thuỷ, chiếm hữu nô lệ, phong kiến, tư bản chủ nghĩa, cộng sản chủ nghĩa","Công xã nguyên thủy, phong kiến, chiếm hữu nô lệ, chủ nghĩa tư bản, chủ nghĩa xã hội","Cộng sản nguyên thủy, phong kiến, chiếm hữu nô lệ, tư bản chủ nghĩa, xã hội chủ nghĩa"],"ans":1,"ex":"Khái quát của C.Mác: lịch sử loài người trải qua năm hình thái kinh tế – xã hội từ thấp đến cao: **cộng sản nguyên thủy, chiếm hữu nô lệ, phong kiến, tư bản chủ nghĩa, cộng sản chủ nghĩa** (mà chủ nghĩa xã hội là giai đoạn đầu). Các phương án đảo thứ tự phong kiến và chiếm hữu nô lệ là sai; dùng “xã hội chủ nghĩa” thay cho hình thái cộng sản chủ nghĩa cũng chưa chính xác."},{"id":"C3-038","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là nội dung giá trị khoa học bền vững và ý nghĩa cách mạng của học thuyết hình thái kinh tế - xã hội?","opts":["Đem lại một cuộc cách mạng trong quan niệm và phân tích về lịch sử xã hội","Là cơ sở phương pháp luận trong hoạt động nhận thức và cải tạo xã hội","Là cơ sở khoa học quán triệt quan điểm của Đảng ta về con đường đi lên chủ nghĩa xã hội ở Việt Nam","Là một học thuyết theo trường phái duy tâm"],"ans":3,"ex":"Học thuyết hình thái kinh tế – xã hội là một phát minh lớn của **chủ nghĩa duy vật lịch sử**, đã đem lại cuộc cách mạng trong quan niệm về lịch sử, khắc phục quan điểm duy tâm; là cơ sở phương pháp luận nhận thức và cải tạo xã hội; và là cơ sở khoa học cho đường lối đi lên chủ nghĩa xã hội ở Việt Nam. Vì vậy nói đó là học thuyết **duy tâm** là sai."},{"id":"C3-039","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Con đường quá độ lên chủ nghĩa xã hội ở Việt Nam là con đường phát triển theo hình thức nào trong tiến trình lịch sử - tự nhiên của xã hội loài người?","opts":["Phát triển theo tuần tự qua các hình thái kinh tế - xã hội.","Phát triển theo xu hướng chung, tuần tự.","Phát triển theo hướng “bỏ qua” một vài hình thái kinh tế - xã hội để tiến lên hình thái kinh tế - xã hội cao hơn.","Phát triển theo xu hướng không đồng đều."],"ans":2,"ex":"Tiến trình lịch sử – tự nhiên có thể diễn ra tuần tự hoặc **“bỏ qua”** một hay vài hình thái khi có điều kiện khách quan và chủ quan phù hợp. Việt Nam quá độ lên chủ nghĩa xã hội **bỏ qua chế độ tư bản chủ nghĩa**, tức bỏ qua việc xác lập địa vị thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản, nhưng vẫn tiếp thu thành tựu của nhân loại."},{"id":"C3-040","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Xuất phát từ cơ sở lý luận nào của chủ nghĩa Mác – Lênin, Đảng Cộng sản Việt Nam khẳng định: Việt Nam thực hiện quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa?","opts":["Học thuyết về giai cấp và đấu tranh giai cấp","Học thuyết hình thái kinh tế - xã hội","Lý luận về cách mạng xã hội","Tất cả các phương án trên đều sai"],"ans":1,"ex":"Cơ sở lý luận của con đường quá độ bỏ qua chế độ tư bản chủ nghĩa là **học thuyết hình thái kinh tế – xã hội**, với luận điểm sự phát triển xã hội là quá trình lịch sử – tự nhiên vừa có tính tuần tự, vừa có khả năng “bỏ qua” trong những điều kiện lịch sử nhất định. Học thuyết giai cấp hay cách mạng xã hội chỉ là những nội dung liên quan, không phải cơ sở trực tiếp."},{"id":"C3-042","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền cụm từ đúng vào chỗ trống: … là những tập đoàn to lớn gồm những người khác nhau về địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử, khác nhau về quan hệ của họ (thường thường thì những quan hệ này được pháp luật quy định và thừa nhận) đối với tư liệu sản xuất, về vai trò của họ trong tổ chức lao động xã hội và như vậy là khác nhau về cách thức hưởng thụ và về phần của cải xã hội ít hoặc nhiều mà họ được hưởng.","opts":["Giai tầng","Giai cấp","Tầng lớp","Cơ cấu xã hội"],"ans":1,"ex":"Đây là định nghĩa **giai cấp** của V.I.Lênin trong tác phẩm **“Sáng kiến vĩ đại”** (1919). Giai cấp là những tập đoàn người khác nhau về địa vị trong hệ thống sản xuất xã hội, về quan hệ với tư liệu sản xuất, về vai trò trong tổ chức lao động và về cách thức, quy mô hưởng thụ của cải xã hội. Tầng lớp, giai tầng hay cơ cấu xã hội là các khái niệm khác."},{"id":"C3-043","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự phân chia giai cấp trong xã hội bắt đầu từ hình thái kinh tế - xã hội nào?","opts":["Cộng sản nguyên thủy","Chiếm hữu nô lệ","Phong kiến","Tư bản chủ nghĩa"],"ans":1,"ex":"Giai cấp xuất hiện khi xã hội cộng sản nguyên thủy tan rã do lực lượng sản xuất phát triển, có của cải dư thừa và **chế độ tư hữu**. Xã hội **chiếm hữu nô lệ** là xã hội có giai cấp đầu tiên trong lịch sử, với hai giai cấp cơ bản là chủ nô và nô lệ. Trong cộng sản nguyên thủy chưa có giai cấp, phong kiến và tư bản là các xã hội có giai cấp ra đời sau."},{"id":"C3-044","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguyên nhân quyết định trực tiếp của sự ra đời giai cấp trong lịch sử xã hội là gì?","opts":["Do chiến tranh, thần linh, Thượng Đế tạo ra","Do sự chênh lệch về khả năng của các tập đoàn người","Do sự xuất hiện chế độ tư hữu về tư liệu sản xuất","Do sự phân hóa giữa giàu và nghèo trong xã hội"],"ans":2,"ex":"Nguyên nhân sâu xa của sự ra đời giai cấp là sự phát triển của lực lượng sản xuất tạo ra của cải dư thừa; còn nguyên nhân **trực tiếp** là sự xuất hiện **chế độ tư hữu về tư liệu sản xuất**. Phân hóa giàu nghèo chỉ là hệ quả của tư hữu; chiến tranh, thần linh hay chênh lệch khả năng là những cách giải thích phi khoa học."},{"id":"C3-045","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống: Thực chất ... là cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng.","opts":["Cải cách xã hội","Đảo chính","Đấu tranh giai cấp","Liên minh giai cấp"],"ans":2,"ex":"**Đấu tranh giai cấp**, về thực chất, là cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng. Nó bắt nguồn từ sự đối lập lợi ích kinh tế cơ bản. Cải cách, đảo chính hay liên minh giai cấp là những hiện tượng xã hội khác, không mang nội dung này."},{"id":"C3-046","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của V.I.Lênin, “Đấu tranh giai cấp” được hiểu theo nghĩa chung nhất là:","opts":["Là sự đấu tranh giữa giai cấp bị áp bức bóc lột với giai cấp áp bức bóc lột","Cuộc đấu tranh của nông dân chống lại bọn địa chủ phong kiến có đặc quyền, đặc lợi, bọn áp bức và bọn ăn bám","Là sự đấu tranh giữa giai cấp nô lệ với giai cấp chủ nô","Là sự đấu tranh xóa bỏ cái cũ, lỗi thời, lạc hậu"],"ans":0,"ex":"V.I.Lênin cho rằng đấu tranh giai cấp là “cuộc đấu tranh của quần chúng bị tước hết quyền, bị áp bức và lao động, chống bọn có đặc quyền đặc lợi, bọn áp bức và bọn ăn bám”. Theo nghĩa chung nhất, đó là đấu tranh giữa giai cấp **bị áp bức, bóc lột** với giai cấp **áp bức, bóc lột**. Các phương án nông dân – địa chủ, nô lệ – chủ nô chỉ là trường hợp cụ thể."},{"id":"C3-047","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là đặc trưng cơ bản của một giai cấp?","opts":["Giai cấp là những tập đoàn người có địa vị kinh tế - xã hội khác nhau trong một hệ thống sản xuất xã hội nhất định trong lịch sử.","Dấu hiệu chủ yếu quy đinh địa vị kinh tế-xã hội của các giai cấp là các mối quan hệ kinh tế - vật chất giữa các tập đoàn người trong phương thức sản xuất.","Thực chất của quan hệ giai cấp là quan hệ giữa bóc lột và bị bóc lột.","Giai cấp là những tập đoàn người khác nhau về sở thích, ngôn ngữ"],"ans":3,"ex":"Theo định nghĩa của Lênin, đặc trưng cơ bản của giai cấp là: khác nhau về **địa vị kinh tế – xã hội** trong hệ thống sản xuất; dấu hiệu chủ yếu quy định địa vị đó là **quan hệ kinh tế – vật chất**; thực chất quan hệ giai cấp là **bóc lột và bị bóc lột**. Sở thích, ngôn ngữ không phải tiêu chí phân chia giai cấp mà gần với đặc trưng của tộc người, nhóm xã hội."},{"id":"C3-048","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các đặc trưng của giai cấp liệt kê dưới đây, đặc trưng nào đóng vai trò quan trọng nhất, chi phối các đặc trưng còn lại?","opts":["Khác nhau về địa vị trong hệ thống tổ chức xã hội?","Tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác","Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội","Khác nhau về vai trò trong tổ chức xã hội"],"ans":2,"ex":"Trong các đặc trưng của giai cấp, **quan hệ sở hữu tư liệu sản xuất** là đặc trưng quan trọng nhất, chi phối các đặc trưng khác. Tập đoàn nào nắm tư liệu sản xuất chủ yếu thì có địa vị thống trị, giữ vai trò tổ chức, quản lý lao động, được hưởng phần của cải lớn hơn và có thể chiếm đoạt lao động của tập đoàn khác."},{"id":"C3-049","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Mâu thuẫn đối kháng giữa các giai cấp là do:","opts":["Sự khác nhau về tư tưởng, lối sống","Sự đối lập về lợi ích cơ bản – lợi ích kinh tế","Sự khác nhau giữa giàu và nghèo","Sự khác nhau về mức thu nhập"],"ans":1,"ex":"Mâu thuẫn đối kháng giai cấp bắt nguồn từ sự **đối lập về lợi ích cơ bản – lợi ích kinh tế**, mà gốc rễ là địa vị khác nhau đối với tư liệu sản xuất: một bên chiếm đoạt lao động, bên kia bị bóc lột. Khác biệt về tư tưởng, lối sống, giàu nghèo hay mức thu nhập chỉ là biểu hiện bên ngoài hoặc hệ quả của sự đối lập lợi ích kinh tế đó."},{"id":"C3-050","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, giai cấp nắm giữ quyền lực nhà nước là giai cấp nào?","opts":["Có tư tưởng cách mạng và tiên tiến nhất","Đại biểu cho ý chí của cộng đồng xã hội","Nắm giữ tư liệu sinh hoạt chủ yếu của xã hội","Nắm giữ tư liệu sản xuất chủ yếu của xã hội"],"ans":3,"ex":"Theo chủ nghĩa duy vật lịch sử, giai cấp nào **nắm giữ tư liệu sản xuất chủ yếu** của xã hội thì trở thành giai cấp thống trị về kinh tế, và do đó nắm quyền lực nhà nước, trở thành giai cấp thống trị về chính trị và tư tưởng. Tư liệu sinh hoạt không phải yếu tố quyết định; việc có tư tưởng tiến bộ cũng không đồng nghĩa với nắm chính quyền."},{"id":"C3-051","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vai trò của đấu tranh giai cấp trong lịch sử nhân loại:","opts":["Là động lực cơ bản của sự phát triển xã hội","Là một động lực trực tiếp, quan trọng của sự phát triển xã hội trong các xã hội có giai cấp","Thay thế các hình thái kinh tế - xã hội từ thấp đến cao","Lật đổ và thay đổi người cầm quyền"],"ans":1,"ex":"Trong xã hội có đối kháng giai cấp, **đấu tranh giai cấp** là một **động lực trực tiếp, quan trọng** của lịch sử, đỉnh cao là cách mạng xã hội dẫn tới thay thế hình thái kinh tế – xã hội. Còn động lực cơ bản, sâu xa của mọi xã hội là sự phát triển của lực lượng sản xuất. Phương án “lật đổ người cầm quyền” là hiểu hời hợt, không nói lên vai trò lịch sử của đấu tranh giai cấp."},{"id":"C3-052","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nội dung nào dưới đây không phải là vai trò của đấu tranh giai cấp trong xã hội có giai cấp?","opts":["Nhằm mục đích thay đổi người cầm quyền","Đấu tranh giai cấp là động lực trực tiếp, quan trọng của lịch sử.","Đấu tranh giai cấp là động lực để phát triển của xã hội có đối kháng giai cấp","Đấu tranh giai cấp có tác dụng cải tạo xã hội, xoá bỏ các lực lượng xã hội phản động và cải tạo bản thân các giai cấp cách mạng."],"ans":0,"ex":"Vai trò của đấu tranh giai cấp là **động lực trực tiếp, quan trọng** của sự phát triển xã hội có đối kháng giai cấp; nó **cải tạo xã hội**, xóa bỏ lực lượng phản động và cải tạo cả bản thân giai cấp cách mạng. Mục đích của đấu tranh giai cấp là thay đổi chế độ xã hội, quan hệ sản xuất, chứ không đơn thuần là **thay đổi người cầm quyền** – đó là đặc điểm của đảo chính."},{"id":"C3-053","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đấu tranh giai cấp trong thời kỳ quá độ từ chủ nghĩa tư bản lên chủ nghĩa xã hội bao gồm những nội dung nào?","opts":["Đấu tranh giai cấp diễn ra trong bối cảnh phức tạp","Không cần đấu tranh giai cấp, xã hội sẽ tự phát triển","Cuộc đấu tranh giai cấp của giai cấp vô sản diễn ra trong những điều kiện mới, với nội dung mới và có những hình thức mới","Tất cả các đáp án đều đúng"],"ans":2,"ex":"Sau khi giành chính quyền, giai cấp vô sản vẫn phải đấu tranh giai cấp nhưng trong **điều kiện mới** (đã nắm chính quyền), với **nội dung mới** (cải tạo xã hội cũ, xây dựng xã hội mới là chủ yếu) và **hình thức mới** (kết hợp bạo lực và hòa bình, giáo dục, hành chính, kinh tế). Quan điểm “không cần đấu tranh giai cấp” là sai, nên không thể chọn phương án tất cả."},{"id":"C3-054","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Cuộc đấu tranh giai cấp của giai cấp vô sản là:","opts":["Chống lại xã hội phong kiến, xã hội cũ","Nhằm mục đích cuối cùng là thiết lập quyền thống trị của giai cấp vô sản, cải tạo xã hội cũ, xây dựng thành công xã hội mới","Cuộc đấu tranh gay go, quyết liệt nhất nhằm thiết lập nền chuyên chính vô sản, cải tạo triệt để xã hội cũ, xoá bỏ mọi đối kháng giai cấp, xây dựng thành công xã hội cộng sản chủ nghĩa và đồng thời là cuộc đấu tranh giai cấp cuối cùng trong lịch sử","Nhằm thay đổi người cầm quyền"],"ans":2,"ex":"Đấu tranh giai cấp của giai cấp vô sản là cuộc đấu tranh **gay go, quyết liệt nhất**, nhằm thiết lập **chuyên chính vô sản**, cải tạo triệt để xã hội cũ, xóa bỏ mọi đối kháng giai cấp, xây dựng xã hội cộng sản chủ nghĩa, và là **cuộc đấu tranh giai cấp cuối cùng** trong lịch sử. Phương án C đầy đủ nhất; các phương án khác chỉ nêu một phần hoặc hiểu sai mục đích."},{"id":"C3-055","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, trong xã hội có giai cấp, giai cấp nào mới có thể làm cho hệ tư tưởng của nó trở thành hệ tư tưởng thống trị trong toàn xã hội?","opts":["Bất cứ giai cấp nào trong xã hội","Chỉ có đội ngũ trí thức","Chỉ có giai cấp nắm quyền sở hữu tư liệu sản xuất chủ yếu","Chỉ có giai cấp ưu tú trong xã hội"],"ans":2,"ex":"C.Mác và Ph.Ăngghen viết trong **Hệ tư tưởng Đức**: giai cấp nào là lực lượng vật chất thống trị thì cũng là lực lượng tinh thần thống trị. Vì vậy chỉ giai cấp **nắm quyền sở hữu tư liệu sản xuất chủ yếu** (và nắm nhà nước) mới có điều kiện biến hệ tư tưởng của mình thành hệ tư tưởng thống trị. Trí thức không phải là giai cấp độc lập về kinh tế."},{"id":"C3-056","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đáp án nào dưới đây là hình thức đấu tranh cao nhất, có ý nghĩa quyết định đến thắng lợi của giai cấp vô sản?","opts":["Đấu tranh kinh tế","Đấu tranh chính trị","Đấu tranh tư tưởng","Tất cả các đáp án đều sai"],"ans":1,"ex":"Đấu tranh giai cấp của giai cấp vô sản có ba hình thức cơ bản: kinh tế, chính trị, tư tưởng. **Đấu tranh chính trị** là hình thức **cao nhất**, có ý nghĩa quyết định, mà đỉnh cao là giành chính quyền nhà nước. Đấu tranh kinh tế chỉ đòi cải thiện điều kiện sống; đấu tranh tư tưởng chuẩn bị, hỗ trợ nhưng không trực tiếp giải quyết vấn đề quyền lực."},{"id":"C3-057","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhận định nào sau đây là SAI?","opts":["Giai cấp bị trị chịu ảnh hưởng tư tưởng của giai cấp thống trị.","Giai cấp thống trị không chịu ảnh hưởng tư tưởng của giai cấp bị trị.","Giai cấp bị trị có thể có hệ tư tưởng riêng của mình.","Giai cấp thống trị luôn tìm cách áp đặt hệ tư tưởng của mình cho các giai cấp khác."],"ans":1,"ex":"Ý thức giai cấp có tính độc lập tương đối và các hệ tư tưởng **tác động qua lại** lẫn nhau. Giai cấp thống trị áp đặt tư tưởng của mình, giai cấp bị trị chịu ảnh hưởng nhưng vẫn có thể có hệ tư tưởng riêng. Đồng thời, giai cấp thống trị **cũng chịu ảnh hưởng** tư tưởng của giai cấp bị trị. Vì vậy nhận định giai cấp thống trị không chịu ảnh hưởng là sai."},{"id":"C3-058","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nội dung của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là:","opts":["Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Là cuộc đấu tranh giữa các nhân tố thúc đẩy đất nước theo định hướng xã hội chủ nghĩa với các nhân tố tác động nhằm cản trở đất nước theo mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","Tất cả các đáp án trên"],"ans":3,"ex":"Đấu tranh giai cấp ở Việt Nam trong thời kỳ quá độ là cuộc đấu tranh giữa các nhân tố **thúc đẩy** đất nước theo định hướng xã hội chủ nghĩa với các nhân tố **cản trở** mục tiêu đó. Nội dung này gắn với việc thực hiện thắng lợi mục tiêu **độc lập dân tộc và chủ nghĩa xã hội**, xây dựng xã hội **dân giàu, nước mạnh, dân chủ, công bằng, văn minh**. Theo đáp án gốc, các phương án bổ sung cho nhau nên chọn tất cả."},{"id":"C3-059","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là nội dung chủ yếu của cuộc đấu tranh giai cấp ở Việt Nam hiện nay?","opts":["Sử dụng các hình thức kinh tế trung gian, quá độ trong đấu tranh giai cấp","Thực hiện thắng lợi sự nghiệp công nghiệp hoá, hiện đại hoá theo định hướng xã hội chủ nghĩa, khắc phục tình trạng nước kém phát triển","Thực hiện công bằng xã hội, chống áp bức, bất công; đấu tranh ngăn chặn và khắc phục những tư tưởng và hành động tiêu cực, sai trái","Đấu tranh làm thất bại mọi âm mưu và hành động chống phá của các thế lực thù địch và bảo vệ độc lập dân tộc, xây dựng thành công chủ nghĩa xã hội."],"ans":0,"ex":"Theo giáo trình, nội dung chủ yếu của đấu tranh giai cấp ở Việt Nam hiện nay gồm: thực hiện thắng lợi **công nghiệp hóa, hiện đại hóa** theo định hướng xã hội chủ nghĩa, khắc phục tình trạng kém phát triển; thực hiện **công bằng xã hội**, chống áp bức, bất công, khắc phục tiêu cực; **làm thất bại âm mưu chống phá** của thế lực thù địch. Việc dùng “hình thức kinh tế trung gian, quá độ” là hình thức của Lênin, không phải nội dung nêu trong giáo trình."},{"id":"C3-060","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Hình thức cộng đồng người nào hình thành khi xã hội bắt đầu có sự phân chia thành giai cấp?","opts":["Thị tộc","Bộ lạc","Bộ tộc","Dân tộc"],"ans":2,"ex":"Các hình thức cộng đồng người phát triển từ **thị tộc, bộ lạc** (thời nguyên thủy, gắn với quan hệ huyết thống, chưa có giai cấp) đến **bộ tộc** rồi **dân tộc**. **Bộ tộc** hình thành khi chế độ cộng sản nguyên thủy tan rã, xã hội bắt đầu phân chia giai cấp, quan hệ lãnh thổ dần thay thế quan hệ huyết thống. Dân tộc là hình thức phát triển cao hơn, ra đời muộn hơn."},{"id":"C3-061","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự hình thành dân tộc phổ biến trong lịch sử gắn với xã hội nào?","opts":["Xã hội phong kiến","Sự hình thành và phát triển của chủ nghĩa tư bản","Phong trào công nhân và cách mạng vô sản","Xã hội cổ đại"],"ans":1,"ex":"Về mặt phổ biến (nhất là ở châu Âu), **dân tộc** hình thành cùng với sự ra đời và phát triển của **chủ nghĩa tư bản**: kinh tế hàng hóa tư bản xóa bỏ tình trạng cát cứ phong kiến, tạo thị trường thống nhất, từ đó hình thành lãnh thổ, ngôn ngữ, văn hóa và nhà nước thống nhất. Ở phương Đông có trường hợp dân tộc hình thành sớm hơn, nhưng đó là đặc thù."},{"id":"C3-062","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống:… là một cộng đồng người ổn định được hình thành trong lịch sử trên cơ sở một lãnh thổ thống nhất, một ngôn ngữ thống nhất, một nền kinh tế thống nhất, một nền văn hóa và tâm lý, tính cách thống nhất, với một nhà nước và pháp luật thống nhất.","opts":["Thị tộc","Bộ lạc","Bộ tộc","Dân tộc"],"ans":3,"ex":"Đây là định nghĩa **dân tộc** (quốc gia dân tộc) với các đặc trưng: cộng đồng người ổn định, có **lãnh thổ** thống nhất, **ngôn ngữ** thống nhất, **nền kinh tế** thống nhất, **văn hóa, tâm lý, tính cách** thống nhất, cùng **nhà nước và pháp luật** thống nhất. Thị tộc, bộ lạc dựa trên huyết thống; bộ tộc chưa có sự thống nhất bền vững về kinh tế và nhà nước như dân tộc."},{"id":"C3-063","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đặc điểm hình thành Dân tộc ở Phương Tây:","opts":["Giống như các dân tộc ở Phương Đông","Gắn liền với sự hình thành và phát triển của chủ nghĩa tư bản","Ra đời từ thời kỳ nguyên thủy","Ra đời cùng với thời kỳ phong kiến"],"ans":1,"ex":"Ở **phương Tây**, dân tộc hình thành gắn với sự ra đời và phát triển của **chủ nghĩa tư bản**: thị trường dân tộc thống nhất thay thế sự phân tán phong kiến, giai cấp tư sản lãnh đạo việc thống nhất quốc gia. Điều này khác với phương Đông, nơi dân tộc có thể hình thành sớm hơn do nhu cầu chống ngoại xâm, trị thủy."},{"id":"C3-064","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đặc điểm hình thành Dân tộc ở Phương Đông:","opts":["Ra đời sớm hơn ở Phương Tây và không gắn với sự ra đời của chủ nghĩa tư bản","Ra đời giống như các dân tộc ở Phương Tây","Ra đời từ thời kỳ nguyên thủy","Ra đời cùng với sự hình thành và phát triển của chủ nghĩa tư bản"],"ans":0,"ex":"Ở nhiều nước **phương Đông** (trong đó có Việt Nam), dân tộc hình thành **sớm hơn** và **không gắn** với sự ra đời của chủ nghĩa tư bản, mà do yêu cầu đoàn kết chống ngoại xâm, chinh phục thiên nhiên (trị thủy, làm thủy lợi). Do đó quá trình hình thành dân tộc ở phương Đông khác phương Tây; nói dân tộc ra đời từ thời nguyên thủy là sai vì khi đó mới chỉ có thị tộc, bộ lạc."},{"id":"C3-065","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đặc điểm nào sau đây đóng vai trò quan trọng nhất, quy định đặc trưng của cộng đồng dân tộc?","opts":["Lãnh thổ và kinh tế","Kinh tế và văn hóa","Lãnh thổ và ngôn ngữ","Kinh tế và ngôn ngữ"],"ans":1,"ex":"Trong các đặc trưng của dân tộc, **kinh tế** là đặc trưng quan trọng nhất, tạo mối liên hệ gắn kết các bộ phận, là cơ sở vững chắc của cộng đồng dân tộc; còn **văn hóa** (cùng tâm lý, tính cách) là yếu tố quy định bản sắc riêng của mỗi dân tộc. Vì vậy theo đáp án gốc, kinh tế và văn hóa là cặp đặc trưng quan trọng nhất, quy định đặc trưng của cộng đồng dân tộc."},{"id":"C3-066","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn một phương án sai: Theo chủ nghĩa duy vật lịch sử, nhà nước…","opts":["Xuất hiện và tồn tại trong những xã hội có đối kháng giai cấp","Xuất hiện và tồn tại trong một giai đoạn phát triển nhất định của xã hội loài người","Ra đời cùng sự xuất hiện của con người","Là sản phẩm và biểu hiện của những mâu thuẫn đối kháng giai cấp không thể điều hòa được."],"ans":2,"ex":"Theo chủ nghĩa duy vật lịch sử, **nhà nước** là một phạm trù lịch sử: nó chỉ xuất hiện khi xã hội phân chia giai cấp, là sản phẩm và biểu hiện của mâu thuẫn giai cấp **không thể điều hòa**, và sẽ tiêu vong khi giai cấp mất đi. Trong xã hội cộng sản nguyên thủy chưa có nhà nước, vì vậy nói nhà nước ra đời cùng sự xuất hiện của con người là sai."},{"id":"C3-067","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Thứ tự sự phát triển các hình thức cộng đồng người trong lịch sử xã hội là?","opts":["Thị tộc - Bộ lạc - Bộ tộc – Dân tộc","Thị tộc – Bộ tộc – Bộ lạc – Dân tộc","Bộ lạc – Thị tộc – Bộ tộc – Dân tộc","Bộ lạc – Bộ tộc – Thị tộc – Dân tộc"],"ans":0,"ex":"Lịch sử cộng đồng người phát triển từ thấp đến cao: **thị tộc** (đơn vị cơ sở, dựa trên huyết thống) → **bộ lạc** (liên kết nhiều thị tộc) → **bộ tộc** (khi xã hội có giai cấp, quan hệ lãnh thổ thay thế huyết thống) → **dân tộc** (cộng đồng ổn định có kinh tế, lãnh thổ, văn hóa, nhà nước thống nhất). Các phương án khác đảo lộn trật tự này."},{"id":"C3-068","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là đặc trưng cơ bản của quốc gia dân tộc?","opts":["Là một cộng đồng người ổn định trên một lãnh thổ thống nhất","Là một cộng đồng người có cùng tính chất về mặt sinh học","Có ngôn ngữ, kinh tế và một nền văn hóa thống nhất","Là một cộng đồng người có một nhà nước và pháp luật thống nhất"],"ans":1,"ex":"Đặc trưng của quốc gia dân tộc gồm: cộng đồng người ổn định trên **lãnh thổ thống nhất**; có **ngôn ngữ, kinh tế, văn hóa** thống nhất; có **nhà nước và pháp luật** thống nhất. Dân tộc là cộng đồng xã hội – lịch sử, không phải cộng đồng chủng tộc, nên “có cùng tính chất sinh học” không phải là đặc trưng của dân tộc."},{"id":"C3-069","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đặc điểm dễ phân biệt nhất giữa quốc gia dân tộc và dân tộc tộc người là:","opts":["Dựa vào lãnh thổ và văn hóa","Dựa vào lãnh thổ và ngôn ngữ","Dựa vào lãnh thổ và kinh tế","Dựa vào lãnh thổ và nhà nước, pháp luật"],"ans":3,"ex":"**Quốc gia dân tộc** (như dân tộc Việt Nam) là cộng đồng chính trị – xã hội gắn với một **lãnh thổ quốc gia** có chủ quyền và một **nhà nước, pháp luật** thống nhất. **Dân tộc tộc người** (như Tày, Thái, Ê Đê...) chủ yếu được phân biệt bằng ngôn ngữ, văn hóa, ý thức tự giác tộc người, có thể cư trú xen kẽ và không có nhà nước riêng. Vì vậy lãnh thổ và nhà nước – pháp luật là dấu hiệu dễ phân biệt nhất."},{"id":"C3-070","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án SAI về mối quan hệ giữa giai cấp, dân tộc và nhân loại theo quan điểm của triết học Mác – Lênin.","opts":["Trong xã hội có giai cấp, lợi ích nhân loại không tách rời với lợi ích giai cấp, lợi ích dân tộc và bị chi phối bởi lợi ích giai cấp và dân tộc","Sự tồn tại của nhân loại là tiền đề, là điều kiện tất yếu thường xuyên của sự tồn tại dân tộc và giai cấp","Sự phát triển về mọi mặt của nhân loại tạo ra những điều kiện thuận lợi cho cuộc đấu tranh giải phóng dân tộc và giai cấp.","Nhân loại đứng trên giai cấp và dân tộc, còn giai cấp và dân tộc có mối quan hệ biện chứng tác động qua lại lẫn nhau"],"ans":3,"ex":"Trong mối quan hệ giai cấp – dân tộc – nhân loại, lợi ích nhân loại không tách rời và chịu sự chi phối của lợi ích giai cấp, dân tộc; sự tồn tại của nhân loại là tiền đề của dân tộc và giai cấp; sự phát triển của nhân loại tạo điều kiện cho giải phóng dân tộc, giai cấp. Ba yếu tố có quan hệ **biện chứng** với nhau; không có chuyện nhân loại “đứng trên” giai cấp và dân tộc."},{"id":"C3-071","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án SAI về mối quan hệ giữa giai cấp và dân tộc.","opts":["Giai cấp quyết định dân tộc nhưng đồng thời vấn đề dân tộc có ảnh hưởng lớn đến vấn đề giai cấp","Đấu tranh giải phóng dân tộc là điều kiện, tiền đề cho đấu tranh giải phóng giai cấp","Giai cấp và dân tộc có mối quan hệ biện chứng, tác động qua lại lẫn nhau","Giai cấp và dân tộc là những phạm trù chỉ các quan hệ xã hội khác nhau nên không có quan hệ với nhau"],"ans":3,"ex":"Giai cấp và dân tộc có quan hệ **biện chứng**: vấn đề giai cấp quyết định khuynh hướng phát triển và tính chất của vấn đề dân tộc, còn vấn đề dân tộc ảnh hưởng mạnh mẽ đến vấn đề giai cấp; giải phóng dân tộc là điều kiện, tiền đề để giải phóng giai cấp. Vì vậy nhận định giai cấp và dân tộc **không có quan hệ** với nhau là sai."},{"id":"C3-072","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Dân tộc Việt Nam được hình thành như thế nào?","opts":["Hình thành từ thời kỳ phong kiến gắn liền với các đời vua Hùng Vương","Hình thành từ thời kỳ nguyên thủy","Hình thành rất sớm gắn liền với quá trình đấu tranh chống ngoại xâm, cải tạo thiên nhiên, bảo vệ nền văn hoá dân tộc, bắt đầu từ khi nước Đại Việt giành độc lập.","Tất cả các đáp án trên đều chưa đúng"],"ans":2,"ex":"Dân tộc Việt Nam hình thành **rất sớm**, không đợi đến khi chủ nghĩa tư bản ra đời, gắn liền với yêu cầu **đấu tranh chống ngoại xâm**, **cải tạo thiên nhiên** (trị thủy) và bảo vệ văn hóa dân tộc. Theo đáp án gốc, mốc hình thành dân tộc được gắn với khi nước Đại Việt giành độc lập, tự chủ. Phương án “thời nguyên thủy” sai vì khi đó mới chỉ có thị tộc, bộ lạc."},{"id":"C3-073","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đối với cách mạng Việt Nam, Chủ tịch Hồ Chí Minh khẳng định: “cách mạng giải phóng dân tộc không phải là nhân tố bị động, phụ thuộc một chiều vào cách mạng vô sản ở các nước chính quốc; ngược lại, nếu đảng của giai cấp công nhân có đường lối đúng đắn, biết phát huy nhân tố bên trong và điều kiện quốc tế bên ngoài, nắm vững thời cơ thì cách mạng ở nước thuộc địa có thể thành công trước cách mạng ở chính quốc”. Đây là nhận định của Bác vận dụng sáng tạo mối quan hệ nào trong nội dung của triết học Mác – Lênin?","opts":["Mối quan hệ giữa giai cấp và dân tộc","Mối quan hệ giữa nhà nước và cách mạng","Mối quan hệ giữa tồn tại xã hội và ý thức xã hội","Mối quan hệ giữa vật chất và ý thức"],"ans":0,"ex":"Hồ Chí Minh đã vận dụng sáng tạo **mối quan hệ giữa giai cấp và dân tộc**: ở nước thuộc địa, giải phóng dân tộc là nhiệm vụ hàng đầu, gắn với giải phóng giai cấp, và cách mạng giải phóng dân tộc có tính chủ động, có thể thành công trước cách mạng vô sản ở chính quốc. Đây là bổ sung quan trọng cho lý luận Mác – Lênin về vấn đề dân tộc và thuộc địa."},{"id":"C3-074","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền cụm từ đúng vào chỗ trống sau: … là một tổ chức chính trị của một giai cấp thống trị về mặt kinh tế nhằm bảo vệ trật tự hiện hành và đàn áp sự phản kháng của các giai cấp khác.","opts":["Tôn giáo","Nhà nước","Hệ thống chính trị","Dân tộc"],"ans":1,"ex":"Theo quan điểm Mác – Lênin, **nhà nước** là tổ chức chính trị của giai cấp thống trị về kinh tế, nhằm bảo vệ trật tự hiện hành và đàn áp sự phản kháng của các giai cấp khác. Hệ thống chính trị rộng hơn (gồm cả đảng, đoàn thể); tôn giáo và dân tộc là những hiện tượng xã hội khác, không phải là bộ máy quyền lực cưỡng chế."},{"id":"C3-075","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguyên nhân sâu xa của sự xuất hiện nhà nước là:","opts":["Do sự phát triển của lực lượng sản xuất dẫn đến sự dư thừa tương đối của cải, xuất hiện chế độ tư hữu.","Do mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được.","Do sự phát triển tự nhiên của xã hội.","Do Thượng đế tạo ra."],"ans":0,"ex":"Nguyên nhân **sâu xa** của sự ra đời nhà nước là sự phát triển của **lực lượng sản xuất** dẫn tới dư thừa tương đối của cải, xuất hiện **chế độ tư hữu**, từ đó xã hội phân chia giai cấp. Còn mâu thuẫn giai cấp không thể điều hòa là nguyên nhân trực tiếp. Quan điểm Thượng đế tạo ra nhà nước là quan điểm thần học, duy tâm."},{"id":"C3-076","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguyên nhân trực tiếp của sự xuất hiện nhà nước là:","opts":["Do sự phát triển của lực lượng sản xuất dẫn đến sự dư thừa tương đối của cải, xuất hiện chế độ tư hữu","Do mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được","Do sự phát triển tự nhiên của xã hội","Do Thượng đế tạo ra"],"ans":1,"ex":"Nguyên nhân **trực tiếp** của sự xuất hiện nhà nước là **mâu thuẫn giai cấp gay gắt không thể điều hòa được**. V.I.Lênin viết trong **Nhà nước và cách mạng**: nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hòa được. Sự phát triển lực lượng sản xuất và chế độ tư hữu là nguyên nhân sâu xa, không phải trực tiếp."},{"id":"C3-077","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự ra đời và tồn tại của nhà nước là do:","opts":["Nguyện vọng của giai cấp thống trị","Nguyện vọng của mỗi quốc gia dân tộc","Tất yếu khách quan và do nguyên nhân kinh tế","Sự phát triển của xã hội"],"ans":2,"ex":"Nhà nước ra đời và tồn tại là **tất yếu khách quan**, có nguồn gốc từ **nguyên nhân kinh tế** (lực lượng sản xuất phát triển, chế độ tư hữu, phân chia giai cấp). Nó không xuất phát từ nguyện vọng chủ quan của giai cấp thống trị hay của quốc gia dân tộc. Phương án “sự phát triển của xã hội” quá chung chung, không nêu được bản chất kinh tế – giai cấp."},{"id":"C3-078","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo triết học Mác – Lênin, sự ra đời và tồn tại của nhà nước nhằm:","opts":["Điều hòa mâu thuẫn giai cấp","Giải quyết mâu thuẫn giai cấp","Bảo vệ lợi ích của mọi giai cấp trong xã hội","Bảo vệ trật tự xã hội theo ý chí và lợi ích của giai cấp thống trị kinh tế"],"ans":3,"ex":"Theo Mác – Lênin, nhà nước không phải công cụ **điều hòa** mâu thuẫn giai cấp, cũng không bảo vệ lợi ích của mọi giai cấp. Nhà nước ra đời để giữ cho xung đột giai cấp trong vòng **trật tự** có lợi cho **giai cấp thống trị về kinh tế**, bảo vệ ý chí và lợi ích của giai cấp đó. Mâu thuẫn giai cấp chỉ được giải quyết triệt để khi xóa bỏ chế độ người bóc lột người."},{"id":"C3-079","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo triết học Mác – Lênin, về bản chất, nhà nước là:","opts":["Của dân, do dân và vì dân","Bộ máy tập trung quyền lực của giai cấp nắm quyền thống trị về kinh tế","Chung của mọi giai cấp","Tất cả các phương án đều sai"],"ans":1,"ex":"Về bản chất, nhà nước là **bộ máy tập trung quyền lực** của giai cấp nắm quyền thống trị về kinh tế, là công cụ chuyên chính của giai cấp. Quan niệm nhà nước “chung của mọi giai cấp” là quan điểm phi giai cấp, đã bị Lênin phê phán. “Của dân, do dân, vì dân” chỉ là đặc trưng của nhà nước kiểu mới (xã hội chủ nghĩa), không phải bản chất chung của mọi nhà nước."},{"id":"C3-080","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đáp án nào sau đây nêu đúng nhất bản chất của nhà nước?","opts":["Là cơ quan quyền lực của giai cấp","Là bộ máy quản lý xã hội","Công cụ thống trị áp bức của giai cấp thống trị đối với toàn bộ xã hội, cơ quan trọng tài phân xử, hòa giải các xung đột xã hội","Cơ quan phúc lợi chung của toàn xã hội"],"ans":2,"ex":"Bản chất nhà nước là **công cụ thống trị, áp bức** của giai cấp thống trị đối với toàn xã hội. Đồng thời, như Ph.Ăngghen chỉ ra, nhà nước xuất hiện như một lực lượng “đứng trên” xã hội, có vai trò như **cơ quan trọng tài** giữ xung đột trong vòng trật tự – nhưng là trật tự có lợi cho giai cấp thống trị. Phương án C nêu cả hai mặt này nên được coi là đầy đủ nhất; các phương án khác phiến diện."},{"id":"C3-081","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo triết học Mác – Lênin, bộ máy tổ chức quyền lực và thực thi quyền lực đặc biệt của xã hội trong điều kiện xã hội có đối kháng giai cấp là:","opts":["Nhà nước","Giáo hội","Các đảng phái","Các đoàn thể xã hội"],"ans":0,"ex":"**Nhà nước** là bộ máy tổ chức quyền lực và thực thi **quyền lực đặc biệt** (quyền lực công cộng có tính cưỡng chế) trong xã hội có đối kháng giai cấp, với quân đội, cảnh sát, nhà tù, tòa án... Giáo hội, đảng phái, đoàn thể đều là thiết chế của kiến trúc thượng tầng nhưng không có quyền lực cưỡng chế chung đối với mọi thành viên xã hội."},{"id":"C3-082","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đặc trưng cơ bản của nhà nước theo quan điểm của chủ nghĩa duy vật lịch sử là:","opts":["Quản lý cư dân trên một vùng lãnh thổ nhất định","Có hệ thống các cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế đối với mọi thành viên","Có hệ thống thuế khóa để nuôi bộ máy chính quyền","Tất cả các đáp án trên"],"ans":3,"ex":"Nhà nước có ba đặc trưng cơ bản: **quản lý cư dân trên một vùng lãnh thổ** nhất định (khác với tổ chức thị tộc theo huyết thống); có **hệ thống cơ quan quyền lực chuyên nghiệp** mang tính cưỡng chế (quân đội, cảnh sát, tòa án...); có **hệ thống thuế khóa** để nuôi bộ máy chính quyền. Ba đặc trưng này đều đúng."},{"id":"C3-083","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất: Các chức năng cơ bản của nhà nước là:","opts":["Chức năng thống trị chính trị giai cấp (trấn áp bạo lực, chức năng giai cấp) và chức năng xã hội (tổ chức xây dựng); chức năng đối nội và chức năng đối ngoại.","Chức năng đối nội và chức năng đối ngoại; chức năng kinh tế.","Chức năng thống trị xã hội và chức năng xã hội; chức năng giáo dục.","Tất cả các đáp án trên đều sai."],"ans":0,"ex":"Giáo trình nêu các chức năng cơ bản của nhà nước theo hai cách phân loại: xét theo tính chất quyền lực có **chức năng thống trị chính trị giai cấp** (trấn áp bạo lực) và **chức năng xã hội** (tổ chức xây dựng); xét theo phạm vi tác động có **chức năng đối nội** và **chức năng đối ngoại**. Phương án A đầy đủ và chính xác nhất."},{"id":"C3-084","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn một đáp án không phải là nội dung thuộc chức năng thống trị chính trị giai cấp của nhà nước?","opts":["Chịu sự quy định bởi tính giai cấp của nhà nước","Làm công cụ chuyên chính của giai cấp thống trị","Bảo vệ sự thống trị của giai cấp thống trị","Thực hiện các mối quan hệ với các nước trên thế giới"],"ans":3,"ex":"**Chức năng thống trị chính trị giai cấp** chịu sự quy định bởi tính giai cấp của nhà nước, biến nhà nước thành công cụ chuyên chính, bảo vệ sự thống trị và lợi ích của giai cấp thống trị. Còn **thực hiện quan hệ với các nước trên thế giới** là nội dung của **chức năng đối ngoại**, phân loại theo phạm vi tác động, nên không thuộc chức năng thống trị chính trị."},{"id":"C3-085","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn một đáp án không phải là nội dung thuộc chức năng xã hội của nhà nước?","opts":["Quản lý, điều hành những hoạt động chung vì sự tồn tại của xã hội","Thỏa mãn một số nhu cầu chung của cộng đồng dân cư","Làm công cụ chuyên chính của giai cấp thống trị","Nhà nước nhân danh xã hội làm nhiệm vụ quản lý nhà nước về xã hội"],"ans":2,"ex":"**Chức năng xã hội** của nhà nước là nhân danh xã hội quản lý, điều hành những hoạt động chung vì sự tồn tại của xã hội và thỏa mãn một số nhu cầu chung của cộng đồng (thủy lợi, giao thông, y tế, giáo dục...). Còn **làm công cụ chuyên chính** của giai cấp thống trị là nội dung của **chức năng thống trị chính trị giai cấp**."},{"id":"C3-086","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn một đáp án không phải là nội dung thuộc chức năng đối nội của nhà nước?","opts":["Thực hiện đường lối đối nội nhằm duy trì trật tự xã hội","Xác lập vị trí chính thống những tư tưởng, ý chí của giai cấp thống trị","Quản lý các hoạt động kinh tế, chính trị, xã hội… bằng pháp luật","Thực hiện các mối quan hệ với các nước trên thế giới"],"ans":3,"ex":"**Chức năng đối nội** là việc thực hiện đường lối đối nội nhằm duy trì trật tự xã hội, quản lý các hoạt động kinh tế, chính trị, xã hội bằng pháp luật, xác lập vị trí chính thống cho tư tưởng của giai cấp thống trị. Còn **quan hệ với các nước trên thế giới** thuộc về **chức năng đối ngoại**, nên không phải nội dung đối nội."},{"id":"C3-087","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn một đáp án không phải là nội dung thuộc chức năng đối ngoại của nhà nước?","opts":["Chịu sự quy định bởi tính giai cấp của nhà nước","Đáp ứng nhu cầu giao lưu, trao đổi về kinh tế, văn hóa, khoa học kỹ thuật, y tế, giáo dục… với các nước trong khu vực và thế giới.","Bảo vệ lãnh thổ quốc gia","Thực hiện các mối quan hệ với các nước trên thế giới"],"ans":0,"ex":"**Chức năng đối ngoại** bao gồm: thực hiện quan hệ với các nước; đáp ứng nhu cầu giao lưu kinh tế, văn hóa, khoa học, giáo dục...; **bảo vệ lãnh thổ quốc gia**. Theo cách trình bày của giáo trình, “chịu sự quy định bởi tính giai cấp của nhà nước” được nêu như nội dung của **chức năng thống trị chính trị giai cấp**, nên đáp án gốc xem đó không phải nội dung riêng của chức năng đối ngoại."},{"id":"C3-088","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tìm đáp án sai: Theo chủ nghĩa duy vật lịch sử, mối quan hệ giữa chức năng thống trị chính trị của giai cấp và chức năng xã hội của nhà nước là?","opts":["Chức năng thống trị chính trị của giai cấp thống trị giữ địa vị quyết định, chi phối và định hướng chức năng xã hội của nhà nước.","Chức năng xã hội của nhà nước có vai trò rất quan trọng đối với sự duy trì trật tự xã hội. Nếu chính quyền nhà nước nào không chú ý tới chức năng xã hội thì sẽ nhanh chóng đi tới sự sụp đổ.","Chức năng thống trị chính trị của giai cấp và chức năng xã hội của nhà nước chỉ có mối quan hệ bề ngoài, không bản chất","Chức năng thống trị chính trị và chức năng xã hội của nhà nước luôn có mối quan hệ biện chứng, tác động hữu cơ với nhau."],"ans":2,"ex":"Chức năng thống trị chính trị và chức năng xã hội có quan hệ **biện chứng, hữu cơ**: chức năng thống trị chính trị giữ vai trò **quyết định, chi phối**, định hướng chức năng xã hội; còn chức năng xã hội là cơ sở để duy trì sự thống trị, nhà nước nào xem nhẹ nó sẽ nhanh chóng sụp đổ. Vì vậy cho rằng hai chức năng chỉ có quan hệ **bề ngoài, không bản chất** là sai."},{"id":"C3-089","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đáp án nào không phải là đặc trưng cơ bản của nhà nước theo quan điểm của chủ nghĩa duy vật lịch sử?","opts":["Quản lý cư dân trên một vùng lãnh thổ nhất định","Đảm bảo lợi ích cho toàn thể các giai cấp và tầng lớp trong xã hội","Có hệ thống các cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế đối với mọi thành viên","Có hệ thống thuế khóa để nuôi bộ máy chính quyền"],"ans":1,"ex":"Ba đặc trưng cơ bản của nhà nước là: quản lý cư dân trên lãnh thổ nhất định; có hệ thống cơ quan quyền lực chuyên nghiệp mang tính cưỡng chế; có hệ thống thuế khóa. Quan niệm nhà nước **đảm bảo lợi ích cho toàn thể các giai cấp** trái với bản chất giai cấp của nhà nước, vì nhà nước trước hết bảo vệ lợi ích của giai cấp thống trị."},{"id":"C3-090","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Thứ tự các kiểu nhà nước tồn tại trong lịch sử xã hội:","opts":["Nhà nước phong kiến, nhà nước chủ nô, nhà nước tư bản, nhà nước vô sản","Nhà nước vô sản, nhà nước phong kiến, nhà nước chủ nô, nhà nước tư bản","Nhà nước chủ nô, nhà nước phong kiến, nhà nước tư bản, nhà nước vô sản","Nhà nước chủ nô, nhà nước phong kiến, nhà nước vô sản, nhà nước tư sản"],"ans":2,"ex":"Tương ứng với các hình thái kinh tế – xã hội có giai cấp, lịch sử có bốn **kiểu nhà nước** theo thứ tự: **nhà nước chủ nô** (chiếm hữu nô lệ), **nhà nước phong kiến**, **nhà nước tư sản**, và **nhà nước vô sản** (xã hội chủ nghĩa). Kiểu nhà nước do bản chất giai cấp và cơ sở kinh tế quyết định, nên trật tự này trùng với trật tự các hình thái kinh tế – xã hội."},{"id":"C3-091","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các kiểu nhà nước sau, nhà nước nào khác về bản chất so với các kiểu nhà nước còn lại?","opts":["Nhà nước chiếm hữu nô lệ","Nhà nước phong kiến","Nhà nước tư bản","Nhà nước vô sản"],"ans":3,"ex":"Nhà nước chủ nô, phong kiến và tư sản đều là nhà nước của **thiểu số bóc lột** thống trị đa số, dựa trên chế độ tư hữu về tư liệu sản xuất. **Nhà nước vô sản** khác về bản chất: là nhà nước của đa số nhân dân lao động, dựa trên chế độ công hữu, nhằm xóa bỏ áp bức, bóc lột, tiến tới xã hội không còn giai cấp."},{"id":"C3-092","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các kiểu nhà nước sau, nhà nước nào được coi là nhà nước đặc biệt, nhà nước nửa nhà nước, nhà nước không còn nguyên nghĩa?","opts":["Nhà nước chiếm hữu nô lệ","Nhà nước vô sản","Nhà nước phong kiến","Nhà nước tư bản"],"ans":1,"ex":"V.I.Lênin gọi **nhà nước vô sản** là nhà nước kiểu mới, nhà nước **“nửa nhà nước”**, **“không còn nguyên nghĩa”**, vì nó là công cụ của đa số trấn áp thiểu số bóc lột, chức năng tổ chức xây dựng là chủ yếu, và nó có xu hướng **tự tiêu vong** khi giai cấp không còn. Các nhà nước chủ nô, phong kiến, tư sản là nhà nước theo đúng nghĩa của thiểu số bóc lột."},{"id":"C3-093","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nền chuyên chính vô sản (nhà nước vô sản) có chức năng cơ bản là:","opts":["Chống lại giai cấp phong kiến và chế độ cũ.","Xây dựng một trật tự xã hội mới, thủ tiêu chế độ người áp bức bóc lột người, đập tan sự phản kháng của các thế lực phản động đã bị đánh đổ nhưng chưa bị tiêu diệt vẫn ngoan cố chống lại chính quyền do giai cấp vô sản lãnh đạo.","Thực hiện trấn áp bạo lực với các giai cấp, tầng lớp khác trong xã hội.","Chỉ thực hiện chức năng tổ chức xây dựng mà không cần thực hiện chức năng thống trị chính trị giai cấp."],"ans":1,"ex":"Chuyên chính vô sản có hai chức năng gắn bó với nhau: **tổ chức xây dựng** trật tự xã hội mới, thủ tiêu chế độ người áp bức bóc lột người (chức năng cơ bản, chủ yếu), và **trấn áp** sự phản kháng của thế lực phản động đã bị đánh đổ nhưng chưa bị tiêu diệt. Phương án B đầy đủ nhất. Phương án D sai vì bỏ chức năng trấn áp; phương án C sai vì trấn áp mọi giai cấp, tầng lớp."},{"id":"C3-094","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất: Thực chất của nhà nước vô sản là:","opts":["Nhà nước do giai cấp nông dân và tầng lớp trí thức nắm quyền, lãnh đạo.","Nhà nước do giai cấp vô sản nắm quyền, lãnh đạo.","Nhà nước do giai cấp vô sản lãnh đạo, liên minh với giai cấp nông dân, tầng lớp trí thức tiến bộ, và các tầng lớp nhân dân lao động khác đại diện và bảo vệ quyền lợi của giai cấp và của toàn thể nhân dân lao động.","Nhà nước do tầng lớp trí thức nắm quyền, lãnh đạo."],"ans":2,"ex":"Thực chất của **nhà nước vô sản** là nhà nước do **giai cấp vô sản (công nhân) lãnh đạo**, dựa trên **liên minh** với giai cấp nông dân, tầng lớp trí thức và nhân dân lao động, đại diện và bảo vệ lợi ích của toàn thể nhân dân lao động. Phương án chỉ nói giai cấp vô sản nắm quyền là chưa đầy đủ; nông dân hay trí thức không giữ vai trò lãnh đạo."},{"id":"C3-095","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, mối quan hệ giữa chức năng đối nội và chức năng đối ngoại của nhà nước là:","opts":["Là hai mặt của một thực thể thống nhất, hỗ trợ và tác động lẫn nhau nhằm thực hiện đường lối đối nội và đường lối đối ngoại của giai cấp thống trị","Chức năng đối nội và chức năng đối ngoại chỉ có mối quan hệ bề ngoài, không bản chất","Chức năng đối ngoại quan trọng hơn và giữ vai trò chủ yếu","Tất cả các đáp án trên đều không đúng"],"ans":0,"ex":"**Chức năng đối nội** và **chức năng đối ngoại** là hai mặt của một thực thể thống nhất, hỗ trợ và tác động lẫn nhau nhằm thực hiện đường lối của giai cấp thống trị. Trong đó chức năng đối nội giữ vai trò quyết định, chức năng đối ngoại phải phục vụ đối nội. Vì vậy cho rằng chúng chỉ có quan hệ bề ngoài, hoặc đối ngoại quan trọng hơn, đều sai."},{"id":"C3-096","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Hiện nay, Đảng ta chủ trương xây dựng Nhà nước Việt Nam phát triển theo hướng nào?","opts":["Nhà nước tư sản","Nhà nước pháp quyền","Nhà nước pháp quyền xã hội chủ nghĩa","Nhà nước quân chủ"],"ans":2,"ex":"Đảng Cộng sản Việt Nam chủ trương xây dựng **Nhà nước pháp quyền xã hội chủ nghĩa** của nhân dân, do nhân dân, vì nhân dân, do Đảng lãnh đạo, quản lý xã hội bằng pháp luật. Phương án “nhà nước pháp quyền” chưa đủ vì chưa thể hiện bản chất xã hội chủ nghĩa; nhà nước tư sản hay quân chủ trái với con đường đi lên chủ nghĩa xã hội."},{"id":"C3-097","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhà nước Việt Nam thuộc hình thức nào trong các hình thức nhà nước liệt kê sau đây?","opts":["Cộng hòa dân chủ","Cộng hòa dân chủ nhân dân","Xô Viết","Cộng hòa đại nghị"],"ans":1,"ex":"Nhà nước vô sản có nhiều hình thức trong lịch sử: Công xã Pari, nhà nước **Xô viết**, nhà nước **dân chủ nhân dân**. Nhà nước Việt Nam (từ Việt Nam Dân chủ Cộng hòa đến Cộng hòa xã hội chủ nghĩa Việt Nam) thuộc hình thức **cộng hòa dân chủ nhân dân**. Cộng hòa đại nghị là hình thức của nhà nước tư sản; Xô viết là hình thức ở Liên Xô."},{"id":"C3-098","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Bộ máy cai trị của nhà nước bao gồm:","opts":["Lực lượng vũ trang chuyên nghiệp và bộ máy hành chính","Bộ máy hành chính và pháp luật của nó","Quân đội, cảnh sát, tòa án","Lực lượng vũ trang chuyên nghiệp và hệ thống pháp luật"],"ans":0,"ex":"Bộ máy cai trị của nhà nước gồm **lực lượng vũ trang chuyên nghiệp** (quân đội, cảnh sát, nhà tù...) và **bộ máy hành chính** (quan lại, công chức). Đây là yếu tố vật chất tạo nên quyền lực cưỡng chế của nhà nước. Pháp luật là công cụ, phương tiện quản lý chứ không phải bộ phận của bộ máy cai trị; phương án C chỉ liệt kê một phần."},{"id":"C3-099","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất điền vào chỗ trống: Theo nghĩa rộng, … là sự biến đổi có tính chất bước ngoặt và căn bản về chất trong mọi lĩnh vực đời sống xã hội, là phương thức thay thế hình thái kinh tế xã hội này bằng hình thái kinh tế - xã hội cao hơn.","opts":["Cách mạng khoa học và công nghệ","Cách mạng xã hội","Đấu tranh giai cấp","Tất cả các phương án trên đều sai"],"ans":1,"ex":"Theo **nghĩa rộng**, **cách mạng xã hội** là sự biến đổi có tính bước ngoặt, căn bản về chất trong toàn bộ các lĩnh vực đời sống xã hội, là phương thức chuyển từ hình thái kinh tế – xã hội thấp lên hình thái cao hơn. Cách mạng khoa học – công nghệ chỉ là biến đổi trong lực lượng sản xuất; đấu tranh giai cấp là động lực, không phải phương thức thay thế hình thái."},{"id":"C3-100","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất điền vào chỗ trống: Theo nghĩa hẹp, … là việc lật đổ một chế độ chính trị đã lỗi thời và thiết lập một chế độ chính trị tiến bộ hơn của giai cấp cách mạng.","opts":["Cách mạng xã hội","Cách mạng khoa học và công nghệ","Đấu tranh giai cấp","Tất cả các phương án trên đều sai"],"ans":0,"ex":"Theo **nghĩa hẹp**, **cách mạng xã hội** là việc lật đổ một chế độ chính trị đã lỗi thời, thiết lập chế độ chính trị tiến bộ hơn của giai cấp cách mạng. Vấn đề cơ bản của mọi cuộc cách mạng là vấn đề **chính quyền nhà nước**. Đây là khâu then chốt, mở đường cho các biến đổi căn bản về kinh tế, xã hội theo nghĩa rộng."},{"id":"C3-101","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguồn gốc sâu xa của cách mạng xã hội là do:","opts":["Mâu thuẫn giữa sự tiến bộ của lực lượng sản xuất với tính ổn định, lạc hậu của quan hệ sản xuất.","Mâu thuẫn giai cấp và đấu tranh giai cấp","Tự thân xã hội phát triển","Do Thượng Đế sắp đặt"],"ans":0,"ex":"Nguồn gốc **sâu xa** của cách mạng xã hội là **mâu thuẫn giữa lực lượng sản xuất tiến bộ với quan hệ sản xuất lỗi thời, lạc hậu**. Khi quan hệ sản xuất trở thành xiềng xích kìm hãm lực lượng sản xuất, như C.Mác nói trong **Góp phần phê phán khoa kinh tế chính trị** (1859), thì “bắt đầu thời đại một cuộc cách mạng xã hội”. Mâu thuẫn và đấu tranh giai cấp chỉ là nguồn gốc trực tiếp."},{"id":"C3-102","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguồn gốc trực tiếp của cách mạng xã hội là do:","opts":["Mâu thuẫn giữa sự tiến bộ của lực lượng sản xuất với tính ổn định, lạc hậu của quan hệ sản xuất.","Mâu thuẫn giữa giai cấp thống trị và giai cấp bị thống trị trong xã hội, do đấu tranh giai cấp.","Tự thân xã hội phát triển","Do Thượng Đế sắp đặt"],"ans":1,"ex":"Mâu thuẫn kinh tế giữa lực lượng sản xuất và quan hệ sản xuất biểu hiện về mặt xã hội thành **mâu thuẫn giữa giai cấp thống trị và giai cấp bị trị**. Khi mâu thuẫn này gay gắt, **đấu tranh giai cấp** lên tới đỉnh cao sẽ dẫn tới cách mạng xã hội. Vì vậy đây là nguồn gốc **trực tiếp**, còn mâu thuẫn lực lượng sản xuất – quan hệ sản xuất là nguồn gốc sâu xa."},{"id":"C3-103","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất điền vào chỗ trống: … là quá trình phát triển diễn ra một cách tuần tự, dần dần từng bộ phận, từng lĩnh vực của đời sống xã hội.","opts":["Cách mạng xã hội","Cải cách xã hội","Tiến hóa xã hội","Đảo chính"],"ans":2,"ex":"**Tiến hóa xã hội** là quá trình phát triển diễn ra **tuần tự, dần dần**, từng bộ phận, từng lĩnh vực của đời sống xã hội; đó là quá trình tích lũy về lượng. Khác với cách mạng xã hội (biến đổi căn bản về chất), cải cách (thay đổi bộ phận có chủ đích) hay đảo chính (giành quyền lực nhà nước nhưng không đổi bản chất chế độ)."},{"id":"C3-104","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất điền vào chỗ trống: … chỉ tạo nên những thay đổi bộ phận, lĩnh vực riêng lẻ của đời sống xã hội.","opts":["Cách mạng xã hội","Cải cách xã hội","Tiến hóa xã hội","Đảo chính"],"ans":1,"ex":"**Cải cách xã hội** là những cải biến từng mặt, từng lĩnh vực của đời sống xã hội, chỉ tạo nên **thay đổi bộ phận**, riêng lẻ mà không làm thay đổi căn bản bản chất của chế độ. Cải cách có thể là một bộ phận của tiến hóa hoặc của cách mạng xã hội. Khác với cách mạng xã hội là biến đổi toàn diện, căn bản về chất."},{"id":"C3-105","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất điền vào chỗ trống: … là thủ đoạn giành quyền lực nhà nước bởi một cá nhân hoặc một nhóm người nhằm xác lập một chế độ xã hội có cùng bản chất.","opts":["Cách mạng xã hội","Cải cách xã hội","Tiến hóa xã hội","Đảo chính"],"ans":3,"ex":"**Đảo chính** là thủ đoạn giành quyền lực nhà nước bởi một cá nhân hay một nhóm người nhằm thiết lập chế độ chính trị có **cùng bản chất**, tức chỉ thay đổi người cầm quyền mà không thay đổi chế độ xã hội. Do đó đảo chính khác về căn bản với **cách mạng xã hội**, vốn thay thế chế độ cũ bằng chế độ xã hội mới tiến bộ hơn."},{"id":"C3-106","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Lực lượng cách mạng xã hội là:","opts":["Tất cả các giai cấp, tầng lớp tồn tại trong xã hội.","Những giai cấp, tầng lớp người có lợi ích ít nhiều gắn bó với cách mạng, tham gia vào các phong trào cách mạng đang thực hiện mục đích của cách mạng.","Đáp án A và B đều đúng","Đáp án A và B đều sai"],"ans":1,"ex":"**Lực lượng cách mạng** là những giai cấp, tầng lớp có lợi ích **ít nhiều gắn bó** với cách mạng, tham gia các phong trào cách mạng nhằm thực hiện mục đích của cách mạng. Không phải mọi giai cấp, tầng lớp đều là lực lượng cách mạng, vì có những giai cấp là **đối tượng** cách mạng cần đánh đổ."},{"id":"C3-107","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo triết học Mác – Lênin, động lực cách mạng là:","opts":["Những giai cấp và những lực lượng đối lập cần phải đánh đổ của cách mạng.","Những giai cấp có lợi ích gắn bó chặt chẽ và lâu dài đối với cách mạng, có tính tự giác, tích cực, chủ động, kiên quyết, triệt để cách mạng, có khả năng lôi cuốn, tập hợp các giai cấp, tầng lớp khác tham gia phong trào cách mạng.","Giai cấp có hệ tư tưởng tiến bộ, đại diện cho xu hướng phát triển của xã hội, cho phương thức sản xuất tiến bộ.","Tất cả các đáp án trên đều đúng"],"ans":1,"ex":"**Động lực cách mạng** là những giai cấp có lợi ích **gắn bó chặt chẽ, lâu dài** với cách mạng, có tính tự giác, tích cực, kiên quyết, triệt để cách mạng, có khả năng lôi cuốn, tập hợp các giai cấp, tầng lớp khác. Cần phân biệt với **đối tượng cách mạng** (lực lượng cần đánh đổ – phương án A) và với **giai cấp lãnh đạo** cách mạng (đại diện phương thức sản xuất tiến bộ – phương án C)."},{"id":"C3-108","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo triết học Mác – Lênin, đối tượng của cách mạng xã hội là:","opts":["Những giai cấp và những lực lượng đối lập cần phải đánh đổ của cách mạng.","Những giai cấp có lợi ích gắn bó chặt chẽ và lâu dài đối với cách mạng, có tính tự giác, tích cực, chủ động, kiên quyết, triệt để cách mạng, có khả năng lôi cuốn, tập hợp các giai cấp, tầng lớp khác tham gia phong trào cách mạng.","Giai cấp có hệ tư tưởng tiến bộ, đại diện cho xu hướng phát triển của xã hội, cho phương thức sản xuất tiến bộ.","Tất cả các đáp án trên đều đúng"],"ans":0,"ex":"Trong cách mạng xã hội cần phân biệt **đối tượng**, **lực lượng** và **động lực** cách mạng. Đối tượng là những giai cấp, lực lượng phản động, đại diện cho phương thức sản xuất lỗi thời mà cách mạng phải đánh đổ. Phương án B mô tả **động lực cách mạng**, còn C mô tả **giai cấp lãnh đạo** cách mạng, nên không thể chọn D."},{"id":"C3-109","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tính chất của cách mạng xã hội được xác định bởi:","opts":["Mâu thuẫn cơ bản và nhiệm vụ giải quyết mâu thuẫn kinh tế với mâu thuẫn chính trị xã hội tương ứng.","Giai cấp cầm quyền xác định","Thượng đế, thần linh","Sự phát triển tự nhiên của xã hội"],"ans":0,"ex":"**Tính chất** của một cuộc cách mạng xã hội do **mâu thuẫn cơ bản** cần giải quyết quy định: mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất và các mâu thuẫn chính trị – xã hội tương ứng, cùng nhiệm vụ giải quyết chúng. Chẳng hạn, cách mạng tư sản giải quyết mâu thuẫn với quan hệ sản xuất phong kiến. Tính chất không do giai cấp cầm quyền, thần linh hay sự phát triển tự phát quyết định."},{"id":"C3-110","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điều kiện khách quan để cách mạng xã hội diễn ra là:","opts":["Năng lực tổ chức thực hiện nhiệm vụ cách mạng, khả năng tập hợp lực lượng cách mạng của giai cấp lãnh đạo cách mạng.","Thời điểm đặc biệt khi điều kiện khách quan và nhân tố chủ quan của cách mạng xã hội đã chín muồi, đó là lúc thuận lợi nhất có thể bùng nổ cách mạng, có ý nghĩa quyết định đối với thành công của cách mạng.","Điều kiện, hoàn cảnh kinh tế - xã hội, chính trị bên ngoài tác động đến, là tiền đề diễn ra các cuộc cách mạng xã hội.","Khi ý chí, niềm tin, trình độ giác ngộ và nhận thức của lực lượng cách mạng một lòng hướng vào thực hiện mục tiêu và nhiệm vụ cách mạng."],"ans":2,"ex":"Cách mạng xã hội chỉ nổ ra khi có đủ **điều kiện khách quan** và **nhân tố chủ quan**. Điều kiện khách quan là hoàn cảnh kinh tế – xã hội, chính trị khách quan làm tiền đề cho cách mạng, đỉnh cao là **tình thế cách mạng**. Các phương án A và D thuộc nhân tố chủ quan; B mô tả **thời cơ cách mạng**, tức lúc cả hai mặt đã chín muồi."},{"id":"C3-111","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu không phải là điều kiện chủ quan để cách mạng xã hội diễn ra?","opts":["Năng lực tổ chức thực hiện nhiệm vụ cách mạng, khả năng tập hợp lực lượng cách mạng của giai cấp lãnh đạo cách mạng đã đạt đến độ chin muồi.","Khi ý chí, niềm tin, trình độ giác ngộ và nhận thức của lực lượng cách mạng một lòng hướng vào thực hiện mục tiêu và nhiệm vụ cách mạng.","Lực lượng và những yếu tố của xã hội cũ đang suy yếu","Tất cả các đáp án nêu trên"],"ans":2,"ex":"**Nhân tố chủ quan** gồm năng lực tổ chức, khả năng tập hợp lực lượng của giai cấp lãnh đạo; ý chí, niềm tin, trình độ giác ngộ của lực lượng cách mạng. Sự suy yếu của lực lượng và các yếu tố của xã hội cũ là biểu hiện của **điều kiện khách quan** (tình thế cách mạng: giai cấp thống trị không thể duy trì thống trị như cũ). Vì vậy C không phải điều kiện chủ quan."},{"id":"C3-112","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Các phương pháp cách mạng được sử dụng trong cách mạng xã hội là:","opts":["Diễn biến hòa bình","Đảo chính","Bạo lực cách mạng và phương pháp hòa bình","Tự diễn biến, tự chuyển hóa"],"ans":2,"ex":"Theo chủ nghĩa Mác – Lênin, cách mạng xã hội có hai phương pháp cơ bản: **bạo lực cách mạng** (khởi nghĩa vũ trang, chiến tranh cách mạng...) và **phương pháp hòa bình** khi có điều kiện. Việc lựa chọn tùy tương quan lực lượng và hoàn cảnh cụ thể. Diễn biến hòa bình, tự diễn biến, tự chuyển hóa là các âm mưu chống phá; đảo chính chỉ là thay đổi nhóm cầm quyền, không phải cách mạng xã hội."},{"id":"C3-113","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tại sao sử dụng phương pháp bạo lực cách mạng được coi là tất yếu trong xã hội có đối kháng giai cấp?","opts":["Vì có lợi, ít gây đau khổ cho con người","Vì giai cấp thống trị lỗi thời không bao giờ tự nguyện từ bỏ địa vị thống trị của mình.","Vì có lợi cho giai cấp cầm quyền đàn áp giai cấp bị thống trị","Tất cả các đáp án trên đều sai"],"ans":1,"ex":"Bạo lực cách mạng là tất yếu vì **giai cấp thống trị lỗi thời không bao giờ tự nguyện rời bỏ địa vị** và luôn dùng bộ máy nhà nước để đàn áp. Ph. Ăngghen ví bạo lực là **\"bà đỡ\"** của mọi xã hội cũ đang thai nghén xã hội mới. Bạo lực cách mạng là bạo lực của quần chúng nhằm giải phóng, không phải công cụ đàn áp như phương án C."},{"id":"C3-114","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Muốn cho cách mạng xã hội nổ ra và giành thắng lợi, ngoài tình thế cách mạng cần phải có:","opts":["Sự khủng hoảng trong xã hội","Nhân tố chủ quan","Sự giác ngộ và tích cực của quần chúng nhân dân","Sự chín muồi của nhân tố chủ quan và sự kết hợp đúng đắn giữa nhân tố chủ quan với nhân tố khách quan."],"ans":3,"ex":"V.I. Lênin chỉ ra rằng không phải mọi **tình thế cách mạng** đều dẫn tới cách mạng; cách mạng chỉ nổ ra và thắng lợi khi có thêm **nhân tố chủ quan chín muồi** (giai cấp cách mạng đủ sức tiến hành hành động quần chúng mạnh mẽ) và biết **kết hợp đúng đắn** nhân tố chủ quan với điều kiện khách quan. Các phương án A, B, C chỉ nêu một phần điều kiện."},{"id":"C3-115","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Xu hướng của cách mạng xã hội trên thế giới hiện nay là?","opts":["Xu hướng đối thoại, hòa giải đang là xu hướng chủ đạo hiện nay.","Xu hướng giữ vững độc lập tự chủ của quốc gia dân tộc, không phụ thuộc và không can thiệp vào công việc nội bộ của nhau, đấu tranh cho dân chủ, hòa bình và tiến bộ xã hội đang diễn ra mạnh mẽ.","Các quốc gia, dân tộc sẽ đi tới một xã hội dân chủ, tự do, công bằng, văn minh theo cách đi của mình thông qua các chính sách phát triển kinh tế - xã hội, văn hóa, giáo dục, y tế và khoa học - công nghệ.","Tất cả các đáp án trên đều đúng"],"ans":3,"ex":"Trong bối cảnh thế giới hiện nay, cách mạng xã hội diễn ra với nhiều xu hướng đan xen: xu hướng **đối thoại, hòa giải**; xu hướng giữ vững **độc lập, tự chủ**, đấu tranh vì hòa bình, dân chủ, tiến bộ xã hội; và xu hướng các dân tộc tự lựa chọn con đường đi tới xã hội dân chủ, công bằng, văn minh qua các chính sách phát triển. Cả ba nhận định đều đúng nên chọn D."},{"id":"C3-116","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền đáp án đúng vào chỗ trống sau: Khái niệm … dùng để chỉ phương diện sinh hoạt vật chất và các điều kiện sinh hoạt vật chất của xã hội.","opts":["Lực lượng sản xuất","Kiến trúc thượng tầng","Tồn tại xã hội","Quan hệ sản xuất"],"ans":2,"ex":"**Tồn tại xã hội** là khái niệm chỉ phương diện sinh hoạt vật chất và các điều kiện sinh hoạt vật chất của xã hội, đối lập với **ý thức xã hội** là phương diện tinh thần. Lực lượng sản xuất và quan hệ sản xuất chỉ là bộ phận của phương thức sản xuất, còn kiến trúc thượng tầng thuộc đời sống chính trị – tinh thần."},{"id":"C3-117","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Các yếu tố cấu thành tồn tại xã hội bao gồm:","opts":["Phương thức sản xuất và điều kiện tự nhiên – hoàn cảnh địa lý.","Phương thức sản xuất, điều kiện tự nhiên – hoàn cảnh địa lý và dân cư.","Phương thức sản xuất, xã hội và dân cư.","Điều kiện tự nhiên - hoàn cảnh địa lý và dân cư."],"ans":1,"ex":"Theo giáo trình, **tồn tại xã hội** gồm ba yếu tố cơ bản: **phương thức sản xuất vật chất**, **điều kiện tự nhiên – hoàn cảnh địa lý** và **dân số, mật độ dân số** (dân cư). Trong đó phương thức sản xuất giữ vai trò quyết định. Các phương án còn lại thiếu yếu tố hoặc đưa vào khái niệm quá rộng như \"xã hội\"."},{"id":"C3-118","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Khái niệm ý thức xã hội dùng để chỉ:","opts":["Phương diện sinh hoạt vật chất của xã hội.","Phương diện sinh hoạt tinh thần của một giai cấp.","Phương diện sinh hoạt tinh thần của đời sống xã hội, nảy sinh từ tồn tại xã hội và phản ánh tôn tại xã hội trong những giai đoạn nhất định.","Những đặc trưng về tâm lý, tính cách của một cộng đồng dân tộc"],"ans":2,"ex":"**Ý thức xã hội** là phương diện sinh hoạt tinh thần của đời sống xã hội, nảy sinh từ tồn tại xã hội và phản ánh tồn tại xã hội trong những giai đoạn lịch sử nhất định. Nó bao gồm quan điểm, tư tưởng, tình cảm, tâm trạng, truyền thống... của cộng đồng. Phương án A là tồn tại xã hội, B chỉ là ý thức của một giai cấp, D chỉ là tâm lý dân tộc."},{"id":"C3-119","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Hình thái ý thức xã hội nào sau đây ra đời từ khi xã hội chưa phân chia giai cấp?","opts":["Ý thức triết học.","Ý thức tôn giáo.","Ý thức chính trị.","Ý thức pháp quyền."],"ans":1,"ex":"**Ý thức tôn giáo** xuất hiện rất sớm, từ xã hội nguyên thủy, dưới dạng tín ngưỡng, ma thuật, tô tem giáo, do sự bất lực của con người trước tự nhiên. Ngược lại, **ý thức chính trị**, **ý thức pháp quyền** gắn liền với giai cấp và nhà nước; **triết học** ra đời khi đã có phân công lao động trí óc – chân tay và phân chia giai cấp."},{"id":"C3-120","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng theo quan điểm triết học Mác - Lênin về đặc điểm tâm lý xã hội.","opts":["Tâm lý xã hội là sự phản ánh mang tính kinh nghiệm, yếu tố trí tuệ và đan xen yếu tố tình cảm.","Tâm lý xã hội là sự phản ánh gián tiếp có tính tự phát, thường ghi lại những mặt bề ngoài tồn tại xã hội.","Tâm lý xã hội mang tính phong phú và phức tạp, nhưng không tuân theo các quy luật tâm lý.","Tâm lý xã hội không có vai trò quan trọng trong ý thức xã hội."],"ans":0,"ex":"**Tâm lý xã hội** là cấp độ thấp của ý thức xã hội, bao gồm tình cảm, tâm trạng, thói quen, tập quán hình thành trực tiếp từ đời sống hằng ngày. Nó phản ánh mang tính **kinh nghiệm**, trong đó yếu tố trí tuệ đan xen với yếu tố tình cảm. Tâm lý xã hội phản ánh **trực tiếp** chứ không gián tiếp, vẫn tuân theo quy luật tâm lý và có vai trò quan trọng."},{"id":"C3-121","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất về tâm lý xã hội.","opts":["Tâm lý xã hội cho biết những mối liên hệ khách quan, bản chất, tất yếu mang tính quy luật của các sự vật và quá trình xã hội.","Tâm lý xã hội phản ánh một cách trực tiếp và tự phát những điều kiện sinh hoạt hằng ngày của con người.","Tâm lý xã hội phản ánh một cách trực tiếp và tự giác những điều kiện sinh hoạt hằng ngày của con người.","Tâm lý xã hội không bao gồm tư tưởng của xã hội hình thành dưới tác động trực tiếp của cuộc sống hằng ngày."],"ans":2,"ex":"**Tâm lý xã hội** phản ánh **trực tiếp** điều kiện sinh hoạt hằng ngày của con người, hình thành từ kinh nghiệm sống, tình cảm, tâm trạng, thói quen. Theo đáp án gốc, C được chọn. Lưu ý: giáo trình nhấn mạnh tâm lý xã hội mang tính **tự phát**, chưa đạt tới trình độ lý luận; phương án A là đặc điểm của hệ tư tưởng/lý luận khoa học, không phải tâm lý xã hội."},{"id":"C3-122","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng về đặc điểm hệ tư tưởng.","opts":["Hệ tư tưởng ra đời trực tiếp từ tâm lý xã hội.","Hệ tư tưởng là hệ thống những quan điểm, hệ thống hóa, khái quát hóa thành lý luận, thành các học thuyết chính trị - xã hội phản ánh lợi ích của một giai cấp nhất định.","Trong xã hội có giai cấp thì chỉ có hệ tư tưởng biểu hiện tính giai cấp của ý thức xã hội.","Hệ tư tưởng không ảnh hưởng đến sự phát triển của khoa học."],"ans":1,"ex":"**Hệ tư tưởng** là cấp độ cao của ý thức xã hội: hệ thống quan điểm được khái quát hóa thành lý luận, học thuyết chính trị – xã hội, phản ánh lợi ích của một giai cấp nhất định. Hệ tư tưởng không ra đời trực tiếp từ tâm lý xã hội mà do các nhà tư tưởng xây dựng; tâm lý xã hội cũng mang tính giai cấp; và hệ tư tưởng có ảnh hưởng tới khoa học."},{"id":"C3-123","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng về vai trò của tồn tại xã hội trong quan hệ biện chứng với ý thức xã hội.","opts":["Ý thức xã hội hoàn toàn phụ thuộc một cách thụ động vào tồn tại xã hội.","Tồn tại xã hội quyết định ý thức xã hội.","Khi tồn tại xã hội đã thay đổi thì toàn bộ các yếu tố cấu thành ý thức xã hội biến đổi theo cùng tồn tại xã hội.","Tồn tại xã hội có vai trò quyết định đối với các hình thái ý thức xã hội một cách đơn giản, trực tiếp, không qua các khâu trung gian."],"ans":1,"ex":"Nguyên lý cơ bản của chủ nghĩa duy vật lịch sử: **tồn tại xã hội quyết định ý thức xã hội**. Tuy vậy, sự quyết định này không đơn giản, trực tiếp mà thường thông qua các khâu trung gian; ý thức xã hội có **tính độc lập tương đối**, không phụ thuộc thụ động và không phải mọi yếu tố đều biến đổi đồng thời. Do đó A, C, D sai."},{"id":"C3-124","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất về tính độc lập tương đối của ý thức xã hội.","opts":["Các hình thái ý thức xã hội trong quá trình phản ánh hiện thực có tác động trở lại tồn tại xã hội như nhau.","Ý thức xã hội luôn luôn lạc hậu hơn so với tồn tại xã hội vì không phản ánh kịp hoạt động thực tiễn.","Không thể giải thích một tư tưởng nào đó nếu chỉ dựa vào những quan hệ kinh tế hiện có mà không chú ý đến các giai đoạn phát triển tư tướng đó.","Ý thức xã hội tác động trở lại tồn tại xã hội theo hai chiều hướng hoặc thúc đẩy hoặc kìm hãm; mức độ tác động đó chỉ phụ thuộc vào điều kiện lịch sử cụ thể."],"ans":3,"ex":"Một biểu hiện của **tính độc lập tương đối** là ý thức xã hội **tác động trở lại** tồn tại xã hội theo hai chiều: thúc đẩy (nếu tiến bộ) hoặc kìm hãm (nếu lạc hậu). Theo đáp án gốc, D được chọn vì nêu đúng hai chiều tác động. Cần biết thêm: giáo trình cho rằng mức độ tác động còn phụ thuộc tính chất quan hệ kinh tế, vai trò giai cấp mang tư tưởng và mức độ truyền bá vào quần chúng."},{"id":"C3-125","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất về tính độc lập tương đối của ý thức xã hội.","opts":["Những tư tưởng khoa học tiên tiến có thể vượt trước sự phát triển của tồn tại xã hội nên có thể thoát ly tồn tại xã hội.","Tồn tại xã hội thay đổi nhưng có một số bộ phận của ý thức xã hội chưa thay đổi ngay cùng với tồn tại xã hội.","Các hình thái ý thức xã hội trong sự phát triển không thể tác động qua lại lẫn nhau.","Trong xã hội có giai cấp, tính chất kế thừa của ý thức xã hội không gắn liền với tính giai cấp của nó."],"ans":1,"ex":"**Tính lạc hậu** của ý thức xã hội: khi tồn tại xã hội đã thay đổi, một số bộ phận của ý thức xã hội (nhất là tâm lý, phong tục, tập quán) chưa thay đổi ngay. Tư tưởng tiến bộ có thể vượt trước nhưng không thoát ly tồn tại xã hội; các hình thái ý thức có tác động qua lại; trong xã hội có giai cấp, sự kế thừa gắn với tính giai cấp."},{"id":"C3-126","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Yếu tố nào sau đây là yếu tố cơ bản nhất của tồn tại xã hội?","opts":["Điều kiện tự nhiên.","Dân số.","Phương thức sản xuất vật chất.","Năng suất lao động"],"ans":2,"ex":"Trong ba yếu tố của tồn tại xã hội, **phương thức sản xuất vật chất** là yếu tố cơ bản, quyết định. Nó quy định tính chất, kết cấu xã hội và sự chuyển biến từ hình thái kinh tế – xã hội này sang hình thái khác. Điều kiện tự nhiên và dân số có ảnh hưởng nhưng không giữ vai trò quyết định; năng suất lao động chỉ là chỉ tiêu của lực lượng sản xuất."},{"id":"C3-127","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Ý thức xã hội bao gồm các hình thái ý thức xã hội cơ bản nào?","opts":["Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức văn hóa, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức thẩm mỹ, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức đạo đức, ý thức dân tộc, ý thức tôn giáo, ý thức khoa học, ý thức triết học.","Ý thức chính trị, ý thức pháp quyền, ý thức văn hóa, ý thức môi trường, ý thức tôn giáo, ý thức khoa học, ý thức triết học."],"ans":1,"ex":"Giáo trình nêu các **hình thái ý thức xã hội** cơ bản: ý thức chính trị, pháp quyền, đạo đức, **thẩm mỹ** (nghệ thuật), tôn giáo, khoa học và triết học. \"Văn hóa\", \"dân tộc\", \"môi trường\" không phải là hình thái ý thức xã hội độc lập theo cách phân loại này, nên các phương án A, C, D sai."},{"id":"C3-128","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Khi tồn tại xã hội thay đổi thì:","opts":["Ý thức tôn giáo sẽ không thay đổi.","triết học sẽ thay đổi triệt để","Ý thức xã hội sớm hay muộn cũng sẽ có những thay đổi nhất định.","Ý thức xã hội sẽ thay đổi một cách hệ thống và đồng bộ."],"ans":2,"ex":"Vì **tồn tại xã hội quyết định ý thức xã hội**, khi tồn tại xã hội biến đổi thì ý thức xã hội **sớm hay muộn** cũng biến đổi theo. Nhưng do tính độc lập tương đối, sự biến đổi không đồng loạt, không đồng bộ; có yếu tố đổi nhanh, có yếu tố (như tôn giáo, tập quán) đổi chậm. Vì vậy C đúng, còn A, B, D tuyệt đối hóa."},{"id":"C3-129","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong xã hội có giai cấp, hình thái ý thức xã hội nào quyết định đến các hình thái ý thức xã hội còn lại?","opts":["Ý thức đạo đức","Ý thức chính trị","Ý thức thẩm mỹ","Ý thức pháp quyền"],"ans":1,"ex":"Trong xã hội có giai cấp, **ý thức chính trị** phản ánh trực tiếp quan hệ kinh tế và lợi ích giai cấp, quan hệ giữa các giai cấp với nhà nước, nên có vai trò đặc biệt quan trọng, chi phối các hình thái ý thức khác như pháp quyền, đạo đức, nghệ thuật. Ý thức pháp quyền gắn bó với chính trị nhưng chịu sự chi phối của ý thức chính trị."},{"id":"C3-130","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Ý thức xã hội không phụ thuộc vào tồn tại xã hội một cách thụ động mà còn có tác động tích cực trở lại tồn tại xã hội, đó là sự thể hiện:","opts":["Tính độc lập tương đối của ý thức xã hội","Tính định hướng của ý thức xã hội","Ý thức xã hội luôn có tính vượt trước","Tất cả các đáp án trên"],"ans":0,"ex":"**Tính độc lập tương đối** của ý thức xã hội thể hiện ở: tính lạc hậu, tính vượt trước, tính kế thừa, sự tác động qua lại giữa các hình thái và đặc biệt là **sự tác động trở lại tồn tại xã hội**. Việc ý thức xã hội không phụ thuộc thụ động mà tác động tích cực trở lại chính là biểu hiện đó. \"Vượt trước\" chỉ là một biểu hiện khác, không phải luôn luôn có."},{"id":"C3-131","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điều kiện cơ bản để ý thức xã hội tác động trở lại tồn tại xã hội là:","opts":["Ý thức xã hội phải phù hợp với tồn tại xã hội","Hoạt động thực tiễn của con người","Điều kiện vật chất bảo đảm","Ý thức xã hội phải “vượt trước” tồn tại xã hội"],"ans":1,"ex":"Ý thức tự nó không làm thay đổi được hiện thực; ý thức xã hội chỉ tác động tới tồn tại xã hội **thông qua hoạt động thực tiễn** của con người. Tư tưởng chỉ trở thành lực lượng vật chất khi thâm nhập vào quần chúng và được quần chúng hiện thực hóa bằng hành động. Đây là điều kiện cơ bản, các phương án còn lại chỉ là yếu tố phụ hoặc không bắt buộc."},{"id":"C3-132","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Mối quan hệ giữa tồn tại xã hội và ý thức xã hội thực chất là biểu hiện của mối quan hệ giữa:","opts":["Kinh tế và chính trị.","Vật chất và ý thức.","Thực tiễn và lý luận.","Kinh tế và văn hóa."],"ans":1,"ex":"Quan hệ **tồn tại xã hội – ý thức xã hội** là sự vận dụng vấn đề cơ bản của triết học (quan hệ **vật chất – ý thức**) vào lĩnh vực xã hội. Tồn tại xã hội là phương diện vật chất, ý thức xã hội là phương diện tinh thần của đời sống xã hội. Các cặp kinh tế – chính trị, thực tiễn – lý luận chỉ là những biểu hiện hẹp hơn."},{"id":"C3-133","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhận định nào sau đây là SAI về ý thức xã hội:","opts":["Ý thức xã hội là sự phản ánh tồn tại xã hội.","Ý thức xã hội có tính độc lập tương đối trong quan hệ với tồn tại với xã hội.","Ý thức xã hội là đời sống chính trị của xã hội.","Ý thức xã hội không đồng nhất với ý thức cá nhân."],"ans":2,"ex":"**Ý thức xã hội** là phương diện sinh hoạt tinh thần của xã hội, phản ánh tồn tại xã hội, có tính độc lập tương đối và không đồng nhất với ý thức cá nhân (quan hệ cái chung – cái riêng). Nói ý thức xã hội là \"đời sống chính trị\" là sai, vì chính trị chỉ là một lĩnh vực; ý thức chính trị chỉ là một hình thái của ý thức xã hội."},{"id":"C3-134","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu là nhận định nào SAI về ý thức xã hội?","opts":["Ý thức xã hội luôn lạc hậu hơn tồn tại xã hội.","Ý thức xã hội có thể vượt trước tồn tại xã hội.","Ý thức xã hội có thể tác động trở lại tồn tại xã hội.","Ý thức xã hội có tính độc lập tương đối với tồn tại xã hội."],"ans":0,"ex":"Ý thức xã hội **thường** lạc hậu so với tồn tại xã hội, nhưng không phải **luôn luôn**; tư tưởng khoa học tiên tiến có thể **vượt trước**, dự báo tương lai. Do đó nhận định \"luôn lạc hậu\" là tuyệt đối hóa, sai. Các nhận định B, C, D đều là biểu hiện đúng của tính độc lập tương đối của ý thức xã hội."},{"id":"C3-135","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đảng ta đã dựa trên cơ sở lý luận nào để phát huy vai trò của con người trong sự nghiệp cách mạng và đổi với ở Việt Nam hiện nay?","opts":["Lý luận về con người của Nho giáo","Lý luận về con người của thời kỳ Phục Hưng","Lý luận về con người của Chủ nghĩa Mác-Lênin","Cả 3 đáp án trên"],"ans":2,"ex":"Đảng Cộng sản Việt Nam lấy **chủ nghĩa Mác – Lênin** và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng. Quan điểm về con người là thực thể sinh học – xã hội, là tổng hòa các quan hệ xã hội, vừa là chủ thể vừa là sản phẩm của lịch sử là cơ sở để Đảng xác định con người là **trung tâm, mục tiêu và động lực** của sự nghiệp đổi mới."},{"id":"C3-136","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vận dụng kiến thức nào của chủ nghĩa duy vật lịch sử để giải thích trong giai đoạn hiện nay vẫn còn tồn tại tư tưởng “trọng nam, khinh nữ”?","opts":["Ý thức xã hội có tính vượt trước so với tồn tại xã hội","Ý thức xã hội có tính kế thừa trong sự phát triển","Có sự tác động qua lại giữa các hình thái ý thức xã hội khác nhau","Ý thức xã hội thường lạc hậu hơn so với tồn tại xã hội"],"ans":3,"ex":"Tư tưởng \"trọng nam khinh nữ\" hình thành từ tồn tại xã hội phong kiến, gia trưởng. Dù tồn tại xã hội đã thay đổi, tư tưởng ấy vẫn còn do **tính lạc hậu** của ý thức xã hội: sức ỳ của tập quán, thói quen, và sự duy trì của các lực lượng bảo thủ. Đây là biểu hiện của tính độc lập tương đối, không phải tính vượt trước."},{"id":"C3-137","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vận dụng kiến thức nào của chủ nghĩa duy vật lịch sử để giải thích câu nói: “sức mạnh của thói quen, của phong tục, tập quán là sức mạnh bảo thủ ghê gớm nhất”?","opts":["Quan hệ sản xuất tác động ngược trở lại lực lượng sản xuất.","Tính độc lập tương đối của ý thức xã hội so với tồn tại xã hội.","Cơ sở hạ tầng quyết định kiến trúc thượng tầng","Không có đáp án nào"],"ans":1,"ex":"Câu nói của V.I. Lênin chỉ ra rằng thói quen, phong tục, tập quán, những yếu tố thuộc tâm lý xã hội, thường tồn tại dai dẳng dù cơ sở kinh tế sinh ra chúng đã mất. Đây là biểu hiện **tính lạc hậu**, một mặt của **tính độc lập tương đối của ý thức xã hội** so với tồn tại xã hội. Các phương án A, C nói về quan hệ khác."},{"id":"C3-138","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tâm lý tiểu nông của người Việt Nam truyền thống căn bản là do:","opts":["Bản tính cố hữu của người Việt","Bị đế quốc, phong kiến nhiều thế kỷ áp bức, bóc lột","Phương thức sản xuất tiểu nông, manh mún, lạc hậu","Tất cả các phương án đều sai"],"ans":2,"ex":"Theo nguyên lý **tồn tại xã hội quyết định ý thức xã hội**, tâm lý tiểu nông (manh mún, cục bộ, bình quân chủ nghĩa...) căn bản là sản phẩm của **phương thức sản xuất tiểu nông** nhỏ lẻ, lạc hậu kéo dài nhiều thế kỷ. Đó không phải là bản tính cố hữu; áp bức của đế quốc, phong kiến chỉ là yếu tố củng cố thêm."},{"id":"C3-139","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Lối sống, phong tục tập quán của con người ở những vùng miền khác nhau là do:","opts":["Tồn tại xã hội quyết định","Sở thích theo nhóm người","Sự khác nhau của ngôn ngữ","Sự khác nhau về nhà nước và pháp luật"],"ans":0,"ex":"Lối sống, phong tục, tập quán là những yếu tố của **ý thức xã hội** (tâm lý xã hội). Chúng khác nhau giữa các vùng miền vì điều kiện tự nhiên, cách thức sản xuất, dân cư, tức **tồn tại xã hội**, ở mỗi nơi khác nhau. Sở thích, ngôn ngữ hay nhà nước, pháp luật không phải nguyên nhân quyết định."},{"id":"C3-141","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các định nghĩa sau đây, định nghĩa nào là của triết học Mác – Lênin về con người?","opts":["Con người là động vật biết tư duy.","Con người là động vật hai chân, không có lông vũ","Con người là thực thể xã hội.","Con người là một thực thể thống nhất sinh học - xã hội."],"ans":3,"ex":"Triết học Mác – Lênin định nghĩa con người là **thực thể thống nhất giữa mặt sinh vật và mặt xã hội**. Mặt sinh học là tiền đề, mặt xã hội là bản chất, hai mặt thống nhất, không tách rời. Định nghĩa \"động vật biết tư duy\" hay \"động vật hai chân không lông\" (Platon) chỉ nêu dấu hiệu bề ngoài; \"thực thể xã hội\" bỏ qua mặt sinh học."},{"id":"C3-142","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quan niệm của triết học Mác-Lênin về bản chất con người?","opts":["Con người là một thực thể thống nhất giữa mặt sinh vật với mặt xã hội","Trong tính hiện thực của nó con người là tổng hòa những quan hệ xã hội trên nền tảng sinh học.","Con người là chủ thể và là sản phẩm của lịch sử.","Bao gồm ba đáp án trên."],"ans":3,"ex":"Quan niệm Mác – Lênin về con người gồm các luận điểm: con người là **thực thể sinh học – xã hội**; trong tính hiện thực, bản chất con người là **tổng hòa các quan hệ xã hội** (Luận cương về Phoiơbắc); con người vừa là **chủ thể** vừa là **sản phẩm** của lịch sử. Ba nhận định A, B, C đều đúng nên chọn D."},{"id":"C3-143","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chủ nghĩa duy vật lịch sử coi con người là một bộ phận của giới tự nhiên, còn giới tự nhiên là...","opts":["Đối tượng chinh phục của con người.","Đối tượng cải tạo của con người.","Thân thể vô cơ của con người.","Đối tượng vô cơ của con người."],"ans":2,"ex":"Trong **Bản thảo kinh tế – triết học 1844**, C. Mác viết giới tự nhiên là **\"thân thể vô cơ của con người\"**. Con người là bộ phận của tự nhiên, sống nhờ tự nhiên và phải thường xuyên trao đổi chất với tự nhiên. Quan niệm tự nhiên chỉ là \"đối tượng chinh phục\" là phiến diện, dễ dẫn tới phá hủy môi trường."},{"id":"C3-144","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Cơ sở khoa học tự nhiên của quan niệm “con người là sản phẩm của quá trình phát triển lâu dài của giới tự nhiên” là gì?","opts":["Thuyết tế bào.","Thuyết tiến hóa.","Thuyết di truyền","Thuyết biến dị"],"ans":1,"ex":"Quan niệm con người là sản phẩm của quá trình phát triển lâu dài của giới tự nhiên dựa trên **thuyết tiến hóa** của **Ch. Đácuyn**, chứng minh nguồn gốc tự nhiên của loài người. Thuyết tế bào và định luật bảo toàn, chuyển hóa năng lượng là những phát minh khác, làm cơ sở cho chủ nghĩa duy vật biện chứng nói chung."},{"id":"C3-145","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Con người mà triết học Mác – Lênin nghiên cứu là:","opts":["Con người cụ thể.","Con người trừu tượng.","Con người hiện thực.","Con người lý tưởng."],"ans":2,"ex":"Khác với con người trừu tượng của chủ nghĩa duy vật cũ (Phoiơbắc) hay con người lý tưởng của chủ nghĩa duy tâm, triết học Mác – Lênin nghiên cứu **con người hiện thực**: con người sống, hoạt động thực tiễn, trong những quan hệ xã hội và điều kiện lịch sử cụ thể. \"Con người cụ thể\" là đối tượng của các khoa học cụ thể."},{"id":"C3-146","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quan niệm của triết học Mác - Lênin cho rằng: muốn nhận thức bản chất con người cần phải:","opts":["Thông qua tư tưởng của con người.","Thông qua hoạt động sản xuất vật chất của con người.","Thông qua các quan hệ hiện thực của con người.","Thông qua cống hiến xã hội của con người."],"ans":2,"ex":"Theo luận điểm của C. Mác, bản chất con người là **tổng hòa những quan hệ xã hội** trong tính hiện thực. Vì vậy muốn nhận thức bản chất con người phải xem xét qua **các quan hệ hiện thực** của nó (kinh tế, chính trị, gia đình, tinh thần...). Hoạt động sản xuất là một quan hệ cơ bản nhưng chưa đủ bao quát; tư tưởng hay cống hiến chỉ là biểu hiện."},{"id":"C3-147","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của chủ nghĩa Mác - Lênin: Trong tính hiện thực của nó, bản chất con người là...?","opts":["Tính thiện.","Tính ác.","Tổng hòa những quan hệ xã hội.","Tổng hòa các quan hệ kinh tế"],"ans":2,"ex":"Trong **Luận cương về Phoiơbắc** (1845), C. Mác khẳng định: trong tính hiện thực của nó, bản chất con người là **tổng hòa những quan hệ xã hội**. Quan niệm tính thiện, tính ác (Mạnh Tử, Tuân Tử) là trừu tượng, phi lịch sử. \"Tổng hòa các quan hệ kinh tế\" thu hẹp bản chất con người vào một loại quan hệ."},{"id":"C3-148","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền vào chỗ trống: “Bản chất con người không phải là một cái trừu tượng của cá nhân riêng biệt. Trong...(1)... của nó bản chất con người là...(2)... những quan hệ xã hội”.","opts":["1) tính vật chất, 2) tổng hòa.","1) tính vật chất, 2) tổng hợp.","1) tính hiện thực, 2) tổng số.","1) tính hiện thực, 2) tổng hòa."],"ans":3,"ex":"Đây là luận điểm nổi tiếng trong **Luận cương về Phoiơbắc** của C. Mác: bản chất con người không phải cái trừu tượng cố hữu của cá nhân riêng biệt; **trong tính hiện thực của nó**, bản chất con người là **tổng hòa** những quan hệ xã hội. \"Tổng hòa\" nhấn mạnh sự thống nhất, tác động qua lại, không phải phép cộng \"tổng số\" hay \"tổng hợp\"."},{"id":"C3-149","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chủ nghĩa duy vật lịch sử cho rằng:","opts":["Con người là chủ thể sáng tạo ra lịch sử theo ý mình.","Lịch sử sáng tạo ra con người, con người không thể sáng tạo ra lịch sử.","Con người sáng tạo ra lịch sử trong phạm vi những điều kiện khách quan mà chính lịch sử trước đó đã tạo ra cho nó.","Con người và lịch sử đều là kết quả ngẫu nhiên, không phải là sự sáng tạo chủ quan."],"ans":2,"ex":"Chủ nghĩa duy vật lịch sử khẳng định: con người sáng tạo ra lịch sử, nhưng không phải theo ý muốn tùy tiện mà **trong những điều kiện khách quan** do lịch sử trước đó để lại (C. Mác, **Ngày 18 tháng Sương mù của Lu-i Bô-na-pác-tơ**). Phương án A là duy ý chí, B là định mệnh luận, D phủ nhận tính quy luật."},{"id":"C3-150","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nội dung nào thể hiện đúng nhất quan điểm của chủ nghĩa duy vật lịch sử về con người?","opts":["Con người là sản phẩm của lịch sử, luôn chịu tác động của lịch sử.","Con người vừa là chủ thể của lịch sử, vừa là sản phẩm của lịch sử.","Con người sáng tạo ra lịch sử theo mong muốn chủ quan của mình.","Con người vừa là sản phẩm của lịch sử, vừa là bộ phận của lịch sử."],"ans":1,"ex":"Quan điểm đúng nhất là con người **vừa là chủ thể vừa là sản phẩm của lịch sử**. Con người là sản phẩm của tự nhiên và lịch sử xã hội, đồng thời bằng lao động sản xuất, con người cải tạo tự nhiên, xã hội và tạo ra lịch sử của mình. Phương án A chỉ nêu một mặt, C là duy ý chí, D không thể hiện vai trò chủ thể."},{"id":"C3-151","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Hai yếu tố nào sau đây có vai trò quan trọng nhất đánh dấu sự phát triển của con người về phương diện xã hội?","opts":["Lao động và sáng tạo.","Lao động và ngôn ngữ.","Lao động và sản xuất.","Khoa học và kỹ thuật."],"ans":1,"ex":"Theo Ph. Ăngghen trong **Vai trò của lao động trong quá trình chuyển biến từ vượn thành người**, đầu tiên là **lao động**, sau lao động và đồng thời với lao động là **ngôn ngữ**: đó là hai sức kích thích chủ yếu biến bộ óc vượn thành bộ óc người. Hai yếu tố này đánh dấu sự phát triển của con người về phương diện xã hội."},{"id":"C3-152","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống của luận điểm sau: “Khi lao động bị..., con người trở nên què quặt, phiến diện, khuyết thiếu trên nhiều phương diện khác nhau”.","opts":["Kìm hãm","Triệt tiêu","Tha hóa","Loại bỏ"],"ans":2,"ex":"C. Mác phân tích **lao động bị tha hóa** trong **Bản thảo kinh tế – triết học 1844**: khi sản phẩm và quá trình lao động trở thành lực lượng xa lạ, thống trị người lao động, con người bị biến dạng, trở nên què quặt, phiến diện. \"Tha hóa\" là thuật ngữ chính xác, chỉ sự biến đổi thành cái xa lạ, đối lập với bản chất người, chứ không chỉ là kìm hãm hay triệt tiêu."},{"id":"C3-153","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Thực chất của hiện tượng tha hóa ở con người là gì?","opts":["Lao động của con người bị tha hóa","Nhân cách của con người bị thay đổi","Động cơ hành động của con người bị thay đổi","Hành động của con người gây bất lợi cho nhau"],"ans":0,"ex":"Thực chất của tha hóa con người là **lao động bị tha hóa**: người lao động bị tách khỏi sản phẩm, khỏi quá trình lao động, khỏi bản chất loài và khỏi người khác. Do lao động là hoạt động bản chất của con người, nên khi lao động bị tha hóa thì con người bị tha hóa. Thay đổi nhân cách hay động cơ chỉ là hệ quả."},{"id":"C3-154","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Biểu hiện tha hóa ở con người, theo quan điểm của Triết học Mác-Lênin là gì?","opts":["Con người đối xử với nhau tàn bạo hơn","Con người bị đánh mất mình trong lao động","Con người lao động tự giác và sáng tạo hơn","Cả 3 đáp án trên đều đúng"],"ans":1,"ex":"Biểu hiện của tha hóa là con người **bị đánh mất mình trong lao động**: lao động không còn là sự khẳng định bản chất người mà trở thành phương tiện kiếm sống, bị cưỡng bức; người lao động chỉ thấy tự do trong các chức năng động vật. Phương án C là ngược lại với tha hóa; phương án A chỉ là hiện tượng đạo đức bề ngoài."},{"id":"C3-155","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tha hóa của con người được đẩy lên mức cao nhất trong nền sản xuất của chế độ xã hội nào?","opts":["Chiếm hữu Nô lệ","Phong kiến","Tư bản Chủ nghĩa","Cộng sản Chủ nghĩa"],"ans":2,"ex":"Tha hóa gắn với chế độ tư hữu và được đẩy lên **mức cao nhất trong chủ nghĩa tư bản**, khi sức lao động trở thành hàng hóa, người công nhân bị bóc lột giá trị thặng dư, sản phẩm lao động biến thành tư bản thống trị lại người lao động. Chủ nghĩa cộng sản là xã hội xóa bỏ tha hóa, nên D sai."},{"id":"C3-156","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của Triết học Mác-Lênin, nguyên nhân của hiện tượng tha hóa của con người là gì?","opts":["Do sự ý muốn chủ quan của con người","Do sự sắp đặt của Thượng đế","Do sự xuất hiện của chế độ tư hữu về tư liệu sản xuất","Do chế độ sở hữu chung về tư liệu sản xuất"],"ans":2,"ex":"Theo triết học Mác – Lênin, nguyên nhân của tha hóa là **chế độ tư hữu về tư liệu sản xuất**, gắn với sự phân chia giai cấp và bóc lột. Tha hóa không do ý muốn chủ quan hay Thượng đế sắp đặt. Chế độ công hữu chính là điều kiện để khắc phục tha hóa, giải phóng con người."},{"id":"C3-157","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống của luận điểm sau: “Sự phát triển tự do của mỗi người là ... cho sự phát triển tự do của tất cả mọi người”?","opts":["Điều kiện","Nguyên nhân","Lý do","Tiền đề"],"ans":0,"ex":"Trong **Tuyên ngôn của Đảng Cộng sản** (1848), C. Mác và Ph. Ăngghen viết: thay cho xã hội tư sản sẽ xuất hiện một liên hiệp, trong đó **sự phát triển tự do của mỗi người là điều kiện cho sự phát triển tự do của tất cả mọi người**. Luận điểm nêu mục tiêu giải phóng con người, quan hệ thống nhất giữa cá nhân và cộng đồng."},{"id":"C3-158","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điều kiện và tiền đề để giải phóng triệt để con người theo quan điểm của Triết học Mác-Lênin là gì?","opts":["Xóa bỏ áp bức bất công","Xóa bỏ giai cấp và chế độ sở hữu tư nhân về tư liệu sản xuất","Xóa bỏ lao động","Xóa bỏ chế độ công hữu về tư liệu sản xuất"],"ans":1,"ex":"Vì nguồn gốc của áp bức và tha hóa là chế độ tư hữu, nên điều kiện tiên quyết để giải phóng triệt để con người là **xóa bỏ chế độ tư hữu về tư liệu sản xuất và xóa bỏ giai cấp**, gắn với phát triển lực lượng sản xuất. \"Xóa bỏ áp bức\" chưa chỉ ra gốc rễ; xóa bỏ lao động hay công hữu là sai."},{"id":"C3-159","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, chủ thể chính sáng tạo ra lịch sử là:","opts":["Vĩ nhân.","Cá nhân.","Quần chúng nhân dân.","Giai cấp."],"ans":2,"ex":"Chủ nghĩa duy vật lịch sử khẳng định **quần chúng nhân dân** là chủ thể chân chính sáng tạo ra lịch sử: họ là lực lượng sản xuất cơ bản, động lực của cách mạng xã hội và người sáng tạo giá trị văn hóa tinh thần. Vĩ nhân, lãnh tụ có vai trò quan trọng nhưng chỉ phát huy khi gắn bó với quần chúng."},{"id":"C3-160","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng điền vào chỗ trống, khái niệm … dùng để chỉ lực lượng sản xuất cơ bản của xã hội, trực tiếp sản xuất ra của cải vật chất, là cơ sở của sự tồn tại và phát triển của xã hội. Là động lực cơ bản của mọi cuộc cách mạng xã hội và là người sáng tạo ra những giá trị văn hóa tinh thần cho xã hội.","opts":["Quần chúng nhân dân.","Lãnh tụ","Vĩ nhân.","Tất cả các đáp án trên."],"ans":0,"ex":"Định nghĩa trong câu nêu đủ ba vai trò của **quần chúng nhân dân**: lực lượng sản xuất cơ bản trực tiếp tạo ra của cải vật chất; **động lực cơ bản** của các cuộc cách mạng xã hội; người sáng tạo giá trị văn hóa tinh thần. Lãnh tụ, vĩ nhân là những cá nhân kiệt xuất, không trực tiếp đảm nhiệm các vai trò này với tư cách lực lượng xã hội."},{"id":"C3-161","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Chọn đáp án đúng nhất, lịch sử xã hội loài người được quyết định bởi:","opts":["Quần chúng nhân dân.","Mệnh trời.","Cá nhân anh hùng hào kiệt.","Không do ai quyết định, vì nó diễn ra theo quy luật tự nhiên."],"ans":0,"ex":"Theo chủ nghĩa duy vật lịch sử, lịch sử xã hội do **quần chúng nhân dân** quyết định, vì họ là lực lượng tạo ra của cải vật chất và trực tiếp thực hiện các biến đổi xã hội. Quan niệm \"mệnh trời\" là duy tâm thần bí; đề cao cá nhân anh hùng là duy tâm chủ quan; còn D đồng nhất quy luật xã hội với quy luật tự nhiên, phủ nhận vai trò con người."},{"id":"C3-162","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Yếu tố nào KHÔNG thuộc khái niệm quần chúng nhân dân của triết học Mác - Lênin?","opts":["Người lao động.","Bộ phận dân cư chống lại các giai cấp bóc lột.","Những người cầm quyền trong xã hội.","Những tầng lớp, giai cấp thúc đẩy tiến bộ xã hội."],"ans":2,"ex":"**Quần chúng nhân dân** gồm: người lao động sản xuất của cải vật chất (hạt nhân cơ bản); bộ phận dân cư chống lại giai cấp thống trị áp bức, bóc lột; các giai cấp, tầng lớp thúc đẩy tiến bộ xã hội. Đây là phạm trù lịch sử, có nội hàm thay đổi theo thời đại. \"Những người cầm quyền\" không phải tiêu chí xác định quần chúng nhân dân."},{"id":"C3-163","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Khái niệm cá nhân được xác định trong quan hệ nào sau đây?","opts":["Trong quan hệ với loài.","Trong quan hệ với giai cấp.","Trong quan hệ với xã hội.","Trong quan hệ với nhà nước."],"ans":2,"ex":"**Cá nhân** là khái niệm chỉ con người cụ thể sống trong một xã hội nhất định, được xác định **trong quan hệ với xã hội**: vừa là thực thể riêng biệt, độc đáo, vừa là thành viên mang dấu ấn các quan hệ xã hội. Quan hệ cá nhân – xã hội là quan hệ cái riêng – cái chung; quan hệ với loài là khái niệm \"con người\" nói chung."},{"id":"C3-164","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Quan điểm của chủ nghĩa Mác-Lênin về lãnh tụ là gì?","opts":["Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân.","Những cá nhân kiệt xuất được quần chúng tín nhiệm.","Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân dân.","Tất cả các đáp án trên."],"ans":3,"ex":"Theo chủ nghĩa Mác – Lênin, **lãnh tụ** là những cá nhân kiệt xuất, có tri thức khoa học uyên bác, nắm bắt được xu thế phát triển; có năng lực tập hợp quần chúng; **gắn bó mật thiết với quần chúng**, được quần chúng **tín nhiệm** và sẵn sàng **hy sinh** vì lợi ích của quần chúng. Ba phương án A, B, C đều là phẩm chất của lãnh tụ."},{"id":"C3-165","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Vai trò của lãnh tụ đối với phong trào của quần chúng nhân dân?","opts":["Thúc đẩy hoặc kìm hãm sự tiến bộ của xã hội.","Là người sáng lập ra các tổ chức chính trị, xã hội và là linh hồn của các tổ chức đó.","Lãnh tụ của mỗi thời đại chỉ có thể hoàn thành những nhiệm vụ đặt ra của thời đại đó.","Tất cả các đáp án trên"],"ans":3,"ex":"Lãnh tụ có vai trò: nắm bắt xu thế, định hướng chiến lược; **sáng lập và là linh hồn** của các tổ chức chính trị – xã hội; có thể **thúc đẩy hoặc kìm hãm** tiến bộ xã hội. Tuy vậy, lãnh tụ của mỗi thời đại chỉ hoàn thành được nhiệm vụ do thời đại đặt ra, không thể vượt khỏi điều kiện lịch sử. Vì vậy chọn D."},{"id":"C3-166","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan niệm của triết học Mác Lênin, mục đích cao nhất của sự phát triển xã hội là:","opts":["Hạnh phúc và sự phát triển toàn diện của con người.","Tăng trưởng kinh tế.","Ổn định xã hội.","Bình đẳng xã hội."],"ans":0,"ex":"Theo triết học Mác – Lênin, con người vừa là động lực vừa là mục tiêu của phát triển; **mục đích cao nhất** là **giải phóng con người**, đem lại hạnh phúc và sự phát triển tự do, toàn diện cho con người. Tăng trưởng kinh tế, ổn định và bình đẳng xã hội là phương tiện, điều kiện để đạt mục tiêu ấy."},{"id":"C3-167","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nội dung nào trong các nội dung được nêu dưới đây thể hiện đúng nhất mục tiêu phát triển con người ở Việt Nam giai đoạn hiện nay?","opts":["Phát triển thể chất con người","Phát triển con người toàn diện.","Phát triển con người đạo đức.","Phát triển con người văn hóa."],"ans":1,"ex":"Đảng ta xác định mục tiêu là xây dựng **con người Việt Nam phát triển toàn diện** về trí tuệ, đạo đức, thể chất, tâm hồn, trách nhiệm xã hội, ý thức công dân. Các phương án A, C, D chỉ nêu một khía cạnh, nằm trong nội hàm của phát triển toàn diện. Đây là sự vận dụng tư tưởng Mác về con người phát triển tự do, toàn diện."},{"id":"C3-168","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong tư tưởng truyền thống Việt Nam, vấn đề nào về con người được quan tâm nhiều nhất là:","opts":["Bản chất con người","Trí tuệ của con người.","Đạo lý làm người.","Sức mạnh chinh phục tự nhiên của con người."],"ans":2,"ex":"Tư tưởng truyền thống Việt Nam, chịu ảnh hưởng của Nho, Phật, Lão và văn hóa làng xã, quan tâm nhiều nhất đến **đạo lý làm người**: lòng nhân ái, tình nghĩa, hiếu thảo, trung với nước, đề cao đạo đức hơn tài năng. Việt Nam ít bàn luận trừu tượng về bản chất con người hay sức mạnh chinh phục tự nhiên như triết học phương Tây."},{"id":"C3-169","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tệ sung bái cá nhân trong xã hội là tuyệt đối hóa vai trò của:","opts":["Lãnh tụ","Quần chúng nhân dân","Giai cấp thống trị","Tất cả các phương án trên"],"ans":0,"ex":"**Tệ sùng bái cá nhân** là sự **tuyệt đối hóa vai trò của lãnh tụ**, cá nhân xuất chúng, coi họ là người quyết định lịch sử, đứng trên quần chúng và tổ chức. Đây là biểu hiện của quan điểm duy tâm về lịch sử, trái với nguyên lý quần chúng nhân dân là chủ thể sáng tạo lịch sử; cần phê phán tệ này."},{"id":"C3-170","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Từ vấn đề con người của chủ nghĩa duy vật lịch sử, chọn đáp án đúng nhất: thời thế tạo anh hùng hay anh hùng tạo thời thế?","opts":["Thời thế tạo anh hùng","Anh hùng tạo thời thế","Thời thế tạo anh hùng và anh hùng tạo ra thời thế cả hai đều đúng","Tất cả đều sai"],"ans":2,"ex":"Từ quan điểm con người vừa là **sản phẩm** vừa là **chủ thể** của lịch sử: hoàn cảnh lịch sử (thời thế) đặt ra nhiệm vụ và sản sinh ra lãnh tụ phù hợp, nên **thời thế tạo anh hùng**; đồng thời lãnh tụ nắm bắt quy luật, tổ chức quần chúng làm thay đổi hoàn cảnh, nên **anh hùng tạo thời thế**. Hai mặt thống nhất, nên C đúng."},{"id":"C3-171","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Anh hùng tạo thời thế và thời thế tạo anh hùng, đúng hay sai?","opts":["Sai. Vì khẳng định như vậy là tuyệt đối hóa vai trò của cá nhân, vĩ nhân","Đúng. Vì giải thích từ luận điểm con người là vừa là chủ thể lịch sử và vừa là sản phẩm của hoàn cảnh, lịch sử.","Sai. Vì tuyệt đối hóa vai trò của quần chúng nhân dân","Đúng. Vì tuyệt đối hóa vai trò của lãnh tụ"],"ans":1,"ex":"Nhận định \"anh hùng tạo thời thế và thời thế tạo anh hùng\" là đúng, vì xuất phát từ luận điểm con người **vừa là chủ thể của lịch sử, vừa là sản phẩm của hoàn cảnh**. C. Mác cũng viết hoàn cảnh sáng tạo ra con người đến mức nào thì con người cũng sáng tạo ra hoàn cảnh đến mức ấy. Các phương án D, A, C đều quy về sự tuyệt đối hóa một mặt."},{"id":"C3-172","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nội dung bài thơ sau của Chủ tịch Hồ Chí Minh đề cập đến nội dung nào về con người theo quan điểm của triết học Mác – Lênin? “Ngủ thì ai cũng như lương thiện Tỉnh dạy phân ra kẻ dữ hiền. Hiền, dữ phải đâu là tính sẵn Phần nhiều do giáo dục mà nên”.","opts":["Bản tính con người là do định sẵn","Bản tính con người là tổng hòa các quan hệ xã hội","Con người là một thực thể sinh học – xã hội","Bản chất con người là lương thiện"],"ans":1,"ex":"Bài thơ trong **Nhật ký trong tù** của Hồ Chí Minh cho thấy hiền, dữ không phải bẩm sinh mà chủ yếu do **giáo dục** và môi trường xã hội hình thành. Điều này phù hợp luận điểm bản chất con người là **tổng hòa các quan hệ xã hội**, phủ nhận quan niệm tính thiện, tính ác định sẵn (A, D). Phương án C đúng nhưng không phải trọng tâm bài thơ."},{"id":"C3-173","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong thời kỳ đất nước có chiến tranh, nhiệm vụ của cách mạng Việt Nam đối với con người là gì?","opts":["Giải phóng cho con người","Tạo công ăn việc làm cho con người","Đoàn kết mọi người lại với nhau","Giáo dục cho con người"],"ans":0,"ex":"Trong thời kỳ chiến tranh, nhiệm vụ hàng đầu của cách mạng Việt Nam đối với con người là **giải phóng con người**: giải phóng dân tộc khỏi ách thực dân, đế quốc, giải phóng giai cấp, đem lại độc lập, tự do. Đó là tiền đề để thực hiện các mục tiêu khác như việc làm, giáo dục, đoàn kết."},{"id":"C3-174","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong thời kỳ hiện nay nhiệm vụ của cách mạng Việt Nam đối với con người là gì?","opts":["Chăm lo sức khỏe cho con người","Nâng cao đời sống vật chất cho con người","Chăm lo đời sống tinh thần cho con người","Tạo điều kiện cho con người phát triển một cách toàn diện"],"ans":3,"ex":"Trong thời kỳ đổi mới, xây dựng chủ nghĩa xã hội, nhiệm vụ của cách mạng Việt Nam đối với con người là **tạo điều kiện cho con người phát triển toàn diện**, coi con người là trung tâm, mục tiêu và động lực của phát triển. Chăm lo sức khỏe, đời sống vật chất, tinh thần là các bộ phận nằm trong nhiệm vụ tổng quát này."},{"id":"C3-175","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của Đảng Cộng sản Việt Nam, để phát huy vai trò của con người, cần phải:","opts":["Thực hiện nghiêm túc trong hoạt động nhận thức","Thực hiện triệt để trong hoạt động thực tiễn","Thực hiện trong cả nhận thức lẫn hoạt động thực tiễn","Cả 3 đáp án trên đều sai"],"ans":2,"ex":"Theo quan điểm của Đảng, phát huy vai trò con người phải được thực hiện **cả trong nhận thức lẫn trong hoạt động thực tiễn**, thể hiện nguyên tắc **thống nhất lý luận và thực tiễn**. Nhận thức đúng vị trí con người phải đi đôi với cơ chế, chính sách, hành động cụ thể; nếu tách rời một mặt sẽ rơi vào giáo điều hoặc kinh nghiệm chủ nghĩa."},{"id":"C3-176","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong sự nghiệp xây dựng Chủ nghĩa xã hội ở Việt Nam, chúng ta cần phải tiến hành:","opts":["Phát triển lực lượng sản xuất đạt trình độ tiên tiến để tạo cơ sở cho việc xây dựng quan hệ sản xuất mới","Chủ động xây dựng quan hệ sản xuất mới để tạo cơ sở thúc đẩy lực lượng sản xuất phát triển","Kết hợp đồng thời phát triển lực lượng sản xuất với từng bước xây dựng quan hệ sản xuất mới phù hợp","Củng cố xây dựng kiến trúc thượng tầng mới cho phù hợp với cơ sở hạ tầng"],"ans":2,"ex":"Vận dụng **quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất**, Việt Nam phải **kết hợp đồng thời** phát triển lực lượng sản xuất với từng bước xây dựng quan hệ sản xuất mới phù hợp. Đi trước quan hệ sản xuất một cách duy ý chí (sai lầm trước đổi mới) hay chờ lực lượng sản xuất phát triển hoàn chỉnh đều trái quy luật."},{"id":"C3-181","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống (...) trong câu sau: “...là cơ sở của sự tồn tại và phát triển của xã hội loài người, và xét đến cùng quyết định toàn bộ sự vận động, phát triển của đời sống xã hội”?","opts":["Hoạt động tinh thần","Sản xuất tinh thần","Hoạt động vật chất","Sản xuất vật chất"],"ans":3,"ex":"**Sản xuất vật chất** là hoạt động cải biến tự nhiên tạo ra của cải đáp ứng nhu cầu con người. Đó là **cơ sở của sự tồn tại và phát triển** của xã hội loài người, xét đến cùng quyết định toàn bộ đời sống xã hội: chính trị, pháp luật, khoa học, nghệ thuật... Sản xuất tinh thần chỉ phát triển trên nền tảng sản xuất vật chất."},{"id":"C3-182","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền thêm từ để hoàn thiện nhận định sau đây và xác định đó là nhận định của ai? \"Điểm khác biệt căn bản giữa xã hội loài người với xã hội loài vật là ở chỗ: loài vật may mắn lắm chỉ hái lượm trong khi con người lại........(1) - (.......(2)....)","opts":["1) Biết sáng tạo; 2) Ph. Ăngghen","1) Sản xuất; 2) Ph. Ăngghen","1) Tiến hành lao động; 2) C. Mác","1) Tư duy; 2) V.I. Lênin"],"ans":1,"ex":"Trong thư gửi P.L. Lavrốp (1875), **Ph. Ăngghen** viết: điểm khác biệt căn bản giữa xã hội loài người với xã hội loài vật là loài vật may mắn lắm chỉ hái lượm, trong khi con người lại **sản xuất**. Sản xuất là hoạt động đặc trưng của con người, tạo ra những thứ tự nhiên không có sẵn."},{"id":"C3-183","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống (...) trong câu sau: Sản xuất vật chất là cơ sở của sự ... của xã hội loài người, và xét đến cùng quyết định toàn bộ sự vận động, phát triển của đời sống xã hội?","opts":["Tồn tại","Phát triển","Tiến bộ","Tồn tại và phát triển"],"ans":3,"ex":"Luận điểm đầy đủ của giáo trình: sản xuất vật chất là cơ sở của sự **tồn tại và phát triển** của xã hội loài người, xét đến cùng quyết định sự vận động, phát triển của đời sống xã hội. Sản xuất vật chất vừa bảo đảm sự sống (tồn tại), vừa là nguồn gốc của mọi tiến bộ (phát triển); các phương án A, B, C đều thiếu."},{"id":"C3-184","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tiêu chuẩn quan trọng nhất để phân biệt các thời đại kinh tế là:","opts":["Thể chế chính trị","Hình thức nhà nước","Phương thức sản xuất","Hình thức tôn giáo"],"ans":2,"ex":"C. Mác viết: những thời đại kinh tế khác nhau không phải ở chỗ chúng sản xuất ra cái gì, mà là ở chỗ chúng **sản xuất bằng cách nào**, với những tư liệu lao động nào. Do đó **phương thức sản xuất** là tiêu chuẩn quan trọng nhất phân biệt các thời đại kinh tế. Thể chế chính trị, hình thức nhà nước, tôn giáo thuộc kiến trúc thượng tầng."},{"id":"C3-185","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Mối quan hệ \"song trùng\" của nền sản xuất vật chất mà C. Mác nhắc đến là quan hệ nào sau đây?","opts":["Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với sản phẩm của quá trình sản xuất vật chất","Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với tư liệu sản xuất","Quan hệ giữa con người với tự nhiên và quan hệ giữa con người với con người trong quá trình sản xuất vật chất","Quan hệ giữa người với người trong sản xuất vật chất và quan hệ giai cấp trong xã hội"],"ans":2,"ex":"C. Mác chỉ ra rằng sản xuất vật chất bao hàm **quan hệ \"song trùng\"**: một mặt là quan hệ giữa **con người với tự nhiên** (biểu hiện thành lực lượng sản xuất), mặt khác là quan hệ giữa **con người với con người** trong sản xuất (quan hệ sản xuất). Hai mặt gắn bó, tạo thành phương thức sản xuất."},{"id":"C3-186","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền các từ còn thiếu vào câu sau: \".....(1)..... và.....(2)..... là hai mặt cơ bản, tất yếu của quá trình sản xuất\"?","opts":["Cơ sở hạ tầng/kiến trúc thượng tầng","Cơ sở hạ tầng/quan hệ sản xuất","Lực lượng sản xuất/quan hệ sản xuất","Lực lượng sản xuất/kiến trúc thượng tầng"],"ans":2,"ex":"**Lực lượng sản xuất** (quan hệ người – tự nhiên) và **quan hệ sản xuất** (quan hệ người – người trong sản xuất) là hai mặt cơ bản, tất yếu của quá trình sản xuất, thống nhất trong **phương thức sản xuất**. Cơ sở hạ tầng và kiến trúc thượng tầng là cặp phạm trù khác, nói về quan hệ kinh tế – chính trị, tinh thần."},{"id":"C3-187","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong thời kỳ quá độ lên chủ nghĩa xã hội, Việt Nam cần làm gì?","opts":["Chủ động thiết lập quan hệ sản xuất trước, sau đó phát triển lực lượng sản xuất phù hợp","Chủ động xây dựng lực lượng sản xuất trước, sau đó phát triển quan hệ sản xất phù hợp","Kết hợp đồng thời phát triển lực lượng sản xuất với xác lập quan hệ sản xuất phù hợp.","Tôn trọng quy luật khách quan và tuyệt đối không can thiệp vào sự phát triển của lực lượng sản xuất và quan hệ sản xuất."],"ans":2,"ex":"Trong thời kỳ quá độ, Việt Nam vận dụng quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất bằng cách **kết hợp đồng thời** phát triển lực lượng sản xuất với xác lập quan hệ sản xuất phù hợp. Thiết lập quan hệ sản xuất \"đi trước\" là duy ý chí; còn D sai vì con người có thể chủ động vận dụng quy luật."},{"id":"C3-188","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự tồn tại nền kinh tế hàng hóa nhiều thành phần trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là do yếu tố nào quy định?","opts":["Đặc điểm tự nhiên của Việt Nam quy định","Thành phần giai cấp trong xã hội Việt Nam quy định","Trình độ của lực lượng sản xuất của Việt Nam quy định","Nhận thức chính trị của Việt Nam quy định"],"ans":2,"ex":"Do **lực lượng sản xuất** ở Việt Nam còn ở nhiều trình độ khác nhau (thủ công, cơ khí, hiện đại), theo quy luật quan hệ sản xuất phù hợp với trình độ lực lượng sản xuất, tất yếu phải tồn tại **nhiều hình thức sở hữu**, nhiều thành phần kinh tế. Đây là cơ sở khách quan, không phải do nhận thức chính trị hay đặc điểm tự nhiên."},{"id":"C3-189","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các nội dung sau, nội dung nào thể hiện đúng nhất sự thay đổi của kiến trúc thượng tầng khi cơ sở hạ tầng thay đổi?","opts":["Mọi yếu tố của kiến trúc thượng tầng sẽ thay đổi theo ngay","Nhà nước, tôn giáo, đạo đức thay đổi theo ngay","Tôn giáo, nghệ thuật, triết học thay đổi theo ngay","Không phải mọi yếu tố của kiến trúc thượng tầng sẽ thay đổi theo ngay"],"ans":3,"ex":"Khi **cơ sở hạ tầng** thay đổi thì kiến trúc thượng tầng thay đổi theo, nhưng **không đồng loạt**: các yếu tố như chính trị, pháp luật, nhà nước thay đổi nhanh; còn tôn giáo, nghệ thuật, triết học, đạo đức thay đổi chậm, có yếu tố vẫn tồn tại lâu dài. Vì thế D đúng, còn A, B, C tuyệt đối hóa."},{"id":"C3-190","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống (...) trong câu sau: “Quá trình lịch sử - tự nhiên của sự phát triển xã hội chẳng những diễn ra bằng con đường..... mà còn bao hàm cả sự bỏ qua trong những điều kiện lịch sử nhất định, hoặc một vài hình thái kinh tế - xã hội nhất định”?","opts":["Phát triển nhảy vọt","Phát triển rút ngắn","Phát triển tuần tự","Phát triển từ từ"],"ans":2,"ex":"Học thuyết **hình thái kinh tế – xã hội** coi sự phát triển xã hội là **quá trình lịch sử – tự nhiên**. Quá trình này chẳng những diễn ra bằng con đường **phát triển tuần tự** qua các hình thái, mà trong điều kiện lịch sử nhất định còn có thể **bỏ qua** một vài hình thái. Đây là cơ sở lý luận cho con đường quá độ bỏ qua chế độ tư bản ở Việt Nam."},{"id":"C3-191","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nguồn gốc sâu xa của sự vận động và phát triển của các hình thái kinh tế - xã hội là gì?","opts":["Sự tăng lên không ngừng của năng suất lao động","Áp bức, bất công và mâu thuẫn giai cấp","Động cơ chính trị của các vĩ nhân, lãnh tụ","Mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất"],"ans":3,"ex":"Nguồn gốc sâu xa của sự vận động, phát triển các hình thái kinh tế – xã hội là **mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất**. Khi quan hệ sản xuất trở thành xiềng xích kìm hãm lực lượng sản xuất, mâu thuẫn được giải quyết qua cách mạng xã hội, thay thế phương thức sản xuất cũ. Mâu thuẫn giai cấp chỉ là biểu hiện về mặt xã hội của mâu thuẫn này."},{"id":"C3-192","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo quan điểm của triết học Mác - Lênin, nguyên nhân khách quan của đấu tranh giai cấp là gì?","opts":["Do một lý thuyết khoa học về giai cấp thúc đẩy quần chúng nhân dân nổi dậy","Do sự lôi kéo của một thủ lĩnh có uy tín trong nhân dân phát động và lãnh đạo","Do sự nghèo khổ của quần chúng nhân dân","Do mâu thuẫn giữa trình độ phát triển của lực lượng sản xuất xã hội với quan hệ sản xuất đã trở nên lỗi thời"],"ans":3,"ex":"Nguyên nhân khách quan, sâu xa của đấu tranh giai cấp là **mâu thuẫn giữa lực lượng sản xuất đã phát triển với quan hệ sản xuất lỗi thời**. Về mặt xã hội, mâu thuẫn đó biểu hiện thành mâu thuẫn lợi ích giữa giai cấp bóc lột và bị bóc lột. Lý thuyết, thủ lĩnh hay sự nghèo khổ chỉ là yếu tố chủ quan hoặc biểu hiện bề ngoài."},{"id":"C3-193","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhà nước trong thời kỳ quá độ lên chủ nghĩa xã hội là nhà nước nào?","opts":["Nhà nước dân chủ cộng hòa","Nhà nước dân chủ tư sản","Nhà nước chuyên chính vô sản","Nhà nước dân chủ nhân dân"],"ans":2,"ex":"Theo C. Mác trong **Phê phán Cương lĩnh Gô-ta**, giữa xã hội tư bản và xã hội cộng sản là thời kỳ quá độ chính trị, và nhà nước của thời kỳ ấy là **chuyên chính cách mạng của giai cấp vô sản**. V.I. Lênin phát triển: nhà nước chuyên chính vô sản là nhà nước \"nửa nhà nước\", dân chủ cho đa số nhân dân."},{"id":"C3-194","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Xu hướng phát triển của nhà nước trong chủ nghĩa cộng sản là gì?","opts":["Củng cố vững chắc quyền lực giai cấp","Chuyển hóa thành nhà nước cộng sản","Chuyển hóa thành nhà nước toàn cầu","Nhà nước tự tiêu vong"],"ans":3,"ex":"Nhà nước là sản phẩm của mâu thuẫn giai cấp không thể điều hòa. Khi giai cấp và đấu tranh giai cấp bị xóa bỏ trong xã hội cộng sản chủ nghĩa, cơ sở tồn tại của nhà nước mất đi, nhà nước sẽ **tự tiêu vong** (Ph. Ăngghen, V.I. Lênin trong **Nhà nước và cách mạng**). Không có \"nhà nước cộng sản\" hay \"nhà nước toàn cầu\"."},{"id":"C3-195","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Điền từ còn thiếu vào chỗ trống (...) trong câu sau: “Chủ nghĩa duy vật lịch sử coi con người là một bộ phận của giới tự nhiên, còn giới tự nhiên là…”?","opts":["Đối tượng chinh phục của con người","Đối tượng cải tạo của con người","Thân thể vô cơ của con người","Đối tượng vô cơ của con người"],"ans":2,"ex":"C. Mác, trong **Bản thảo kinh tế – triết học 1844**, coi giới tự nhiên là **\"thân thể vô cơ của con người\"**: con người là bộ phận của tự nhiên và sống nhờ trao đổi chất với tự nhiên. Từ đó, con người phải bảo vệ tự nhiên như bảo vệ chính mình; coi tự nhiên chỉ là đối tượng chinh phục là phiến diện."},{"id":"C3-196","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, hoạt động nào dưới đây không nằm trong khái niệm sản xuất?","opts":["Sản xuất vật chất","Sản xuất tinh thần","Sản xuất ra bản thân con người","Hoạt động tích trữ của cải"],"ans":3,"ex":"Theo chủ nghĩa duy vật lịch sử, **sản xuất** gồm ba loại thống nhất: **sản xuất vật chất**, **sản xuất tinh thần** và **sản xuất ra bản thân con người** (tái sản xuất con người), trong đó sản xuất vật chất là cơ sở. **Tích trữ của cải** không phải là hoạt động sản xuất vì không tạo ra giá trị mới."},{"id":"C3-197","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Yếu tố nào dưới đây không thuộc phương thức sản xuất?","opts":["Lực lượng sản xuất","Quan hệ xã hội","Quan hệ sản xuất","Lực lượng sản xuất và quan hệ sản xuất"],"ans":1,"ex":"**Phương thức sản xuất** là cách thức con người tiến hành sản xuất vật chất ở mỗi giai đoạn lịch sử, là sự thống nhất giữa **lực lượng sản xuất** và **quan hệ sản xuất** tương ứng. \"Quan hệ xã hội\" là khái niệm rộng hơn nhiều (chính trị, pháp quyền, gia đình...), không phải yếu tố cấu thành phương thức sản xuất."},{"id":"C3-198","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, trình độ của lực lượng sản xuất thể hiện ở nội dung nào?","opts":["Trình độ công cụ lao động và người lao động","Trình độ tổ chức và phân công lao động xã hội","Trình độ ứng dụng khoa học và công nghệ vào sản xuất","Tất cả các phương án đều đúng"],"ans":3,"ex":"Trình độ của **lực lượng sản xuất** thể hiện ở trình độ của **công cụ lao động** và **người lao động** (kỹ năng, kinh nghiệm, tri thức), trình độ **tổ chức và phân công lao động** xã hội, trình độ **ứng dụng khoa học – công nghệ** vào sản xuất. Ba phương án A, B, C đều đúng nên chọn D."},{"id":"C3-199","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"C. Mác viết: “Cái cối xay quay bằng tay đưa lại cho xã hội phong kiến, cái cối xay chạy bằng hơi nước đưa lại cho xã hội có nhà tư bản công nghiệp”. Luận điểm trên của C. Mác nhấn mạnh vai trò của yếu tố nào?","opts":["Quan hệ sản xuất","Tư liệu sản xuất","Công cụ lao động","Đối tượng lao động"],"ans":2,"ex":"Trong **Sự khốn cùng của triết học** (1847), C. Mác dùng hình ảnh cối xay tay và cối xay hơi nước để nhấn mạnh vai trò của **công cụ lao động**: đây là yếu tố động nhất, cách mạng nhất của lực lượng sản xuất, là thước đo trình độ chinh phục tự nhiên và tiêu chí phân biệt các thời đại kinh tế. Công cụ lao động là bộ phận của tư liệu sản xuất."},{"id":"C3-200","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tính chất của lực lượng sản xuất là tính chất nào dưới đây?","opts":["Tính chất hiện đại và tính chất cá nhân","Tính chất cá nhân và tính chất xã hội hoá","Tính chất xã hội hoá và tính chất hiện đại","Tính chất xã hội và tính chất hiện đại"],"ans":2,"ex":"Theo đáp án gốc, tính chất của lực lượng sản xuất được nêu là **tính chất xã hội hóa và tính chất hiện đại**, phản ánh xu hướng lực lượng sản xuất ngày càng xã hội hóa và hiện đại hóa. Cần lưu ý: giáo trình trình bày quy luật quan hệ sản xuất phù hợp với **tính chất và trình độ** của lực lượng sản xuất, trong đó tính chất gồm **tính chất cá nhân** và **tính chất xã hội hóa**."},{"id":"C3-201","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo C. Mác và Ph. Ăngghen thì quá trình thay thế các hình thức sở hữu tư liệu sản xuất phụ thuộc vào yếu tố nào?","opts":["Trình độ của công cụ sản xuất","Trình độ kỹ thuật sản xuất","Trình độ phân công lao động xã hội","Trình độ phát triển của lực lượng sản xuất"],"ans":3,"ex":"C. Mác và Ph. Ăngghen chỉ ra rằng sự thay thế các hình thức **sở hữu tư liệu sản xuất** (công xã nguyên thủy, chiếm hữu nô lệ, phong kiến, tư bản...) phụ thuộc vào **trình độ phát triển của lực lượng sản xuất**. Đây là nội dung quy luật quan hệ sản xuất phù hợp với trình độ lực lượng sản xuất. Công cụ, kỹ thuật, phân công lao động chỉ là những bộ phận của trình độ đó."},{"id":"C3-202","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhân tố nào trong kiến trúc thượng tầng có tác động trực tiếp nhất và mạnh mẽ nhất tới cơ sở hạ tầng kinh tế của xã hội?","opts":["Đạo đức","Tôn giáo","Nhà nước","Giáo hội"],"ans":2,"ex":"Trong **kiến trúc thượng tầng** của xã hội có giai cấp, **nhà nước** là yếu tố có vai trò đặc biệt quan trọng, tác động trực tiếp và mạnh mẽ nhất tới cơ sở hạ tầng, vì nó là công cụ quyền lực tập trung của giai cấp thống trị, sử dụng pháp luật, chính sách để củng cố, bảo vệ cơ sở kinh tế. Đạo đức, tôn giáo tác động gián tiếp, thông qua nhà nước, pháp luật."},{"id":"C3-203","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Theo chủ nghĩa duy vật lịch sử, sự phát triển của các hình thái kinh tế - xã hội trong lịch sử do yếu tố nào quy định?","opts":["Ý muốn chủ quan của con người","Sự phát triển của quan hệ sản xuất","Sự phát triển của lực lượng sản xuất","Tất cả các đáp án trên đều đúng"],"ans":2,"ex":"Theo chủ nghĩa duy vật lịch sử, sự phát triển của các hình thái kinh tế – xã hội là **quá trình lịch sử – tự nhiên**, xét đến cùng do **sự phát triển của lực lượng sản xuất** quy định. Lực lượng sản xuất phát triển làm quan hệ sản xuất thay đổi, kéo theo sự thay đổi của kiến trúc thượng tầng. Ý muốn chủ quan không quyết định được tiến trình lịch sử."},{"id":"C3-204","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Con đường quá độ lên chủ nghĩa xã hội ở Việt Nam được Đảng ta vận dụng sáng tạo theo hình thức nào trong tiến trình lịch sử - tự nhiên của xã hội loài người?","opts":["Phát triển theo tuần tự qua các hình thái kinh tế - xã hội","Phát triển theo xu hướng chung, tuần tự","Phát triển theo hướng “bỏ qua” một hoặc một vài hình thái kinh tế - xã hội để tiến lên hình thái kinh tế - xã hội cao hơn","Phát triển theo xu hướng không đồng đều"],"ans":2,"ex":"Vận dụng tư tưởng về khả năng **\"bỏ qua\"** trong quá trình lịch sử – tự nhiên, Đảng ta xác định con đường **quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa**, tức bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, nhưng tiếp thu, kế thừa thành tựu của nhân loại dưới chủ nghĩa tư bản."},{"id":"C3-205","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Cơ sở hình thành và phân chia giai cấp trong xã hội là do nguyên nhân nào?","opts":["Chiếm hữu tư nhân về tư liệu sản xuất","Chiến tranh của các bộ lạc","Sản xuất nông nghiệp phát triển","Tất cả các đáp án trên đều đúng"],"ans":0,"ex":"Nguyên nhân trực tiếp dẫn tới sự hình thành giai cấp là sự ra đời của **chế độ tư hữu về tư liệu sản xuất**; nguyên nhân sâu xa là sự phát triển của lực lượng sản xuất làm xuất hiện sản phẩm dư thừa. Chiến tranh bộ lạc hay nông nghiệp phát triển chỉ là điều kiện, cách thức, không phải cơ sở hình thành và phân chia giai cấp."},{"id":"C3-206","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"“Cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng” thuộc khái niệm nào dưới đây?","opts":["Cải cách xã hội","Đảo chính","Đấu tranh giai cấp","Liên minh giai cấp"],"ans":2,"ex":"Theo V.I. Lênin, **đấu tranh giai cấp** là cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng. Đấu tranh giai cấp là **động lực** phát triển của xã hội có giai cấp. Cải cách, đảo chính, liên minh giai cấp là những khái niệm khác."},{"id":"C3-207","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Sự ra đời của giai cấp trong lịch sử có ý nghĩa như thế nào?","opts":["Là một bước tiến của lịch sử","Là một sai lầm của lịch sử","Là một phạm trù của lịch sử","Là một dấu ấn của lịch sử"],"ans":0,"ex":"Sự ra đời của giai cấp là một **bước tiến của lịch sử**, gắn với sự phát triển của lực lượng sản xuất và sản phẩm dư thừa, cho phép phân công lao động trí óc – chân tay, thúc đẩy văn minh. Tuy giai cấp gắn với bóc lột, nhưng xét về mặt lịch sử, đó là bước phát triển tất yếu, không phải sai lầm; giai cấp cũng sẽ mất đi khi điều kiện tồn tại của nó không còn."},{"id":"C3-208","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Nhiệm vụ trọng tâm của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là gì?","opts":["Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội","Là cuộc đấu tranh giữa các nhân tố thúc đẩy đất nước theo định hướng xã hội chủ nghĩa với các nhân tố tác động nhằm cản trở đất nước theo mục tiêu độc lập dân tộc và chủ nghĩa xã hội","Xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh","Tất cả các đáp án"],"ans":3,"ex":"Đấu tranh giai cấp trong thời kỳ quá độ ở Việt Nam có nội dung mới: đó là cuộc đấu tranh giữa các nhân tố thúc đẩy với các nhân tố cản trở con đường **độc lập dân tộc và chủ nghĩa xã hội**, nhằm thực hiện thắng lợi mục tiêu ấy và xây dựng xã hội **dân giàu, nước mạnh, dân chủ, công bằng, văn minh**. Các phương án A, B, C đều là nội dung đúng."},{"id":"C3-209","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"“Sự biến đổi có tính chất bước ngoặt và căn bản về chất trong mọi lĩnh vực đời sống xã hội, là phương thức thay thế hình thái kinh tế xã hội này bằng hình thái kinh tế - xã hội cao hơn” được gọi là gì?","opts":["Cách mạng khoa học và công nghệ","Cách mạng xã hội","Đấu tranh giai cấp","Tất cả các phương án trên đều sai"],"ans":1,"ex":"**Cách mạng xã hội** theo nghĩa rộng là sự biến đổi có tính bước ngoặt, căn bản về chất trong mọi lĩnh vực đời sống xã hội, là **phương thức thay thế hình thái kinh tế – xã hội** này bằng hình thái kinh tế – xã hội cao hơn. Cách mạng khoa học – công nghệ chỉ diễn ra trong lĩnh vực lực lượng sản xuất; đấu tranh giai cấp là nguyên nhân, động lực."},{"id":"C3-210","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"“Việc lật đổ một chế độ chính trị đã lỗi thời và thiết lập một chế độ chính trị tiến bộ hơn của giai cấp cách mạng” được gọi là gì?","opts":["Cách mạng xã hội","Cách mạng khoa học và công nghệ","Đấu tranh giai cấp","Tất cả các phương án trên đều sai"],"ans":0,"ex":"**Cách mạng xã hội** theo **nghĩa hẹp** là việc lật đổ một chế độ chính trị đã lỗi thời và thiết lập một chế độ chính trị tiến bộ hơn của giai cấp cách mạng. Vấn đề cơ bản của mọi cuộc cách mạng là vấn đề **chính quyền nhà nước**. Đấu tranh giai cấp là khái niệm rộng hơn, đỉnh cao của nó mới dẫn tới cách mạng xã hội."},{"id":"C3-211","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"“Quá trình phát triển diễn ra một cách tuần tự, dần dần từng bộ phận, từng lĩnh vực của đời sống xã hội” thuộc khái niệm nào dưới đây?","opts":["Cách mạng xã hội","Đấu tranh giai cấp","Tiến hóa xã hội","Đảo chính"],"ans":2,"ex":"**Tiến hóa xã hội** là quá trình phát triển diễn ra **tuần tự, dần dần** từng bộ phận, từng lĩnh vực của đời sống xã hội, tích lũy biến đổi về lượng. Đối lập với nó là **cách mạng xã hội**, biến đổi căn bản về chất. Hai hình thức này có quan hệ biện chứng, thể hiện quy luật lượng – chất trong lĩnh vực xã hội."},{"id":"C3-212","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Đâu là nhận định đúng về ý thức xã hội thông thường?","opts":["Những tri thức, quan niệm được hình thành trực tiếp trong các hoạt động hàng ngày của con người; chưa được hệ thống hoá, chưa được hợp thức và khái quát hoá","Những tri thức, quan niệm được hình thành trực tiếp trong các hoạt động hàng ngày của con người; đã được tổng hợp, hệ thống hoá và khái quát hoá thành các học thuyết","Những tư tưởng, quan điểm của con người trong cuộc sống, đã được tổng hợp, hệ thống hoá và khái quát hoá thành các học thuyết","Những tư tưởng, quan điểm của con người trong cuộc sống; chưa được hệ thống hoá, chưa được hợp thức và khái quát hoá"],"ans":0,"ex":"**Ý thức xã hội thông thường** là những tri thức, quan niệm hình thành trực tiếp trong hoạt động hằng ngày của con người, **chưa được hệ thống hóa, khái quát hóa**. Đối lập với nó là **ý thức lý luận** (B, C), đã được khái quát thành học thuyết. Phương án D diễn đạt \"tư tưởng, quan điểm\" chưa sát với nội hàm \"tri thức, quan niệm\" hình thành trực tiếp."},{"id":"C3-213","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Mối quan hệ giữa ý thức xã hội và ý thức cá nhân là biểu hiện mối quan hệ giữa?","opts":["Nội dung và hình thức","Nguyên nhân và kết quả","Bản chất và hiện tượng","Cái chung và cái riêng"],"ans":3,"ex":"**Ý thức xã hội** tồn tại thông qua ý thức của các cá nhân nhưng không phải là phép cộng giản đơn của chúng; ý thức cá nhân mang những đặc điểm riêng nhưng đều chịu sự chi phối của ý thức xã hội. Đây là biểu hiện của quan hệ **cái chung – cái riêng**: cái chung tồn tại trong cái riêng, cái riêng phong phú hơn cái chung."},{"id":"C3-214","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tiền đề xuất phát của quan điểm duy vật lịch sử về con người mà triết học Mác - Lênin nghiên cứu là gì?","opts":["Con người cụ thể","Con người trừu tượng","Con người hiện thực","Con người lý tưởng"],"ans":2,"ex":"**Con người hiện thực** là tiền đề xuất phát của chủ nghĩa duy vật lịch sử: theo C. Mác và Ph. Ăngghen trong **Hệ tư tưởng Đức**, đó là những cá nhân hiện thực, hoạt động của họ và những điều kiện vật chất của đời sống họ. Đây là điểm khác căn bản với con người trừu tượng của Phoiơbắc hay con người lý tưởng của chủ nghĩa duy tâm."},{"id":"C3-215","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Muốn nhận thức bản chất con người theo quan niệm của triết học Mác - Lênin cần thông qua nội dung nào dưới đây?","opts":["Thông qua tư tưởng của con người","Thông qua hoạt động sản xuất vật chất của con người","Thông qua các quan hệ hiện thực của con người","Thông qua cống hiến xã hội của con người"],"ans":1,"ex":"Theo đáp án gốc, muốn nhận thức bản chất con người cần thông qua **hoạt động sản xuất vật chất**, vì lao động sản xuất là hoạt động đặc trưng tạo nên con người và là cơ sở của mọi quan hệ xã hội. Tuy nhiên, theo luận điểm \"tổng hòa những quan hệ xã hội\", cách diễn đạt đầy đủ hơn là thông qua **các quan hệ hiện thực** của con người, mà quan hệ sản xuất là nền tảng."},{"id":"C3-216","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Trong các đặc trưng của giai cấp thì đặc trưng nào bao trùm và chi phối các đặc trưng khác?","opts":["Khác nhau về quan hệ sở hữu tư liệu sản xuất của xã hội","Khác nhau về vai trò trong tổ chức, quản lý sản xuất","Khác nhau về cách thức hưởng thụ phần của cải xã hội","Khác nhau về địa vị trong phương thức sản xuất"],"ans":0,"ex":"Theo định nghĩa giai cấp của V.I. Lênin trong **Sáng kiến vĩ đại** (1919), giai cấp khác nhau về địa vị trong hệ thống sản xuất, về **quan hệ đối với tư liệu sản xuất**, về vai trò tổ chức quản lý và cách thức hưởng thụ của cải. Trong đó, đặc trưng về **quan hệ sở hữu tư liệu sản xuất** là chủ yếu, quyết định các đặc trưng còn lại."},{"id":"C3-217","chapter":3,"topic":"Chương 3: Chủ nghĩa duy vật lịch sử","q":"Tiêu chuẩn quan trọng nhất để đánh giá tiến bộ xã hội là?","opts":["Sự trong sạch, vững mạnh của bộ máy nhà nước","Sự phát triển của phương thức sản xuất","Trình độ văn hóa của người dân","Chất lượng cuộc sống của người dân"],"ans":3,"ex":"Theo đáp án gốc, **chất lượng cuộc sống của người dân** được xem là tiêu chuẩn quan trọng nhất đánh giá tiến bộ xã hội, vì mục đích cao nhất của phát triển là con người được phát triển toàn diện, hạnh phúc. Lưu ý: chủ nghĩa duy vật lịch sử cũng coi sự phát triển của **lực lượng sản xuất, phương thức sản xuất** là tiêu chuẩn khách quan, cơ bản của tiến bộ xã hội."}];